window.BASAIR_QUESTIONS=window.BASAIR_QUESTIONS.concat([{"id":"s6-154","number":154,"surah":6,"verses":[25],"verseLabel":"الأنعام: 25","question":"ما دلالة إظهار وصفهم في قوله تعالى: ﴿يقول الذين كفروا﴾، دون: يقولون؟","answer":"أظهر ﴿الذين كفروا﴾ موضع الضمير ليسجل أن قولهم ثمرة كفرهم لا نتيجة نظر منصف، ويذمهم بالوصف الذي كشفه استماعهم وجدالهم. كما يمنع الإظهار توهم أن كل من جاء أو استمع قال مقالتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص432–450.","url":""}]},{"id":"s6-155","number":155,"surah":6,"verses":[25],"verseLabel":"الأنعام: 25","question":"ما دلالة إشارتهم إلى القرآن بقولهم: ﴿إن هذا إلا أساطير الأولين﴾؟","answer":"أشاروا بـ﴿هذا﴾ إلى القرآن الحاضر الذي يسمعونه، لكنهم تجنبوا اسمه ووصفه بالوحي تحقيرًا وعنادًا، ثم ألصقوا به حكم الأساطير. والمفارقة أن حضور المتلو وقيام حجته لم يمنعاهم من دعوى أنه حكايات منقولة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص432–450.","url":""}]},{"id":"s6-156","number":156,"surah":6,"verses":[25],"verseLabel":"الأنعام: 25","question":"ما دلالة القصر في قولهم: ﴿إن هذا إلا أساطير الأولين﴾؟","answer":"حصروا القرآن كله في أساطير السابقين، فنفوا عنه الوحي والحق والهداية نفيًا جازمًا. ويكشف هذا القصر شدة عنادهم؛ إذ لم يكتفوا بادعاء وجود قصص فيه، بل زعموا ألا حقيقة له وراء ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص432–450.","url":""}]},{"id":"s6-157","number":157,"surah":6,"verses":[25],"verseLabel":"الأنعام: 25","question":"ما دلالة اختيار لفظ ﴿أساطير﴾ في طعنهم بالقرآن؟","answer":"الأساطير ما سُطّر من أخبار وحكايات الأقدمين التي لا حقيقة لها في زعمهم؛ فاختاروا اللفظ لاتهام القرآن بأنه منقول قديم مختلق، لا وحي منزل. وإضافتها إلى ﴿الأولين﴾ تكمل دعوى الاقتباس من أمم مضت.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص432–450.","url":""}]},{"id":"s6-158","number":158,"surah":6,"verses":[26],"verseLabel":"الأنعام: 26","question":"ما دلالة الجمع بين الفعلين المتقاربين جرسًا: ﴿ينهون عنه وينأون عنه﴾؟","answer":"جمعوا بين إضلال غيرهم وابتعادهم بأنفسهم: ينهون الناس عن اتباع الحق، وينأون هم عنه. والتقارب الصوتي بين الفعلين يرسخ تقابل الحركتين، ويكشف أن شرهم لم يقف عند ضلالهم بل تعداه إلى إضلال الآخرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص451–458.","url":""}]},{"id":"s6-159","number":159,"surah":6,"verses":[26],"verseLabel":"الأنعام: 26","question":"إلى ماذا يعود الضمير في قوله تعالى: ﴿ينهون عنه وينأون عنه﴾؟","answer":"الأقرب في السياق عوده إلى القرآن الذي وصفوه بالأساطير، ويصح أن يعود إلى النبي ﷺ؛ لأن النهي عن القرآن واتباع الرسول متلازمان. وقد ذكر المصدر القولين، والمعنى في كليهما أنهم صدوا عن الوحي وصاحبه وابتعدوا عنهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص451–458.","url":""}]},{"id":"s6-160","number":160,"surah":6,"verses":[26],"verseLabel":"الأنعام: 26","question":"ما دلالة تكرار ﴿عنه﴾ بعد كل من ﴿ينهون﴾ و﴿ينأون﴾؟","answer":"أعيد الجار والمجرور ليتعلق بكل فعل مستقلًا، فيثبت أن صدهم للآخرين وابتعادهم بأنفسهم موجهان كلاهما إلى الحق نفسه. ولو قيل: ينهون وينأون عنه، لضعف استقلال كل جريمة في السمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص451–458.","url":""}]},{"id":"s6-161","number":161,"surah":6,"verses":[26],"verseLabel":"الأنعام: 26","question":"ما دلالة تقديم نهيهم الناس على نأيهم بأنفسهم؟","answer":"قُدم النهي لأن خطره متعدٍّ إلى غيرهم، فهو إضلال بعد الضلال، ولأنه امتداد مباشر لمجادلتهم وطعنهم السابق في القرآن. ثم ذُكر نأيهم ليكتمل وصف من يمنع الآخرين مما لم ينتفع به هو.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص451–458.","url":""}]},{"id":"s6-162","number":162,"surah":6,"verses":[26],"verseLabel":"الأنعام: 26","question":"ما دلالة القصر في قوله تعالى: ﴿وإن يهلكون إلا أنفسهم﴾؟","answer":"حصر عاقبة صدهم في أنفسهم؛ فهم يظنون أنهم يطفئون نور الوحي ويضرون الرسول والمؤمنين، والحقيقة أنهم لا يسوقون إلى الهلاك إلا ذواتهم. فالقصر يقلب تقديرهم للنتيجة ويطمئن إلى أن الحق لا تضره مكائدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص451–458.","url":""}]},{"id":"s6-163","number":163,"surah":6,"verses":[26],"verseLabel":"الأنعام: 26","question":"ما دلالة التعبير بـ﴿يهلكون﴾، دون: يضرون؟","answer":"الهلاك غاية الضرر وانتهاء الشيء إلى الفساد والضياع، فبين أن أثر كفرهم ليس أذى محدودًا بل خسارة النفس ومصيرها. واختيار المضارع يصور استمرارهم في صنع أسباب هلاكهم كلما نهوا ونأوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص451–458.","url":""}]},{"id":"s6-164","number":164,"surah":6,"verses":[26],"verseLabel":"الأنعام: 26","question":"ما دلالة ختم الآية بقوله تعالى: ﴿وما يشعرون﴾، دون: وما يعلمون؟","answer":"الشعور إدراك دقيق لما قد يخفى، فنفى عنهم حتى الإحساس الأول بأن سعيهم يرتد هلاكًا عليهم؛ أما العلم فأعم وقد يأتي بعد نظر واستدلال. والفاصلة تناسب هلاكًا يصنعونه لأنفسهم وهم غافلون عن بداياته وعاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص451–458.","url":""}]},{"id":"s6-165","number":165,"surah":6,"verses":[27],"verseLabel":"الأنعام: 27","question":"ما دلالة المضارع في قوله تعالى: ﴿ولو ترى﴾ مع أن الوقوف على النار مستقبل؟","answer":"استُعمل المضارع لاستحضار المشهد المستقبل كأنه يقع الآن أمام العين؛ فتحول العقيدة بالغيب إلى صورة حية يرى السامع حركتها ويسمع حسرتها. وهذا أبلغ في الإنذار من الإخبار المجرد عما سيقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص459–468.","url":""}]},{"id":"s6-166","number":166,"surah":6,"verses":[27],"verseLabel":"الأنعام: 27","question":"ما دلالة الماضي ﴿وُقفوا﴾ بعد المضارع ﴿ترى﴾؟","answer":"بعد أن استحضر ﴿ترى﴾ المشهد، جاء الماضي مع ﴿إذ﴾ ليصور الوقوف واقعًا مكتملًا متحققًا داخل ذلك المشهد؛ فكأن العين أدركتهم وقد أُحضروا وحُبسوا على النار. والجمع بين الزمنين يحقق المستقبل ويجعله مشاهدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص459–468.","url":""}]},{"id":"s6-167","number":167,"surah":6,"verses":[27],"verseLabel":"الأنعام: 27","question":"ما دلالة بناء ﴿وُقفوا﴾ للمفعول؟","answer":"يدل البناء للمفعول على أنهم أُوقفوا قسرًا وحُبسوا للمعاينة والحساب، لا أنهم اختاروا الوقوف؛ فالمشهد مشهد اقتدار عليهم وذهاب حريتهم. ولم يحتج إلى ذكر الموقِف لأن سلطان الله في ذلك اليوم معلوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص459–468.","url":""}]},{"id":"s6-168","number":168,"surah":6,"verses":[27],"verseLabel":"الأنعام: 27","question":"ما دلالة قوله تعالى: ﴿وُقفوا على النار﴾، دون: عند النار أو أمامها؟","answer":"تفيد ﴿على﴾ إشرافهم المباشر على النار واطلاعهم عليها ومعاينتهم حقيقتها، كأنهم على حافتها لا يحول بينهم وبينها شيء. وهذا أشد تهويلًا من مجرد الوجود عند مكانها أو أمامها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص459–468.","url":""}]},{"id":"s6-169","number":169,"surah":6,"verses":[27],"verseLabel":"الأنعام: 27","question":"ما دلالة حذف جواب ﴿لو﴾ في قوله تعالى: ﴿ولو ترى إذ وُقفوا على النار﴾؟","answer":"حُذف الجواب لتهويل المشهد؛ أي لرأيت أمرًا عظيمًا لا يحيط به وصف، فتذهب نفس السامع في تصوره كل مذهب. وما تلا الشرط من تمنّيهم الرجعة يفتح جانبًا من ذلك الهول دون أن يحصره.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص459–468.","url":""}]},{"id":"s6-170","number":170,"surah":6,"verses":[27],"verseLabel":"الأنعام: 27","question":"ما دلالة حذف الجهة في قولهم: ﴿يا ليتنا نرد﴾؟","answer":"الجهة معلومة، أي نُرد إلى الدنيا، فحُذفت لشدة حضورها في الموقف ولتتجه العناية إلى أصل الرجعة التي صارت أمنيتهم الكبرى. وفي البناء للمفعول إقرار ضمني بأن ردهم ليس بأيديهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص459–468.","url":""}]},{"id":"s6-171","number":171,"surah":6,"verses":[27],"verseLabel":"الأنعام: 27","question":"ما دلالة التعبير بـ﴿نُرد﴾، دون: نرجع؟","answer":"﴿نُرد﴾ مبني للمفعول، فيصورهم مطلوبين إلى قوة تعيدهم بعد أن صار أمرهم إلى غيرهم، أما الرجوع فقد يوهم حركة تصدر باختيارهم. فاللفظ أنسب بذلهم وعجزهم بين يدي الحكم الإلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص459–468.","url":""}]},{"id":"s6-172","number":172,"surah":6,"verses":[27],"verseLabel":"الأنعام: 27","question":"ما دلالة ذكر الربوبية في قولهم: ﴿ولا نكذب بآيات ربنا﴾؟","answer":"لمّا عاينوا العذاب أقروا بأن الآيات صادرة عن ربهم المالك المربي، واستحضروا وصف الربوبية استرحامًا واعترافًا بما أنكروه في الدنيا. والمفارقة أن هذا الانتساب جاء بعد انقضاء زمن الانتفاع بالآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص459–468.","url":""}]},{"id":"s6-173","number":173,"surah":6,"verses":[27],"verseLabel":"الأنعام: 27","question":"ما دلالة قولهم: ﴿ونكون من المؤمنين﴾، دون: ونؤمن؟","answer":"تمنوا أن يصيروا داخلين في جماعة المؤمنين متصفين بالإيمان صفةً ثابتة، لا أن يقع منهم فعل تصديق عابر. فالتعبير يرسم تبدل الهوية والحال الذي يدعونه بعد الرجعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص459–468.","url":""}]},{"id":"s6-174","number":174,"surah":6,"verses":[28],"verseLabel":"الأنعام: 28","question":"ما دلالة الإضراب بقوله تعالى: ﴿بل بدا لهم ما كانوا يخفون من قبل﴾ بعد تمنّيهم الرجعة؟","answer":"أضرب عن ظاهر أمنيتهم ليكشف باعثها الحقيقي: لم ينشأ قولهم عن إيمان راسخ، وإنما عن انكشاف ما أخفوه ومعاينة العاقبة. ولذلك بيّن بعدها أنهم لو رُدوا لعادوا إلى ما نُهوا عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص469–481.","url":""}]},{"id":"s6-175","number":175,"surah":6,"verses":[28],"verseLabel":"الأنعام: 28","question":"ما دلالة التعبير بـ﴿بدا لهم﴾، دون: ظهر لهم؟","answer":"البُدوّ ظهور أمر بعد خفائه مع انكشافه للناظر، فناسب ما كان يخطر في نفوسهم ويكتمونه ثم صار يوم القيامة حاضرًا معترفًا به. أما مطلق الظهور فلا يؤدي وحده هذه المقابلة الدقيقة بين البدو والإخفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص469–481.","url":""}]},{"id":"s6-176","number":176,"surah":6,"verses":[28],"verseLabel":"الأنعام: 28","question":"ما الذي يشمله قوله تعالى: ﴿ما كانوا يخفون من قبل﴾؟","answer":"ذكر المفسرون وجوهًا يشملها اللفظ: ما أخفوه من قبائح ومعاصٍ فظهرت في صحفهم وشهادة جوارحهم، وما كتموه من معرفة الحق، وما كان يعرض في نفوسهم من الإيمان ثم يكابرون فيه. واتساع الموصول ﴿ما﴾ يسمح بهذه المعاني، وجامعها انكشاف المستور يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص469–481.","url":""}]},{"id":"s6-177","number":177,"surah":6,"verses":[28],"verseLabel":"الأنعام: 28","question":"ما دلالة تقييد الإخفاء بقوله تعالى: ﴿من قبل﴾؟","answer":"عيّن الظرف زمن الإخفاء السابق، وهو حياتهم الدنيا، وقابله بزمن البدو والانكشاف في الآخرة. فقرر أن ما أعلنوه عند المعاينة لم ينشأ يومئذ، بل كانت مقدماته معلومة لهم من قبل ثم كتموها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص469–481.","url":""}]},{"id":"s6-178","number":178,"surah":6,"verses":[28],"verseLabel":"الأنعام: 28","question":"ما دلالة الجزم بعودتهم في قوله تعالى: ﴿ولو ردوا لعادوا لما نهوا عنه﴾ بعد معاينة النار؟","answer":"لأن الله يعلم رسوخ الكبر والجحود في نفوسهم، وأن أمنيتهم وليدة هول عابر لا تحول صادق؛ فلو عادوا إلى عالم الغيب وغابت عنهم المعاينة لعادت طباعهم القديمة. والشرط بـ﴿لو﴾ يكشف نتيجة أمر ممتنع على سبيل إقامة الحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص469–481.","url":""}]},{"id":"s6-179","number":179,"surah":6,"verses":[28],"verseLabel":"الأنعام: 28","question":"ما دلالة اللام في قوله تعالى: ﴿لعادوا لما نهوا عنه﴾؟","answer":"اللام في ﴿لما﴾ بمعنى الرجوع إلى الشيء، وأفادت استغراق عودهم فيما عهد عنهم من المنهيات؛ من الشرك والتكذيب وإنكار البعث وسائر القبائح. فالآية لا تخبر بزلة مفردة، بل برجوعهم إلى النهج الذي أصروا عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص469–481.","url":""}]},{"id":"s6-180","number":180,"surah":6,"verses":[28],"verseLabel":"الأنعام: 28","question":"ما دلالة التوكيد في قوله تعالى: ﴿وإنهم لكاذبون﴾؟","answer":"أكدت الجملة بـ﴿إن﴾ واللام لكشف كذب أمنيتهم ووعدهم بعدم التكذيب؛ فالله يحكم على حقيقة نفوسهم لا على كلام ولدته رهبة الموقف. والجملة الاسمية تثبت وصف الكذب فيهم وتفسر الجزم بأنهم سيعودون.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص469–481.","url":""}]},{"id":"s6-181","number":181,"surah":6,"verses":[29],"verseLabel":"الأنعام: 29","question":"ما دلالة الضمير في قولهم: ﴿إن هي إلا حياتنا الدنيا﴾ مع عدم تقدم مرجع صريح؟","answer":"الضمير عائد إلى الحياة المفهومة من المقام، وكأنها لشدة حضورها في أذهانهم لا تحتاج إلى ذكر سابق؛ إذ حصروا تصورهم كله في الحياة المشاهدة. ثم جاء الاسم الظاهر بعدها مفسرًا للضمير ومبينًا لما قصروه عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص482–487.","url":""}]},{"id":"s6-182","number":182,"surah":6,"verses":[29],"verseLabel":"الأنعام: 29","question":"ما دلالة القصر في قولهم: ﴿إن هي إلا حياتنا الدنيا﴾؟","answer":"حصروا جنس الحياة في الدنيا ونفوا أن تتبعها حياة أخرى، فجاء القصر تلخيصًا لمذهبهم المادي وإنكارهم البعث. ولذلك أعقبه النص بتصريحهم: ﴿وما نحن بمبعوثين﴾ ثم بمشهد وقوفهم على ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص482–487.","url":""}]},{"id":"s6-183","number":183,"surah":6,"verses":[29],"verseLabel":"الأنعام: 29","question":"ما دلالة وصف الحياة بـ﴿الدنيا﴾ في حكاية قول من ينكر الآخرة؟","answer":"﴿الدنيا﴾ تعني الأقرب، وتحمل كذلك معنى الدنو وقلة المنزلة؛ فتسميتها نفسها تلمح إلى حياة أخرى تقابلها وإلى أن هذه ليست الغاية، وإن كانوا قد حصروها فيها. فحكى القرآن قولهم بلفظ يهدم دعواهم من داخله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص482–487.","url":""}]},{"id":"s6-184","number":184,"surah":6,"verses":[29],"verseLabel":"الأنعام: 29","question":"ما دلالة الجملة الاسمية والباء في قولهم: ﴿وما نحن بمبعوثين﴾؟","answer":"الجملة الاسمية توحي بثبات النفي في اعتقادهم، ودخول الباء في خبرها يزيده توكيدًا؛ فلم يقولوا إن البعث مستبعد فحسب، بل رسخوا نفيه عن ذواتهم. وهذا التشديد يهيئ للمشهد الذي يضطرهم فيه الواقع إلى الإقرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص482–487.","url":""}]},{"id":"s6-185","number":185,"surah":6,"verses":[29],"verseLabel":"الأنعام: 29","question":"ما دلالة التعبير بـ﴿مبعوثين﴾، دون: عائدين أو أحياء؟","answer":"البعث هو الإنهاض والإرسال بعد الموت بأمر باعث، فيواجه أصل القضية التي أنكروها: قدرة الله على إخراجهم للحساب. أما العود أو الحياة فقد يدلان على مجرد حصول الحياة، ولا يبرزان فعل الإقامة القسرية للموقف والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص482–487.","url":""}]},{"id":"s6-186","number":186,"surah":6,"verses":[30],"verseLabel":"الأنعام: 30","question":"ما سرّ تكرار مشهد ﴿ولو ترى إذ وُقفوا﴾ مع اختلاف المتعلّق: ﴿على النار﴾ و﴿على ربهم﴾؟","answer":"المشهد الأول يريهم عاقبة التكذيب ممثلة في النار فتنبعث أمنية الرجوع، والثاني ينقلهم إلى الوقوف للحساب أمام حكم ربهم فيُنتزع منهم الإقرار بالحق. فالتكرار ليس إعادة، بل تصعيد من معاينة الجزاء إلى مواجهة المالك الذي أنكرو لقاءه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص488–500.","url":""}]},{"id":"s6-187","number":187,"surah":6,"verses":[30],"verseLabel":"الأنعام: 30","question":"كيف يُفهم قوله تعالى: ﴿وُقفوا على ربهم﴾، وما دلالة ﴿على﴾؟","answer":"ليس المراد فوقية مكان، بل أُوقفوا على حكم ربهم وحسابه، أو عُرضوا عليه واطلعوا على ما أعد لهم. فـ﴿على﴾ داخلة في معنى الوقوف على الأمر: بلوغه ومعاينته، والمقام مقام انكشاف سلطان الرب لا وصف مكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص488–500.","url":""}]},{"id":"s6-188","number":188,"surah":6,"verses":[30],"verseLabel":"الأنعام: 30","question":"ما الغرض من الاستفهام في قوله تعالى: ﴿أليس هذا بالحق﴾؟","answer":"الاستفهام تقريري توبيخي، يُلزمهم الاعتراف بالبعث والعذاب اللذين أنكروهما بعد أن صارا معاينين؛ ولذلك لم يملكوا إلا أن يقولوا ﴿بلى﴾. فالسؤال ليس لطلب علم، بل لإقامة الحجة عليهم من إقرارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص488–500.","url":""}]},{"id":"s6-189","number":189,"surah":6,"verses":[30],"verseLabel":"الأنعام: 30","question":"إلى ماذا يشير ﴿هذا﴾ في قوله تعالى: ﴿أليس هذا بالحق﴾؟","answer":"يشير إلى البعث والحساب والعذاب الحاضر الذي يشاهدونه، وهو ما سبق أن أنكروه بقولهم ﴿وما نحن بمبعوثين﴾. والإشارة للقريب تجعل الحقيقة التي جحدوها كأنها موضوعة أمام أعينهم لا سبيل إلى إنكارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص488–500.","url":""}]},{"id":"s6-190","number":190,"surah":6,"verses":[30],"verseLabel":"الأنعام: 30","question":"ما دلالة الباء في قوله تعالى: ﴿أليس هذا بالحق﴾؟","answer":"الباء زائدة في خبر ﴿ليس﴾ لتوكيد اتصاف المشار إليه بالحق؛ أي أليس هذا حقًا ثابتًا لا شك فيه؟ فجاءت تقوية الإثبات في مقابلة قوة إنكارهم السابق للبعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص488–500.","url":""}]},{"id":"s6-191","number":191,"surah":6,"verses":[30],"verseLabel":"الأنعام: 30","question":"ما دلالة جوابهم بـ﴿بلى﴾، دون: نعم؟","answer":"﴿بلى﴾ موضوعة لإبطال النفي السابق؛ فلما قيل ﴿أليس هذا بالحق﴾ أجابوا بما يرفع النفي ويثبت أنه الحق. أما ﴿نعم﴾ في أصل الاستعمال فتصدق مضمون السؤال المنفي، وقد توهم استمرار النفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص488–500.","url":""}]},{"id":"s6-192","number":192,"surah":6,"verses":[30],"verseLabel":"الأنعام: 30","question":"ما دلالة قسمهم بقولهم: ﴿بلى وربنا﴾ بعد إنكار البعث؟","answer":"لم يكتفوا بالإقرار، بل أقسموا بربهم تأكيدًا لما صار يقينًا بالمشاهدة؛ فبلغ انقلابهم من النفي المؤكد ﴿وما نحن بمبعوثين﴾ إلى الإثبات المقسَم عليه. واستحضار الربوبية اعتراف بسلطان من بعثهم وأوقفهم للحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص488–500.","url":""}]},{"id":"s6-193","number":193,"surah":6,"verses":[30],"verseLabel":"الأنعام: 30","question":"ما دلالة التعبير عن مباشرة العذاب بقوله تعالى: ﴿فذوقوا العذاب﴾؟","answer":"أصل الذوق اختبار الشيء بالفم، ثم استُعير لمباشرة الألم وإدراك أثره إدراكًا لا واسطة فيه؛ فكأن العذاب شيء يجدون طعمه بأنفسهم. والفاء تعقب إقرارهم بالجزاء، إذ لم يعد الاعتراف المتأخر مانعًا للعقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص488–500.","url":""}]},{"id":"s6-194","number":194,"surah":6,"verses":[30],"verseLabel":"الأنعام: 30","question":"ما دلالة قوله تعالى: ﴿بما كنتم تكفرون﴾، دون: بكفركم؟","answer":"الموصول ﴿ما﴾ يستوعب ما كانوا يكفرون به وما صدر عنهم من صور الكفر، و﴿كنتم تكفرون﴾ تصور الفعل المتجدد المستمر في حياتهم. أما المصدر ﴿كفركم﴾ فيسمّي الجريمة مجردة من هذا التفصيل الزمني والحركي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص488–500.","url":""}]},{"id":"s6-195","number":195,"surah":6,"verses":[31],"verseLabel":"الأنعام: 31","question":"ما دلالة التعبير بالماضي المؤكد في قوله تعالى: ﴿قد خسر﴾ مع أن الخسران الأخروي مستقبل؟","answer":"﴿قد﴾ مع الماضي تحقق وقوع الخسران حتى صُوّر المستقبل المقطوع به كأنه حدث وانتهى؛ فمن كذب بلقاء الله انعقد سبب خسارته من الآن. وفي الصيغة إنذار بأن النتيجة ليست احتمالًا ينتظر التجربة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص501–518.","url":""}]},{"id":"s6-196","number":196,"surah":6,"verses":[31],"verseLabel":"الأنعام: 31","question":"ما دلالة التعبير بـ﴿كذبوا بلقاء الله﴾، دون: كذبوا بالبعث؟","answer":"﴿لقاء الله﴾ لا يقتصر على الإحياء بعد الموت، بل يستحضر الوقوف بين يديه للحساب ومواجهة حكمه وجزائه؛ فهو أوقع في النفس وأشد صلة بالمشهد السابق ﴿وُقفوا على ربهم﴾. ومن ثم كان التكذيب به خسارة للإنسان نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص501–518.","url":""}]},{"id":"s6-197","number":197,"surah":6,"verses":[31],"verseLabel":"الأنعام: 31","question":"ما دلالة اجتماع ﴿حتى﴾ و﴿إذا﴾ في قوله تعالى: ﴿حتى إذا جاءتهم الساعة بغتة﴾؟","answer":"جعلت ﴿حتى﴾ مجيء الساعة غايةً لاستمرارهم في التكذيب والخسران، ثم افتتحت ﴿إذا﴾ الشرطية لحظة تحقق ذلك المجيء وما ترتب عليه من الحسرة. فانتقل الكلام من مسار طويل من الإنكار إلى مشهد وقوع حاسم مفاجئ.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص501–518.","url":""}]},{"id":"s6-198","number":198,"surah":6,"verses":[31],"verseLabel":"الأنعام: 31","question":"ما دلالة تسمية القيامة ﴿الساعة﴾؟","answer":"الساعة وقت محدود معلوم عند الله تقوم فيه القيامة، وتسميتها بذلك تشعر بقربها وسرعة مجيئها وحسمها للأعمار والتكليف، مهما طال انتظار الناس لها. وهي علم بالغلبة على ذلك اليوم الموعود.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص501–518.","url":""}]},{"id":"s6-199","number":199,"surah":6,"verses":[31],"verseLabel":"الأنعام: 31","question":"ما دلالة تقييد مجيء الساعة بقوله تعالى: ﴿بغتة﴾؟","answer":"﴿بغتة﴾ تعني فجأة من غير توقع ولا مهلة، فتصور الساعة وهي تواجه المكذبين وجهًا لوجه قبل أن يستدركوا تفريطهم. ولذلك أعقبها فورًا قولهم ﴿يا حسرتنا﴾؛ إذ انقضى زمن العمل وبقي انكشاف الخسارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص501–518.","url":""}]},{"id":"s6-200","number":200,"surah":6,"verses":[31],"verseLabel":"الأنعام: 31","question":"ما دلالة نداء الحسرة في قولهم: ﴿يا حسرتنا﴾؟","answer":"نزلوا الحسرة منزلة من يُنادى، كأنهم يقولون لها: احضري فهذا أوانك؛ إذ لم يبق ما يستغاث به سواها. وإضافتها إليهم في ﴿حسرتنا﴾ تشخص ندامتهم الخاصة على منفعة ضيعوها ولا سبيل إلى استدراكها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص501–518.","url":""}]},{"id":"s6-201","number":201,"surah":6,"verses":[31],"verseLabel":"الأنعام: 31","question":"ما دلالة قولهم: ﴿على ما فرطنا فيها﴾، وإلى ماذا يعود ضمير ﴿فيها﴾؟","answer":"التفريط هو التقصير بتضييع ما كان ينبغي حفظه، والضمير في ﴿فيها﴾ يعود إلى الحياة الدنيا؛ أي تحسروا على ما ضيعوه فيها من الإيمان والعمل الصالح والاستعداد للساعة. وقيل يعود إلى الساعة بمعنى التفريط في شأنها، والمعنيان يلتقيان في إضاعة الاستعداد لها في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص501–518.","url":""}]},{"id":"s6-202","number":202,"surah":6,"verses":[31],"verseLabel":"الأنعام: 31","question":"ما دلالة تصوير الذنوب أوزارًا يحملونها في قوله تعالى: ﴿وهم يحملون أوزارهم﴾؟","answer":"الوزر في أصله الحمل الثقيل، فاستعير للذنوب وما يترتب عليها من وبال وعقوبة، وجُسدت المعاصي أثقالًا ملازمة لا يستطيع أصحابها طرحها. فتجعل الصورة المعنى الأخروي محسوسًا منفّرًا يرى فيه القارئ أثر العمل على حامله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص501–518.","url":""}]},{"id":"s6-203","number":203,"surah":6,"verses":[31],"verseLabel":"الأنعام: 31","question":"ما سرّ تخصيص الظهور بحمل الأوزار في قوله تعالى: ﴿على ظهورهم﴾؟","answer":"الظهر هو الموضع المعتاد لحمل الأثقال، وهو أقدر الجسد عليها؛ فتخصيصه يبالغ في ثقل الأوزار حتى كأنها أحمال تقوس الظهور. كما تكني الصورة عن ملازمة الذنوب لأصحابها وتشهيرهم بها في موقف الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص501–518.","url":""}]},{"id":"s6-204","number":204,"surah":6,"verses":[31],"verseLabel":"الأنعام: 31","question":"ما دلالة الخاتمة ﴿ألا ساء ما يزرون﴾ وإعادة مادة الوزر؟","answer":"﴿ألا﴾ تنبه إلى فظاعة الحكم، و﴿ساء﴾ تفيد غاية الذم والتعجب من سوء ما يحملون. ثم أعاد ﴿يزرون﴾ مادة الوزر ليرد آخر الآية على صورتها السابقة، فيؤكد ثقل الحمل وقبحه وسوء عاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص501–518.","url":""}]},{"id":"s6-205","number":205,"surah":6,"verses":[32],"verseLabel":"الأنعام: 32","question":"ما دلالة قصر الحياة الدنيا على ﴿لعب ولهو﴾؟","answer":"القصر يبين حقيقة الدنيا إذا جُعلت غايةً وانقطعت عن عمل الآخرة: أعمال سريعة الزوال تشغل عما يبقى، كاللعب واللهو. ولا يدخل في الذم ما كان فيها طاعةً أو عملاً صالحًا؛ لأن قيمته متصلة بالدار الآخرة التي قررت الآية أنها خير للمتقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص519–529.","url":""}]},{"id":"s6-206","number":206,"surah":6,"verses":[32],"verseLabel":"الأنعام: 32","question":"ما دلالة تقديم ﴿اللعب﴾ على ﴿اللهو﴾؟","answer":"اللعب اشتغال بما لا ثمرة باقية له، وهو سبب يفضي إلى اللهو؛ أي الانشغال عما ينفع. فقدم السبب وما يبدأ به الإنسان، ثم ذُكرت عاقبته في القلب، كما أن اللعب أظهر في مراحل العمر الأولى ثم يشتد اللهو مع التعلق بالشهوات.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص519–529.","url":""}]},{"id":"s6-207","number":207,"surah":6,"verses":[32],"verseLabel":"الأنعام: 32","question":"ما دلالة اللام في قوله تعالى: ﴿وللدار الآخرة خير﴾؟","answer":"اللام لام الابتداء التي تقوي الحكم وتؤكده، وجاءت بعد واو الاستئناف لتقرر في مقابلة لعب الدنيا ولهوها أن الدار الآخرة هي الخير الحقيقي الثابت. فالتوكيد يناسب غفلة من آثر العاجل الزائل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص519–529.","url":""}]},{"id":"s6-208","number":208,"surah":6,"verses":[32],"verseLabel":"الأنعام: 32","question":"ما دلالة التعبير بـ﴿الدار الآخرة﴾ في مقابلة ﴿الحياة الدنيا﴾؟","answer":"وصف الدنيا بالحياة لأنها زمن حركة واختبار سريع الزوال، ووصف الآخرة بالدار لإفادة القرار والإقامة والاستقرار. فالمقابلة لا توازن حياتين متماثلتين، بل تكشف أن ما هنا مرحلة عابرة وأن هناك موطن البقاء والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص519–529.","url":""}]},{"id":"s6-209","number":209,"surah":6,"verses":[32],"verseLabel":"الأنعام: 32","question":"ما دلالة تقييد خير الآخرة بقوله تعالى: ﴿للذين يتقون﴾؟","answer":"لأن خير الآخرة لا يناله كل من بلغها، بل يختص بمن اتقى في الدنيا أسباب سخط الله؛ أما المكذب فله فيها العذاب. فجعلت الصلة التقوى طريق الانتفاع بالدار الباقية، وربطت المقارنة بالعمل لا بمجرد التمني.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص519–529.","url":""}]},{"id":"s6-210","number":210,"surah":6,"verses":[32],"verseLabel":"الأنعام: 32","question":"ما مناسبة الختم بقوله تعالى: ﴿أفلا تعقلون﴾ بعد الموازنة بين الدنيا والآخرة؟","answer":"لأن إدراك أن الباقي خير من الفاني قضية يهدي إليها العقل السليم؛ فوبخهم على ترك مقتضى عقولهم حين آثروا اللعب العابر على الدار الدائمة. وحُذف مفعول ﴿تعقلون﴾ ليشمل عقل حقيقة الدنيا وخيرية الآخرة وما يوجبه ذلك من التقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص519–529.","url":""}]},{"id":"s6-211","number":211,"surah":6,"verses":[33],"verseLabel":"الأنعام: 33","question":"ما دلالة ﴿قد﴾ في قوله تعالى: ﴿قد نعلم إنه ليحزنك الذي يقولون﴾ مع إحاطة علم الله؟","answer":"ليست ﴿قد﴾ للتقليل، بل للتحقيق والتسلية: علمُ الله بحزن رسوله ﷺ ثابت محقق ومستمر. وجاء المضارع لاستمرار العلم وتجدده بحسب متعلقه، فالمعنى أن ألمه حاضر في عناية ربه، وفي ذلك تثبيت له على الصبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص530–543.","url":""}]},{"id":"s6-212","number":212,"surah":6,"verses":[33],"verseLabel":"الأنعام: 33","question":"ما الفرق بين قوله هنا: ﴿قد نعلم إنه ليحزنك الذي يقولون﴾، وقوله في يس: ﴿فلا يحزنك قولهم﴾؟","answer":"في الأنعام مقام تسلية بعد طول جدالهم، فبدأ بإحاطة علم الله بحزنه ثم كشف حقيقة جحودهم؛ فكان الإخبار أرفق بقلبه. أما في يس فجاء النهي المباشر عقب استعجال المكذبين واستهزائهم، ثم عُلّل بعلم الله بسرهم وعلنهم؛ فاختلف الأسلوب باختلاف بناء السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص530–543، في المقارنة بيس: 76.","url":""}]},{"id":"s6-213","number":213,"surah":6,"verses":[33],"verseLabel":"الأنعام: 33","question":"ما دلالة إسناد الحزن إلى ﴿الذي يقولون﴾ بدل التصريح بتكذيبهم؟","answer":"الموصول يعم أقوالهم المؤذية من التكذيب والسخرية والاتهام، ويتركها لقبحها دون إعادة ألفاظها. كما أن صلته المضارعة ﴿يقولون﴾ تستحضر تجدد ما كان يصدر منهم، فناسب تجدد الحزن الذي علمه الله وسلّى رسوله عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص530–543.","url":""}]},{"id":"s6-214","number":214,"surah":6,"verses":[33],"verseLabel":"الأنعام: 33","question":"كيف يُفهم قوله تعالى: ﴿فإنهم لا يكذبونك﴾ مع تصريحهم بتكذيب الرسول ﷺ؟","answer":"المعنى أنهم لا يجدونه كاذبًا في أنفسهم، فقد عرفوا صدقه وأمانته، ولكنهم يجحدون بلسانهم آيات الله ظلمًا ومكابرة؛ وقُرئ أيضًا بالتخفيف بمعنى لا ينسبونك إلى الكذب في باطنهم. فالآية تسليه بأن الخصومة مع الحق الذي جاء به لا مع صدقه المعروف لديهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص530–543.","url":""}]},{"id":"s6-215","number":215,"surah":6,"verses":[33],"verseLabel":"الأنعام: 33","question":"ما دلالة الانتقال من ضمير النبي ﷺ في ﴿يكذبونك﴾ إلى الاسم الظاهر في ﴿بآيات الله يجحدون﴾؟","answer":"أظهر اسم الله ليرفع القضية من أذى شخصي للرسول إلى جحود بحجج الله نفسه، فيشتد ذمهم وتتم تسلية النبي ﷺ. كما أن إضافة الآيات إلى الله تعظم ما واجهوه بالإنكار وتبين صاحب الحق الذي اعتدوا عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص530–543.","url":""}]},{"id":"s6-216","number":216,"surah":6,"verses":[33],"verseLabel":"الأنعام: 33","question":"ما دلالة تقديم ﴿بآيات الله﴾ على ﴿يجحدون﴾؟","answer":"قدم الجار والمجرور للعناية بموضع جحودهم وللقصر بحسب السياق: ليس الذي ينالونه حقيقةً شخص الرسول ﷺ، وإنما تتجه مكابرتهم إلى آيات الله. وفي التقديم تعجيل بذكر الآيات المعظمة قبل تسجيل فعل الجحود.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص530–543.","url":""}]},{"id":"s6-217","number":217,"surah":6,"verses":[33],"verseLabel":"الأنعام: 33","question":"ما دلالة اختيار ﴿يجحدون﴾، دون: يكذبون؟","answer":"الجحود إنكار ما يعرفه الإنسان في باطنه، فهو أدق لحال من تيقن صدق الرسول والآيات ثم أنكرها مكابرةً. أما التكذيب فقد يقع ممن لم يثبت عنده صدق الخبر؛ فاختيار الجحود يسجل اجتماع المعرفة والظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص530–543.","url":""}]},{"id":"s6-218","number":218,"surah":6,"verses":[34],"verseLabel":"الأنعام: 34","question":"ما دلالة تنكير ﴿رسل﴾ في قوله تعالى: ﴿ولقد كذبت رسل من قبلك﴾؟","answer":"التنكير للتكثير والتعظيم؛ أي إن رسلًا كثيرين ذوي شأن سبق أن كُذبوا، فلست بدعًا في طريق الرسالة. وفي عدم تعيينهم تعميم للتسلية بسنة ماضية تشمل أممًا ورسالات متعددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص544–560.","url":""}]},{"id":"s6-219","number":219,"surah":6,"verses":[34],"verseLabel":"الأنعام: 34","question":"ما دلالة بناء ﴿كُذبت﴾ للمفعول؟","answer":"وجه العناية إلى ما وقع على الرسل من التكذيب لأنه موضع تسلية النبي ﷺ والقدوة في الصبر، أما المكذبون فتختلف أممهم ولا حاجة إلى تسميتهم. وفي حذف الفاعل تعميم لكل من سلك طريقهم في مقاومة الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص544–560.","url":""}]},{"id":"s6-220","number":220,"surah":6,"verses":[34],"verseLabel":"الأنعام: 34","question":"ما دلالة تعدية الصبر بـ﴿على﴾ في قوله تعالى: ﴿فصبروا على ما كذبوا وأوذوا﴾؟","answer":"تفيد ﴿على﴾ الاستعلاء والتمكن؛ فكأن التكذيب والأذى حمل ثقيل علاه الرسل وثبتوا فوقه فلم يغلبهم. والتعبير يرسم الصبر قوةً ومغالبةً لا مجرد انتظار سلبي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص544–560.","url":""}]},{"id":"s6-221","number":221,"surah":6,"verses":[34],"verseLabel":"الأنعام: 34","question":"ما دلالة الجمع بين التكذيب والأذى مع أن التكذيب لون من الأذى؟","answer":"خُص التكذيب لأنه أذى الرسالة ومعارضة للحق الذي جاءوا به، ثم عطف الأذى ليشمل ما زاد عليه من سخرية وتهديد واضطهاد بدني ومالي. فالجمع يستوعب الاعتداء على الدعوة والاعتداء على أصحابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص544–560.","url":""}]},{"id":"s6-222","number":222,"surah":6,"verses":[34],"verseLabel":"الأنعام: 34","question":"ما دلالة جعل مجيء النصر غايةً في قوله تعالى: ﴿حتى أتاهم نصرنا﴾؟","answer":"تفيد ﴿حتى﴾ استمرار صبرهم طوال زمن التكذيب والأذى إلى أن جاء النصر في وقته الذي قدره الله. فالنصر ثمرة موعودة للصبر، لكنه لا يعفي من احتمال الطريق حتى يبلغ أجله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص544–560.","url":""}]},{"id":"s6-223","number":223,"surah":6,"verses":[34],"verseLabel":"الأنعام: 34","question":"ما دلالة قوله تعالى: ﴿أتاهم نصرنا﴾، دون: نصرناهم؟","answer":"شخّص النصر كأنه قادم يبلغ الرسل بعد طول انتظار، وفي ذلك إظهار لتحقق الوعد ووصوله إليهم من عند الله. أما ﴿نصرناهم﴾ فتقرر الفعل، ولا ترسم حركة النصر وهو يأتي في اللحظة المقدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص544–560.","url":""}]},{"id":"s6-224","number":224,"surah":6,"verses":[34],"verseLabel":"الأنعام: 34","question":"ما مناسبة قوله تعالى: ﴿ولا مبدل لكلمات الله﴾ بعد وعد الرسل بالنصر؟","answer":"لأن نصر الرسل وعد من كلمات الله، وكلماته صدق وعدل لا يملك أحد تغييرها أو منع نفاذها؛ فالجملة ضمان للوعد السابق وتثبيت للنبي ﷺ. وتأخر النصر لا يعني تبدل الكلمة، بل وقوعها في الأجل الذي اقتضته الحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص544–560.","url":""}]},{"id":"s6-225","number":225,"surah":6,"verses":[34],"verseLabel":"الأنعام: 34","question":"ما دلالة جمع ﴿كلمات الله﴾ في قوله تعالى: ﴿ولا مبدل لكلمات الله﴾؟","answer":"الجمع يشمل ما تعدد من وعود الله وأحكامه وقضائه ووحيه، ومنها كلمته بنصر رسله؛ فلا يملك أحد تبديل شيء منها. وبهذا انتقل التثبيت من وعد واحد إلى قاعدة عامة تحمي كل ما أخبر الله به.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص544–560.","url":""}]},{"id":"s6-226","number":226,"surah":6,"verses":[34],"verseLabel":"الأنعام: 34","question":"ما دلالة قوله تعالى: ﴿ولقد جاءك من نبإ المرسلين﴾، دون: وجاءك نبأ المرسلين؟","answer":"أكدت اللام و﴿قد﴾ تحقق وصول الخبر المسلّي، و﴿من﴾ تبعيضية؛ أي جاءك بعض أخبار المرسلين مما يكفي للعبرة والتثبيت، لا استقصاء كل أحوالهم. واختير ﴿نبإ﴾ للخبر العظيم ذي الفائدة والعاقبة، لا لمجرد خبر عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص544–560.","url":""}]},{"id":"s6-227","number":227,"surah":6,"verses":[35],"verseLabel":"الأنعام: 35","question":"ما دلالة قوله تعالى: ﴿وإن كان كبر عليك إعراضهم﴾؟","answer":"الكِبَر هنا العِظم والمشقة؛ فصوّر إعراضهم حملًا يثقل على الرسول ﷺ لشدة حرصه على هدايتهم. والشرط يمهد لبيان أن هذا الحرص، مع شرفه، لا يغير سنة الاختيار ولا يوجب إجابة مقترحات المعاندين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص561–579.","url":""}]},{"id":"s6-228","number":228,"surah":6,"verses":[35],"verseLabel":"الأنعام: 35","question":"ما دلالة تفصيل المستحيل بقوله تعالى: ﴿نفقًا في الأرض أو سلمًا في السماء﴾؟","answer":"جمع طرفي المكان: غاية النزول في الأرض وغاية الصعود في السماء، ليبين أنك لو استطعت بذل أقصى ما يتصور في طلب آية توافق اقتراحهم فلن يكون الإيمان القسري هو سنة الله. والتفصيل يجسد استحالة ما علق به الشرط بدل أن يقال: إن استطعت آية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص561–579.","url":""}]},{"id":"s6-229","number":229,"surah":6,"verses":[35],"verseLabel":"الأنعام: 35","question":"ما دلالة تقديم النفق في الأرض على السلم في السماء؟","answer":"بدأ بالأرض لأنها موطن الإنسان الأقرب الذي يمشي عليه، فتصور طلب منفذ في أسفلها، ثم انتقل إلى السماء الأبعد والأعلى؛ فترقى المشهد من القريب المنخفض إلى البعيد المرتفع، واستوعب جهتي العالم المشاهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص561–579.","url":""}]},{"id":"s6-230","number":230,"surah":6,"verses":[35],"verseLabel":"الأنعام: 35","question":"ما المراد بـ﴿آية﴾ في قوله تعالى: ﴿فتأتيهم بآية﴾ مع أن القرآن آية؟","answer":"المراد آية حسية مخصوصة توافق ما اقترحوه تعنتًا، لا نفي كون القرآن أعظم آية قائمة؛ فقد رأوا آيات الوحي ثم طلبوا علامة من جنس ما يحددونه هم. وتنكير ﴿آية﴾ يحكي عدم تعيين طريق مشروع لها ويعم ما يتخيلونه من الخوارق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص561–579.","url":""}]},{"id":"s6-231","number":231,"surah":6,"verses":[35],"verseLabel":"الأنعام: 35","question":"ما دلالة قوله تعالى: ﴿ولو شاء الله لجمعهم على الهدى﴾، دون: لهداهم؟","answer":"﴿جمعهم على الهدى﴾ يصورهم جماعةً واحدة محمولة على طريق واحد لا تتخلف عنه، وهو أبلغ في معنى الإلجاء من مجرد حصول الهداية لبعضهم. لكن الحكمة اقتضت أن تكون الهداية مع الاختيار وقيام الحجة، لا جمعًا قسريًا يبطل التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص561–579.","url":""}]},{"id":"s6-232","number":232,"surah":6,"verses":[35],"verseLabel":"الأنعام: 35","question":"ما دلالة توجيه الخطاب للنبي ﷺ بقوله تعالى: ﴿فلا تكونن من الجاهلين﴾؟","answer":"ليس وصفًا له بالجهل، وحاشاه، بل تثبيت شديد له كيلا يحمله الحزن على طلب ما لم تقتضه حكمة الله أو الغفلة عن سنة الاختيار. والخطاب له تعليم للأمة بأن الحرص على الهداية لا يبيح تجاوز حدود الرسالة والسنن الإلهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص561–579.","url":""}]},{"id":"s6-233","number":233,"surah":6,"verses":[35],"verseLabel":"الأنعام: 35","question":"ما دلالة نون التوكيد في قوله تعالى: ﴿فلا تكونن﴾؟","answer":"شددت النون النهي لتقطع طريق الاسترسال مع الحزن، وتؤكد لزوم الوقوف عند علم الله وحكمته في الهداية. وقوة الصيغة تناسب شدة حرص النبي ﷺ، لا وقوع الجهل منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص561–579.","url":""}]},{"id":"s6-234","number":234,"surah":6,"verses":[36],"verseLabel":"الأنعام: 36","question":"كيف يُفهم قوله تعالى: ﴿إنما يستجيب الذين يسمعون﴾ مع أن المكذبين كانوا يسمعون التلاوة؟","answer":"السماع هنا سماع قبول وتدبر يفضي إلى الاستجابة، لا مجرد وصول الصوت إلى الأذن؛ لذلك قصر الاستجابة على أصحاب القلوب الحية. أما من سمع اللفظ وأغلق قلبه فشُبه بالموتى الذين لا يجيبون نداءً.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص580–591.","url":""}]},{"id":"s6-235","number":235,"surah":6,"verses":[36],"verseLabel":"الأنعام: 36","question":"ما دلالة اختيار ﴿يستجيب﴾، دون: يجيب أو يؤمن؟","answer":"الاستجابة قبول واعٍ للدعوة يتبعه انقياد، فهي أوسع من مجرد جواب باللسان، وتصور أثر الإيمان العملي لا التصديق المجرد وحده. وزيادة المبنى تلائم بذل النفس لقبول ما سمعت والانتقال به إلى الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص580–591.","url":""}]},{"id":"s6-236","number":236,"surah":6,"verses":[36],"verseLabel":"الأنعام: 36","question":"ما دلالة المضارع في قوله تعالى: ﴿يستجيب﴾؟","answer":"يصور الاستجابة فعلًا متجددًا كلما سمع أصحاب القلوب الحية آيةً أو دعوةً إلى الحق، فهي صفة مستمرة لا واقعة ماضية منقطعة. كما يستحضر أثر السماع أمام القارئ في الحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص580–591.","url":""}]},{"id":"s6-237","number":237,"surah":6,"verses":[36],"verseLabel":"الأنعام: 36","question":"ما دلالة مقابلة الذين يسمعون بـ﴿الموتى﴾ مع أن الحديث عن مكذبين أحياء؟","answer":"شبّه المكذبين بالموتى لأنهم فقدوا أثر الحياة المعنوية: يسمعون الصوت ولا يملكون استجابة القلب، كما لا يجيب الميت نداءً. وحُذفت أداة التشبيه حتى صار موت القلب كأنه حقيقتهم، فاشتدت المفارقة بينهم وبين السامعين المستجيبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص580–591.","url":""}]},{"id":"s6-238","number":238,"surah":6,"verses":[36],"verseLabel":"الأنعام: 36","question":"ما دلالة المضارع في قوله تعالى: ﴿والموتى يبعثهم الله﴾، دون: سيبعثهم؟","answer":"المضارع يقرر البعث بوصفه فعلًا داخلًا في قدرة الله وسنته المقطوع بها، ويستحضره كأنه مشاهد، فلا يحتاج إلى السين التي قد تبقيه بعيدًا في تصور السامع. وهو يشمل بعث الموتى حقيقةً، مع التلويح بأن إحياء القلوب المغلقة ليس بيد الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص580–591.","url":""}]},{"id":"s6-239","number":239,"surah":6,"verses":[36],"verseLabel":"الأنعام: 36","question":"ما دلالة إظهار اسم الله في قوله تعالى: ﴿يبعثهم الله﴾؟","answer":"أظهر الاسم ليقرر أن البعث من خصائص قدرة الله وحده، ويرد مباشرةً على منكريه، كما يعيد أمر هداية القلوب وإحياء الأجساد إلى مالكهما. ولو حُذف الفاعل لضعف هذا التسجيل العقدي في مقام الجدال.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص580–591.","url":""}]},{"id":"s6-240","number":240,"surah":6,"verses":[36],"verseLabel":"الأنعام: 36","question":"ما دلالة تقديم ﴿إليه﴾ في قوله تعالى: ﴿ثم إليه يرجعون﴾؟","answer":"تقديم الجار والمجرور يفيد الاختصاص: إلى الله وحده يكون المرجع والحساب، لا إلى من عبدوه أو احتموا به. و﴿ثم﴾ تفصل بين بعثهم وبين انتهاء أمرهم إلى موقف الجزاء، مع تهويل ما بعد البعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص580–591.","url":""}]},{"id":"s6-241","number":241,"surah":6,"verses":[37],"verseLabel":"الأنعام: 37","question":"ما دلالة طلبهم: ﴿لولا نُزّل عليه آية من ربه﴾ مع نزول القرآن؟","answer":"لم يريدوا مطلق دليل، فالقرآن قائم بينهم آيةً، وإنما طلبوا خارقة حسية من النوع الذي يقترحونه تعنتًا، كإنزال ملك أو قلب جبل. فصيغة التحضيض تحكي دعوى أن الحجة ناقصة، والواقع أن الخلل في استعدادهم للإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص592–603.","url":""}]},{"id":"s6-242","number":242,"surah":6,"verses":[37],"verseLabel":"الأنعام: 37","question":"ما دلالة صيغة ﴿نُزّل﴾ المشددة في حكاية طلبهم؟","answer":"التضعيف في ﴿نُزّل﴾ يقوي معنى التنزيل الذي يطلبونه ويصوره واقعًا عليه من جهة ربه، ملائمًا لإلحاحهم في طلب آية ظاهرة مخصوصة. وفي حكاية لفظهم كشف لتعنت من لا يكتفي بما نزل فعلًا من آيات القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص592–603.","url":""}]},{"id":"s6-243","number":243,"surah":6,"verses":[37],"verseLabel":"الأنعام: 37","question":"ما دلالة قولهم: ﴿من ربه﴾، دون: من الله؟","answer":"أضافوا الرب إلى الرسول ﷺ لأنهم يطالبونه بعلامة خاصة من الجهة التي يقول إنها ترعاه وتؤيده، وفي العبارة تعريض شاكّ بدعواه لا إقرار منهم بالربوبية. فجاء الرد باسم الجلالة صريحًا: ﴿قل إن الله قادر﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص592–603.","url":""}]},{"id":"s6-244","number":244,"surah":6,"verses":[37],"verseLabel":"الأنعام: 37","question":"ما دلالة الجواب بقوله تعالى: ﴿إن الله قادر على أن ينزل آية﴾ بدل إنزال الآية المقترحة؟","answer":"فرّق الجواب بين القدرة والحكمة: عدم إجابة اقتراحهم ليس عجزًا، فالله قادر على كل آية، لكنه لا ينزلها وفق أهوائهم؛ لأن الآية القاهرة قد يعقب تكذيبها الاستئصال، ولأن التكليف قائم على الاختيار لا الإلجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص592–603.","url":""}]},{"id":"s6-245","number":245,"surah":6,"verses":[37],"verseLabel":"الأنعام: 37","question":"ما دلالة التعبير بالقدرة في قوله تعالى: ﴿قادر على أن ينزل آية﴾، دون: سينزلها؟","answer":"أثبت القدرة المطلقة ونفى أن يكون ترك الإنزال عجزًا، لكنه لم يجعل مجرد القدرة وعدًا بالوقوع؛ فالتنزيل تابع للمشيئة والحكمة. كما أن ﴿على﴾ تؤكد تمكن القدرة من متعلقها، وتلوح بأن القادر على الآية قادر على العقوبة إن أعقبوها بالتكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص592–603.","url":""}]},{"id":"s6-246","number":246,"surah":6,"verses":[37],"verseLabel":"الأنعام: 37","question":"ما مناسبة الختم بقوله تعالى: ﴿ولكن أكثرهم لا يعلمون﴾؟","answer":"استدرك على إثبات القدرة بأن أكثر المقترحين يجهلون حكمة عدم إجابتهم وخطر نزول الآية القاهرة بعد التكذيب، فيجعلون عدم التنزيل حجة لهم وهو حجة عليهم. فالفاصلة ترد الطلب إلى علته: الجهل لا نقص البرهان.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص592–603.","url":""}]},{"id":"s6-247","number":247,"surah":6,"verses":[37],"verseLabel":"الأنعام: 37","question":"ما دلالة قوله تعالى: ﴿أكثرهم﴾، دون: كلهم؟","answer":"أثبت أن الجهل غالب في أصحاب الاقتراح، لكنه لم يسو بينهم جميعًا؛ ففيهم من يعلم وجه الحق ثم يكابر، أو من يمكن أن يهتدي. وهذه الدقة تمنع التعميم وتبين تفاوتهم في دوافع العداوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص592–603.","url":""}]},{"id":"s6-248","number":248,"surah":6,"verses":[38],"verseLabel":"الأنعام: 38","question":"ما دلالة اجتماع النفي و﴿من﴾ في قوله تعالى: ﴿وما من دابة في الأرض﴾؟","answer":"دخول ﴿من﴾ على النكرة في سياق النفي يفيد استغراق الجنس فردًا فردًا؛ فلا تخرج دابة واحدة من الحكم الآتي. فالصيغة أبلغ من ﴿وما دابة﴾ في تأكيد شمول علم الله وتدبيره لكل حي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص604–618.","url":""}]},{"id":"s6-249","number":249,"surah":6,"verses":[38],"verseLabel":"الأنعام: 38","question":"ما دلالة تقييد الدابة بـ﴿في الأرض﴾ ووصف الطائر بأنه ﴿يطير﴾؟","answer":"خص كل صنف بحركته وحيزه المشاهد: الدابة تدب في الأرض، والطائر يتحرك في الجو. وفي الكلام احتباك؛ كأن التقدير: دابة تدب في الأرض، وطائر يطير في السماء، فحذف من كل جملة ما دل عليه مقابلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص604–618.","url":""}]},{"id":"s6-250","number":250,"surah":6,"verses":[38],"verseLabel":"الأنعام: 38","question":"ما دلالة قوله تعالى: ﴿ولا طائر يطير﴾ مع دلالة اسم الطائر على الطيران؟","answer":"قيد الاسم بالفعل ليصور الطائر حال مباشرته الطيران، وليخرج الاستعمالات المجازية للطائر أو ما سُمي به وهو غير طائر في اللحظة. فانتقل الذهن من اسم الجنس إلى مشهد حي تدبره القدرة الإلهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص604–618.","url":""}]},{"id":"s6-251","number":251,"surah":6,"verses":[38],"verseLabel":"الأنعام: 38","question":"ما دلالة تقييد الطيران بقوله تعالى: ﴿بجناحيه﴾؟","answer":"يحقق أن المراد الطيران الحسي للطائر المعروف، لا الطيران المجازي بمعنى السرعة أو الشؤم، ويستحضر هيئة الجناحين اللذين خلقهما الله وأقدره بهما على الحركة. فالقيد يزيد الصورة تعيينًا ومشاهدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص604–618.","url":""}]},{"id":"s6-252","number":252,"surah":6,"verses":[38],"verseLabel":"الأنعام: 38","question":"ما سرّ إفراد ﴿دابة﴾ و﴿طائر﴾ مع إرادة جميع الأنواع؟","answer":"لأن كل اسم نكرة وقع في سياق النفي المؤكد بـ﴿من﴾، فعمّ كل فرد من جنسه؛ والإفراد هنا ينظر إلى الأفراد واحدًا واحدًا، وهو أبلغ في الاستيعاب من ذكر جمع قد يتوهم منه جماعات دون أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص604–618.","url":""}]},{"id":"s6-253","number":253,"surah":6,"verses":[38],"verseLabel":"الأنعام: 38","question":"بأي معنى تكون الدواب والطير ﴿أممًا أمثالكم﴾؟","answer":"هي جماعات وأجناس لها نظم في الخلق والعيش والتناسل والرزق والآجال، يعلمها الله ويدبر أمرها كما يدبر البشر، ثم يحشرها إليه. فالمماثلة في أصل الاجتماع والخضوع للتدبير الإلهي، لا في جميع الصفات والتكاليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص604–618.","url":""}]},{"id":"s6-254","number":254,"surah":6,"verses":[38],"verseLabel":"الأنعام: 38","question":"ما دلالة جمع ﴿أمم﴾ وتنكيرها؟","answer":"جُمعت لتعدد أجناس الحيوان وطوائفه ونظمه، ونُكرت لإفادة التنوع والكثرة والعظمة التي لا يحيط البشر بتفاصيلها. فكل نوع أمة لها خصائصها، وليس الحيوان أفرادًا مبعثرة خارجة عن العلم والتدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص604–618.","url":""}]},{"id":"s6-255","number":255,"surah":6,"verses":[38],"verseLabel":"الأنعام: 38","question":"ما دلالة قوله تعالى: ﴿ما فرطنا في الكتاب من شيء﴾، وما المراد بالكتاب؟","answer":"المعنى أن شيئًا من شؤون الخلق وأجناسهم وآجالهم وأرزاقهم لم يُغفل من علم الله وكتابته. والمراد بالكتاب على القول الأظهر اللوح المحفوظ، وقيل القرآن من جهة اشتماله على أصول الهداية وما يحتاج إليه في الدين؛ والسياق في إحاطة العلم والتدبير يرجح الأول.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص604–618.","url":""}]},{"id":"s6-256","number":256,"surah":6,"verses":[38],"verseLabel":"الأنعام: 38","question":"ما دلالة اختيار ﴿فرطنا﴾، دون: تركنا أو أغفلنا؟","answer":"التفريط تقصير يجاوز به الشيء قدر العناية الواجبة حتى يضيع ويفوت؛ فنفيه أبلغ من نفي مجرد الترك، لأنه ينزه الكتابة الإلهية عن النقص والإهمال والتضييع جميعًا. وقد فسره المصدر هنا بمعنى: ما أغفلنا ولا ضيعنا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص604–618.","url":""}]},{"id":"s6-257","number":257,"surah":6,"verses":[38],"verseLabel":"الأنعام: 38","question":"ما دلالة قوله تعالى: ﴿من شيء﴾ بعد نفي التفريط؟","answer":"﴿من﴾ زائدة لتوكيد الاستغراق، و﴿شيء﴾ أعم النكرات؛ فاجتمعا بعد النفي لنفي أدنى فرد يمكن أن يتوهم خروجه من الكتاب. وبذلك يبلغ النص غاية الشمول من غير أن تكون العبارة حشوًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص604–618.","url":""}]},{"id":"s6-258","number":258,"surah":6,"verses":[38],"verseLabel":"الأنعام: 38","question":"ما مناسبة ختم ذكر الحيوان بقوله تعالى: ﴿ثم إلى ربهم يحشرون﴾؟","answer":"أكمل به المماثلة في الخضوع للتدبير: كما كُتبت أحوالها في الدنيا فإنها تجمع إلى ربها، ويقتص لبعضها من بعض، ثم يصير أمرها إلى ما يشاء الله. والخاتمة دليل آخر على عموم القدرة، ورد على من أنكر حشر البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص604–618.","url":""}]},{"id":"s6-259","number":259,"surah":6,"verses":[38],"verseLabel":"الأنعام: 38","question":"ما دلالة إضافة الرب إلى الحيوان في قوله تعالى: ﴿إلى ربهم﴾؟","answer":"أثبت أن الله رب هذه الأمم أيضًا: خلقها ورزقها ودبر أنواعها وأحوالها، فلا يخرج الحيوان عن رعايته وحكمه. والإضافة تمهد لحشرها إليه؛ فالذي رباها في الدنيا هو الذي يتولى أمرها في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص604–618.","url":""}]},{"id":"s6-260","number":260,"surah":6,"verses":[39],"verseLabel":"الأنعام: 39","question":"ما دلالة تصوير المكذبين بأنهم ﴿صم وبكم﴾ مع سلامة أسماعهم وألسنتهم؟","answer":"لما عطلوا السمع عن قبول الآيات واللسان عن النطق بالحق نُزلوا منزلة من فقد الحاستين حقيقةً. فالصمم والبكم استعارتان لموت الاستجابة، لا وصفان لخلقة أجسادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص619–632.","url":""}]},{"id":"s6-261","number":261,"surah":6,"verses":[39],"verseLabel":"الأنعام: 39","question":"ما دلالة حذف أداة التشبيه في وصفهم بـ﴿صم وبكم﴾؟","answer":"حذف الأداة والوجه فجاء التشبيه بليغًا، حتى كأنهم هم الصم والبكم لا مجرد مشابهين لهم؛ وذلك لشدة تعطيلهم أدوات الاهتداء. فالصيغة أثبتت الوصف فيهم وأقوت التوبيخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص619–632.","url":""}]},{"id":"s6-262","number":262,"surah":6,"verses":[39],"verseLabel":"الأنعام: 39","question":"ما سرّ جمع ﴿الظلمات﴾ في قوله تعالى: ﴿في الظلمات﴾؟","answer":"لأن طرق الضلال وحجبه متعددة: ظلمة الشرك والجهل والتقليد والهوى والمكابرة، وكل واحدة تزيد الأخرى. فالجمع يقابل وحدة الصراط المستقيم، ويصور إحاطة الحجب بهم من جهات شتى.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص619–632.","url":""}]},{"id":"s6-263","number":263,"surah":6,"verses":[39],"verseLabel":"الأنعام: 39","question":"ما دلالة قوله تعالى: ﴿في الظلمات﴾ بعد ﴿صم وبكم﴾ من غير التصريح بالعمى؟","answer":"أغنت الظلمات عن ذكر العمى؛ فمن أحاطت به الظلمة لا يبصر طريقه ولو كانت عينه سليمة. فاجتمعت في الصورة منافذ الهداية الثلاثة: لا يسمعون الحق، ولا ينطقون به، ولا يبصرون سبيله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص619–632.","url":""}]},{"id":"s6-264","number":264,"surah":6,"verses":[39],"verseLabel":"الأنعام: 39","question":"ما دلالة اختلاف التعبير بين ﴿يضلله﴾ و﴿يجعله على صراط مستقيم﴾؟","answer":"عبّر عن الضلال بالفعل الموجز لأنه تيه وانصراف عن الطريق، وجاء في الهداية بصورة الجعل على الصراط ليدل على الإقامة والتمكين والثبات فوق طريق بيّن. وكل ذلك جار بمشيئة الله وحكمته، جزاءً لموقف العبد من الآيات لا ظلمًا ولا إكراهًا بلا سبب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص619–632.","url":""}]},{"id":"s6-265","number":265,"surah":6,"verses":[39],"verseLabel":"الأنعام: 39","question":"ما دلالة قوله تعالى في الهداية: ﴿يجعله على صراط مستقيم﴾، دون: يهده؟","answer":"الجعل يصور نقل المهتدي وإقامته على طريق محدد، و﴿على﴾ تشعر بالاستعلاء والتمكن منه، و﴿مستقيم﴾ ينفي اعوجاجه؛ فزاد التركيب على أصل الهداية معنى الثبات ووضوح المسلك وسلامة الغاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص619–632.","url":""}]},{"id":"s6-266","number":266,"surah":6,"verses":[39],"verseLabel":"الأنعام: 39","question":"ما سرّ إفراد ﴿صراط﴾ ووصفه بالاستقامة في مقابلة جمع ﴿الظلمات﴾؟","answer":"أُفرد الصراط لأن الحق واحد متسق يوصل إلى غاية واحدة، وجُمعت الظلمات لتشعب طرق الباطل وحجبه. ووصف الصراط بالاستقامة يبين أنه أقصر طريق مأمون من الانحراف، بخلاف التيه في الظلمات.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص619–632.","url":""}]},{"id":"s6-267","number":267,"surah":6,"verses":[39],"verseLabel":"الأنعام: 39","question":"ما دلالة تكرار ﴿من يشأ﴾ وذكر اسم الله في الشرط الأول دون الثاني؟","answer":"تكررت أداة الشرط ليُجعل كل من الإضلال والهداية حكمًا مستقلًا متعلقًا بالمشيئة، فيتوازن طرفا المقابلة. وذُكر اسم الله أولًا ثم استتر فاعل ﴿يشأ﴾ الثاني للعلم به وتجنب التكرار؛ فالمشيئة في الجملتين لله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص619–632.","url":""}]},{"id":"s6-268","number":268,"surah":6,"verses":[40],"verseLabel":"الأنعام: 40","question":"ما سرّ التركيب ﴿قل أرأيتكم﴾، وكيف اجتمعت فيه علامتا خطاب؟","answer":"﴿أرأيتكم﴾ بمعنى أخبروني، وتاء الخطاب فيها هي الفاعل، أما الكاف فحرف خطاب يؤكد توجيه السؤال، وتتغير بحسب عدد المخاطبين وجنسهم ولا محل لها من الإعراب. فاجتماعهما يقوي المواجهة ويلفت كل فرد إلى الجواب الذي تعرفه فطرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص633–642.","url":""}]},{"id":"s6-269","number":269,"surah":6,"verses":[40],"verseLabel":"الأنعام: 40","question":"ما دلالة تصوير العذاب آتيًا في قوله تعالى: ﴿إن أتاكم عذاب الله﴾؟","answer":"أسند الإتيان إلى العذاب فصوره كقادم يقصدهم ويصل إليهم لا يستطيعون دفعه أو الإفلات منه. وإضافته إلى الله تزيده مهابةً وتقرر أن القوة التي كانوا يستندون إليها لا تقف أمامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص633–642.","url":""}]},{"id":"s6-270","number":270,"surah":6,"verses":[40],"verseLabel":"الأنعام: 40","question":"ما دلالة اختلاف الفعل بين ﴿أتاكم عذاب الله﴾ و﴿أتتكم الساعة﴾؟","answer":"طابق الفعل فاعله: ذُكر مع ﴿عذاب﴾ لأنه مذكر، وأُنث مع ﴿الساعة﴾ لأنها مؤنثة. وبذلك حافظ النظم على تعيين كل واحد من الاحتمالين: عقوبة عاجلة في الدنيا أو قيام الساعة التي تنهي زمن العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص633–642.","url":""}]},{"id":"s6-271","number":271,"surah":6,"verses":[40],"verseLabel":"الأنعام: 40","question":"ما دلالة العطف بـ﴿أو﴾ بين عذاب الله والساعة؟","answer":"جعلت كل حالة مستقلة كافية لاختبار فطرتهم: سواء نزل بهم عذاب عاجل أم فاجأتهم الساعة، فلن يجدوا من يدعونه حقًا إلا الله. فلا يلزم اجتماع الأمرين لتقوم الحجة على بطلان الشركاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص633–642.","url":""}]},{"id":"s6-272","number":272,"surah":6,"verses":[40],"verseLabel":"الأنعام: 40","question":"ما دلالة تقديم ﴿غير الله﴾ في قوله تعالى: ﴿أغير الله تدعون﴾؟","answer":"قدم المفعول للإنكار والقصر: أإلهًا غير الله تخصون بالدعاء عند انكشاف الضر؟ وتجربتهم نفسها تجيب بالنفي، لأن الشدة تسقط المعبودات المصطنعة وترد القلب إلى الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص633–642.","url":""}]},{"id":"s6-273","number":273,"surah":6,"verses":[40],"verseLabel":"الأنعام: 40","question":"ما دلالة قوله تعالى: ﴿إن كنتم صادقين﴾ بعد سؤال تعرف الفطرة جوابه؟","answer":"شرط يتحدى دعواهم أن معبوداتهم شركاء ينفعون؛ فإن كانوا صادقين فليثبتوا أنهم يدعونها عند الكرب وأنها تكشفه. ولما كانت التجربة تكذبهم صار الشرط إلزامًا بالحجة وكشفًا لتناقض القول مع الفطرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص633–642.","url":""}]},{"id":"s6-274","number":274,"surah":6,"verses":[41],"verseLabel":"الأنعام: 41","question":"ما دلالة تولي الجواب في قوله تعالى: ﴿بل إياه تدعون﴾؟","answer":"أجاب عنهم لأن واقع الفطرة لا يسعهم إنكاره: عند الشدة يتركون الشركاء ويدعون الله. و﴿بل﴾ تبطل احتمال دعاء غيره الذي طرحه السؤال، ثم تثبت الحقيقة التي لا يملكون جوابًا سواها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص643–648.","url":""}]},{"id":"s6-275","number":275,"surah":6,"verses":[41],"verseLabel":"الأنعام: 41","question":"ما دلالة تقديم ﴿إياه﴾ في قوله تعالى: ﴿بل إياه تدعون﴾؟","answer":"تقديم المفعول يفيد القصر الحقيقي: لا تدعون عند نزول الشدة إلا الله؛ فتتجه القلوب إلى القوة الخالقة المنجية وتغيب المعبودات المزعومة. فالتقديم يواجه الشرك بشهادة فطرتهم العملية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص643–648.","url":""}]},{"id":"s6-276","number":276,"surah":6,"verses":[41],"verseLabel":"الأنعام: 41","question":"ما دلالة التعبير بالكشف في قوله تعالى: ﴿فيكشف ما تدعون إليه﴾، دون: فيدفع الضر؟","answer":"الكشف إزالة ما يغطي الشيء، فصوّر الضر غطاءً أحاط بهم ثم يرفعه الله عنهم؛ وهي صورة تبين الإحاطة أولًا والانفراج بعدها. والفاء تشعر بسرعة ترتب الكشف على الدعاء حين تتعلق به المشيئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص643–648.","url":""}]},{"id":"s6-277","number":277,"surah":6,"verses":[41],"verseLabel":"الأنعام: 41","question":"ما دلالة تعدية الدعاء بـ﴿إلى﴾ في قوله تعالى: ﴿ما تدعون إليه﴾؟","answer":"ضُمّن ﴿تدعون﴾ معنى تتضرعون؛ أي يكشف ما تدعون الله متضرعين إليه من أجله. فحرف الانتهاء يصور توجه الدعاء والافتقار إلى الله، وجمع التضمين في لفظ واحد معنى الدعاء ومعنى التضرع الخالص.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص643–648.","url":""}]},{"id":"s6-278","number":278,"surah":6,"verses":[41],"verseLabel":"الأنعام: 41","question":"ما دلالة تعليق كشف الضر بقوله تعالى: ﴿إن شاء﴾؟","answer":"ليبقى الكشف تابعًا لمشيئة الله وحكمته لا حقًا يفرضه دعاء الداعي؛ فقد يعجل الفرج، وقد يؤخره أو يدخر خيرًا غيره. وفي القيد تعليم للإخلاص والافتقار، ورد على تصور آلي يجعل مجرد الدعاء موجبًا لما يطلبه الإنسان بعينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص643–648.","url":""}]},{"id":"s6-279","number":279,"surah":6,"verses":[41],"verseLabel":"الأنعام: 41","question":"ما دلالة قوله تعالى: ﴿وتنسون ما تشركون﴾، وهل المراد النسيان الحقيقي؟","answer":"يحتمل النسيان الحقيقي؛ إذ تذهلهم الشدة عن أصنامهم وينشغلون بمن يملك كشفها، ويحتمل النسيان المجازي بمعنى الترك والإعراض. وكلا الوجهين يكشف أن المعبودات تغيب عن القلوب في الموضع الذي يُختبر فيه صدق الألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص643–648.","url":""}]},{"id":"s6-280","number":280,"surah":6,"verses":[41],"verseLabel":"الأنعام: 41","question":"ما دلالة التعبير بـ﴿ما تشركون﴾، دون: مَن تشركون؟","answer":"﴿ما﴾ تعم كل ما أشركوه، وتنزل معبوداتهم منزلة غير العاقل تحقيرًا لها وإظهارًا لعجزها عن فهم الدعاء أو كشف الضر. فهي أوسع من ﴿من﴾ التي يغلب استعمالها في العقلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص643–648.","url":""}]},{"id":"s6-281","number":281,"surah":6,"verses":[42],"verseLabel":"الأنعام: 42","question":"ما دلالة حذف المرسلين في قوله تعالى: ﴿ولقد أرسلنا إلى أمم من قبلك﴾؟","answer":"دل فعل ﴿أرسلنا﴾ على أن المفعول المحذوف رسل، فاستغنى السياق عن ذكرهم واتجهت العناية إلى الأمم التي تلقت الرسالة ثم تعرضت للبأساء والضراء. كما يعم الحذف رسلًا متعددين من غير حاجة إلى تعيين أسمائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص649–660.","url":""}]},{"id":"s6-282","number":282,"surah":6,"verses":[42],"verseLabel":"الأنعام: 42","question":"ما دلالة جمع ﴿أمم﴾ وتنكيرها؟","answer":"الجمع والتنكير يدلان على أمم كثيرة متنوعة تعاقبت قبل بعثة النبي ﷺ، فالسنة التي تذكرها الآية ليست حادثة منفردة. وفي عدم تسميتها توجيه النظر إلى القانون الجامع: إرسال، ثم ابتلاء، ثم موقف من التضرع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص649–660.","url":""}]},{"id":"s6-283","number":283,"surah":6,"verses":[42],"verseLabel":"الأنعام: 42","question":"ما دلالة تقديم ﴿إلى أمم﴾ على ﴿من قبلك﴾؟","answer":"قُدم متعلق الإرسال لأنه موضع العناية في القصة: جماعات مكلفة تلقت الرسل ثم جرى عليها الابتلاء، أما ﴿من قبلك﴾ فقيد زمن يصل سنتهم بحال المخاطب. فالتقديم يبرز أولًا سعة التجربة بين الأمم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص649–660.","url":""}]},{"id":"s6-284","number":284,"surah":6,"verses":[42],"verseLabel":"الأنعام: 42","question":"ما دلالة توجيه الخطاب إلى النبي ﷺ في قوله تعالى: ﴿من قبلك﴾، دون: من قبلهم؟","answer":"جعل تاريخ الأمم متصلًا مباشرة برسالته ﷺ تسليةً له وإنذارًا لقومه؛ فما وقع للسابقين يمكن أن يقع لمعاصريه إذا سلكوا طريقهم. كما يشعر الخطاب بأن رسالته خاتمة في سلسلة ممتدة من الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص649–660.","url":""}]},{"id":"s6-285","number":285,"surah":6,"verses":[42],"verseLabel":"الأنعام: 42","question":"ما دلالة التعبير عن الابتلاء بقوله تعالى: ﴿فأخذناهم﴾؟","answer":"الأخذ يدل على التمكن والإحاطة، فصوّر الأمم واقعةً تحت سلطان البأساء والضراء لا تملك الإفلات منهما. والفاء تربط الأخذ بما طوي من تكذيبهم للرسل، فيظهر أنه معالجة وزجر بعد قيام الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص649–660.","url":""}]},{"id":"s6-286","number":286,"surah":6,"verses":[42],"verseLabel":"الأنعام: 42","question":"ما الفرق بين ﴿البأساء﴾ و﴿الضراء﴾، وما دلالة الجمع بينهما؟","answer":"البأساء ما يصيب الناس في الأموال والمعاش والحرب من فقر وشدة، والضراء ما يمس الأبدان والأنفس من مرض وألم، وقيل هما اسمان يعمان وجوه الشدة. والجمع يستوعب الابتلاء الخارجي والداخلي الذي من شأنه أن يرد القلب إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص649–660.","url":""}]},{"id":"s6-287","number":287,"surah":6,"verses":[42],"verseLabel":"الأنعام: 42","question":"ما دلالة ﴿لعلهم يتضرعون﴾ مع علم الله بما سيكون؟","answer":"ليست ﴿لعل﴾ للشك في علم الله، بل تبين الغاية التي من أجلها وقع الابتلاء، وتعرض التضرع نتيجةً مرجوة بحسب ما تقتضيه الأسباب ويعرفه المخاطبون. وفيها إبقاء باب الرجوع مفتوحًا لهم قبل حلول العقوبة القاطعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص649–660.","url":""}]},{"id":"s6-288","number":288,"surah":6,"verses":[43],"verseLabel":"الأنعام: 43","question":"ما دلالة تقديم مجيء البأس في قوله تعالى: ﴿فلولا إذ جاءهم بأسنا تضرعوا﴾؟","answer":"لأن مجيء البأس هو السبب الذي كان ينبغي أن يولد التضرع، فقُدم الظرف المتعلق به لإبراز فظاعة أنهم رأوا السبب حاضرًا ثم لم تقع منهم نتيجته. و﴿لولا﴾ هنا للتوبيخ على ترك ما كان أولى بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص661–670.","url":""}]},{"id":"s6-289","number":289,"surah":6,"verses":[43],"verseLabel":"الأنعام: 43","question":"ما دلالة تصوير البأس بأنه ﴿جاءهم﴾؟","answer":"استعير المجيء لوصول البأس إليهم فصُوّر كقادم قصدهم وأحاط بهم، وهو تصوير يشخص الشدة ويجعلها مواجهة لا خبرًا بعيدًا. وإضافته إلى ضمير التعظيم في ﴿بأسنا﴾ تبين قوته ومصدره.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص661–670.","url":""}]},{"id":"s6-290","number":290,"surah":6,"verses":[43],"verseLabel":"الأنعام: 43","question":"ما دلالة تكرار مادة التضرع بعد قوله تعالى: ﴿لعلهم يتضرعون﴾؟","answer":"ذكرت أولًا بوصفها الغاية المرجوة من الابتلاء، ثم أعيدت في ﴿تضرعوا﴾ لتوبيخهم على أن الغاية نفسها لم تتحقق عند حضور سببها. فالتكرار يقابل بين ما كان ينبغي أن يكون وما وقع فعلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص661–670.","url":""}]},{"id":"s6-291","number":291,"surah":6,"verses":[43],"verseLabel":"الأنعام: 43","question":"ما دلالة تصوير القلوب بالقسوة في قوله تعالى: ﴿ولكن قست قلوبهم﴾؟","answer":"استعيرت صلابة الحجر للقلب الذي لا تلينه الموعظة ولا تؤثر فيه الشدة؛ فكما لا ينفذ الأثر في الجسم القاسي لم ينفذ البأس إلى باطنهم توبةً وخشوعًا. و﴿لكن﴾ تكشف المانع الذي قطع النتيجة المتوقعة من الابتلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص661–670.","url":""}]},{"id":"s6-292","number":292,"surah":6,"verses":[43],"verseLabel":"الأنعام: 43","question":"ما دلالة الماضي في قوله تعالى: ﴿قست قلوبهم﴾؟","answer":"دل الماضي على تحقق القسوة وثبوتها قبل مجيء البأس، ولذلك بقيت القلوب على صلابتها حين طرأ الابتلاء فلم تنتفع به. فهو يسجل علةً راسخة لا انفعالًا عابرًا وقع بعد الشدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص661–670.","url":""}]},{"id":"s6-293","number":293,"surah":6,"verses":[43],"verseLabel":"الأنعام: 43","question":"ما دلالة إسناد التزيين إلى الشيطان في قوله تعالى: ﴿وزين لهم الشيطان ما كانوا يعملون﴾؟","answer":"لأن وسوسته موّهت القبيح في أعينهم حتى رأوه حسنًا، وثبتتهم على الكفر والمعاصي بدل التضرع؛ فنُسب إليه التزيين باعتباره الداعي والمغوي، مع بقاء مسؤوليتهم عن قبول وسوسته واختيار العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص661–670.","url":""}]},{"id":"s6-294","number":294,"surah":6,"verses":[43],"verseLabel":"الأنعام: 43","question":"ما دلالة قوله تعالى: ﴿ما كانوا يعملون﴾، دون: أعمالهم؟","answer":"الموصول وصلته يستحضران أعمالًا معينة متجددة كانوا يباشرونها ويصرون عليها، و﴿كانوا﴾ مع المضارع تفيد رسوخ العادة والاستمرار. أما الاسم ﴿أعمالهم﴾ فيجمعها مجردةً من حركة الممارسة والزمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص661–670.","url":""}]},{"id":"s6-295","number":295,"surah":6,"verses":[44],"verseLabel":"الأنعام: 44","question":"ما دلالة النسيان في قوله تعالى: ﴿فلما نسوا ما ذكروا به﴾، وهل هو ذهاب حقيقي للذكر؟","answer":"المراد أساسًا ترك التذكير والإعراض عنه حتى عاملوه معاملة المنسي، لا عذر الذاكرة التي غاب عنها الأمر بغير قصد. والفاء الفصيحة تطوي أنهم ذُكروا فلم ينتفعوا، ثم تربط إعراضهم بالانتقال إلى الاستدراج بالنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص671–684.","url":""}]},{"id":"s6-296","number":296,"surah":6,"verses":[44],"verseLabel":"الأنعام: 44","question":"ما دلالة بناء ﴿ذُكّروا به﴾ للمفعول؟","answer":"حُذف المذكر لأن جنسه معلوم، وهم الرسل وما جاءوا به من النذر والعظات، وتوجه الاهتمام إلى التذكير نفسه وإلى موقف الأمم منه. كما يعم البناء كل وسيلة أقام الله بها الحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص671–684.","url":""}]},{"id":"s6-297","number":297,"surah":6,"verses":[44],"verseLabel":"الأنعام: 44","question":"ما دلالة مقابلة نسيان التذكير بقوله تعالى: ﴿فتحنا عليهم أبواب كل شيء﴾؟","answer":"لما لم توقظهم الشدائد نُقلوا إلى امتحان الرخاء، ففُتحت لهم وجوه النعم والرزق والقوة فتحًا واسعًا؛ لا تكريمًا، بل استدراجًا حتى يفرحوا ويبطروا ثم يؤخذوا بغتة. فالمقابلة تكشف أن النعمة قد تكون اختبارًا بعد فشل اختبار الضر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص671–684.","url":""}]},{"id":"s6-298","number":298,"surah":6,"verses":[44],"verseLabel":"الأنعام: 44","question":"ما دلالة تعدية الفتح بـ﴿على﴾ في قوله تعالى: ﴿فتحنا عليهم﴾، دون: فتحنا لهم؟","answer":"﴿على﴾ تصور النعم وهي تنصب من فوقهم وتحيط بهم من كل جهة، وتلمح إلى أن هذا الفتح سيؤول حملًا عليهم وحجةً تستعلي عاقبتها، لا منفعة خالصة كما قد توحي اللام. فالحرف يلائم مقام الاستدراج لا مقام الإكرام.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص671–684.","url":""}]},{"id":"s6-299","number":299,"surah":6,"verses":[44],"verseLabel":"الأنعام: 44","question":"لماذا جُمعت ﴿أبواب﴾ ثم أضيفت إلى ﴿كل شيء﴾؟","answer":"جمع الأبواب يدل على تعدد وجوه النعم والخيرات، وإضافتها إلى ﴿كل شيء﴾ تفيد السعة والعموم والتهويل؛ أي فُتحت عليهم أبواب كل نوع مما يُرغب فيه، فاشتدت صورة الإملاء والاستدراج.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص671–684.","url":""}]},{"id":"s6-300","number":300,"surah":6,"verses":[44],"verseLabel":"الأنعام: 44","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى إذا فرحوا بما أوتوا﴾؛ وما دلالة بلوغ الفرح غاية الاستدراج؟","answer":"تفيد ﴿حتى﴾ امتداد الإمهال إلى غايته، وتصور ﴿إذا﴾ لحظة التحول المفاجئ. أما فرحهم فليس سرور الشاكر، بل فرح البطر وسوء استعمال النعمة؛ فلما بلغ اطمئنانهم بها غايته جاء الأخذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص671–684.","url":""}]},{"id":"s6-301","number":301,"surah":6,"verses":[44],"verseLabel":"الأنعام: 44","question":"لماذا بُني ﴿أوتوا﴾ للمجهول مع أن المعطي هو الله؟","answer":"بُني ﴿أوتوا﴾ للمجهول تصويرًا لنظرتهم إلى النعم مقطوعة عن واهبها؛ كأنهم تلقوها باستحقاقهم أو علمهم، فدل التعبير على كمال إعراضهم ونسيانهم أن الله هو الذي ابتلاهم بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص671–684.","url":""}]},{"id":"s6-302","number":302,"surah":6,"verses":[44],"verseLabel":"الأنعام: 44","question":"ما سرّ التعبير في قوله تعالى: ﴿أخذناهم بغتة﴾، واختار الأخذ والمباغتة؟","answer":"الأخذ يدل على القبض والاستيلاء الذي لا يفلت منه مأخوذ، و﴿بغتة﴾ تدل على وقوعه بلا مقدمة ظاهرة وهم في غاية الأمن والفرح؛ فكانت المفاجأة أشد في الحسرة والعقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص671–684.","url":""}]},{"id":"s6-303","number":303,"surah":6,"verses":[44],"verseLabel":"الأنعام: 44","question":"ما سرّ التعبير في قوله تعالى: ﴿فإذا هم مبلسون﴾ بالجملة الاسمية؟","answer":"الجملة الاسمية في ﴿فإذا هم مبلسون﴾ تثبت عليهم حال الإبلاس وتصور استقرارها عقب الأخذ؛ انتقلوا في لحظة من فرح البطر إلى حيرة ويأس لا يجدون منه مخرجًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص671–684.","url":""}]},{"id":"s6-304","number":304,"surah":6,"verses":[44],"verseLabel":"الأنعام: 44","question":"لماذا اختير لفظ ﴿مبلسون﴾، لا: يائسون؟","answer":"الإبلاس أخص من مجرد اليأس؛ فهو يأس يصحبه تحير وانقطاع حجة وسكوت من شدة الصدمة. لذلك صورت ﴿مبلسون﴾ ما أحدثته الأخذة المفاجئة في ظاهرهم وباطنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص671–684.","url":""}]},{"id":"s6-305","number":305,"surah":6,"verses":[45],"verseLabel":"الأنعام: 45","question":"لماذا عبّر عن استئصالهم بقوله: ﴿فقطع دابر القوم﴾؟","answer":"الدابر آخر القوم ومن يأتي في أثرهم، وقطعه كناية عن الاستئصال الكامل؛ فلم يُهلك بعضهم ويُبق بعضًا، بل انقطع امتدادهم وآثار ظلمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص685–693.","url":""}]},{"id":"s6-306","number":306,"surah":6,"verses":[45],"verseLabel":"الأنعام: 45","question":"لماذا أظهر وصفهم فقال: ﴿القوم الذين ظلموا﴾، ولم يقل: دابرهم؟","answer":"إظهار ﴿القوم الذين ظلموا﴾ مكان الضمير يعلن سبب الاستئصال ويجعل الحكم عامًا: من استمر على هذا الظلم استحق مثل عاقبتهم. وفي لفظ ﴿القوم﴾ استيعاب لجماعتهم واجتماعهم على الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص685–693.","url":""}]},{"id":"s6-307","number":307,"surah":6,"verses":[45],"verseLabel":"الأنعام: 45","question":"لماذا عُدل عن وصفهم بالكفر إلى ﴿الذين ظلموا﴾؟","answer":"الظلم أعم من الكفر؛ فهو يشمل الشرك وتكذيب الآيات والمعاصي ووضع الأشياء في غير مواضعها. فالوصف يجمع وجوه جرمهم ويبين أن الهلاك جزاء ظلمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص685–693.","url":""}]},{"id":"s6-308","number":308,"surah":6,"verses":[45],"verseLabel":"الأنعام: 45","question":"لماذا عُطف الحمد على هلاك الظالمين: ﴿والحمد لله رب العالمين﴾؟","answer":"عُقب هلاك الظالمين بالحمد لأن قطع دابرهم عدل ورفع للفساد ونجاة للرسل والمؤمنين، وإظهار لصدق الوعد؛ فهي نعمة عامة تستوجب حمد الله، لا شماتة مجردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص685–693.","url":""}]},{"id":"s6-309","number":309,"surah":6,"verses":[45],"verseLabel":"الأنعام: 45","question":"لماذا خُتمت الآية باسم ﴿رب العالمين﴾ خاصة؟","answer":"﴿رب العالمين﴾ أنسب بالحمد على إزالة الظلم؛ لأن ربوبيته تشمل جميع الخلق، ومن تدبيره أن يطهر العالم من فساد المستكبرين ويحفظ مصالح عباده.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص685–693.","url":""}]},{"id":"s6-310","number":310,"surah":6,"verses":[46],"verseLabel":"الأنعام: 46","question":"ما سرّ التعبير في قوله تعالى: ﴿إن أخذ الله سمعكم وأبصاركم﴾، فعبّر عن سلب الحواس بالأخذ؟","answer":"الأخذ يصور السمع والأبصار نعمًا في ملك الله، متى شاء قبضها وسلب الانتفاع بها؛ فيوقظ الإنسان إلى أنه لا يملك حواسه استقلالًا ولا يستطيع ردها إذا أخذها الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص694–706.","url":""}]},{"id":"s6-311","number":311,"surah":6,"verses":[46],"verseLabel":"الأنعام: 46","question":"لماذا أُفرد ﴿سمعكم﴾ وجُمعت ﴿أبصاركم﴾؟","answer":"أُفرد السمع لأنه مصدر يدل على الجنس، ولأن المسموع الواحد يصل إلى جماعة من جهة واحدة؛ وجُمعت الأبصار لتعدد العيون وجهات النظر والمدركات المرئية باختلاف الأشخاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص694–706.","url":""}]},{"id":"s6-312","number":312,"surah":6,"verses":[46],"verseLabel":"الأنعام: 46","question":"ما سرّ التعبير في قوله تعالى في السمع والبصر ﴿أخذ﴾، وفي القلوب ﴿ختم﴾؟","answer":"ناسب ﴿أخذ﴾ السمع والأبصار لأنهما حاستان ظاهرتان يُتصور سلبهما، وناسب ﴿ختم﴾ القلوب لأنها أوعية الإدراك الباطن؛ فالختم يمنع وصول الهدى إليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص694–706.","url":""}]},{"id":"s6-313","number":313,"surah":6,"verses":[46],"verseLabel":"الأنعام: 46","question":"لماذا عُدّي الختم بـ﴿على﴾: ﴿وختم على قلوبكم﴾؟","answer":"تفيد ﴿على﴾ الاستعلاء والإحاطة؛ فالختم موضوع على القلوب متمكن منها، فيصور الحاجز المحكم الذي يمنعها من الفهم والانتفاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص694–706.","url":""}]},{"id":"s6-314","number":314,"surah":6,"verses":[46],"verseLabel":"الأنعام: 46","question":"ما سرّ التعبير في قوله تعالى: ﴿من إله غير الله يأتيكم به﴾؛ وإلى ماذا يعود ضمير ﴿به﴾ مع تعدد المذكورات؟","answer":"يجوز أن يعود الضمير في ﴿به﴾ إلى المأخوذ المفهوم من الجميع، أي بما ذُكر من السمع والبصر وإدراك القلب، أو إلى واحد منها على معنى الجنس. وإفراده يجمع هذه النعم في أمر لا يقدر على رده إلا الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص694–706.","url":""}]},{"id":"s6-315","number":315,"surah":6,"verses":[46],"verseLabel":"الأنعام: 46","question":"لماذا جاء الاستفهام بـ﴿من إله غير الله﴾ بعد افتراض سلب السمع والبصر والقلب؟","answer":"الاستفهام إنكاري يلزمهم بما يعرفون: لا إله غير الله يستطيع رد السمع والبصر وفتح القلوب. فجاء بعد فرض السلب ليحوّل إقرارهم بربوبيته إلى حجة على بطلان الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص694–706.","url":""}]},{"id":"s6-316","number":316,"surah":6,"verses":[46],"verseLabel":"الأنعام: 46","question":"ما سرّ التعبير في قوله تعالى: ﴿انظر كيف نصرف الآيات﴾، واختار ﴿نصرف﴾ المشدد؟","answer":"التصريف هو تنويع الآيات والحجج وتوجيهها من أسلوب إلى آخر؛ فتارة بالتقرير وتارة بالإنذار وضرب المثل. وصيغة التفعيل تفيد هذا التكثير والتنويع المتكرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص694–706.","url":""}]},{"id":"s6-317","number":317,"surah":6,"verses":[46],"verseLabel":"الأنعام: 46","question":"ما دلالة مجيء قوله تعالى: ﴿ثم هم يصدفون﴾ بعد تصريف الآيات؟","answer":"جاء ﴿ثم هم يصدفون﴾ لإظهار شدة التفاوت بين وضوح الآيات وبين إعراضهم؛ فـ﴿ثم﴾ للاستبعاد والتعجيب من صدوفهم بعد هذا التصريف، لا لمجرد الترتيب الزمني.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص694–706.","url":""}]},{"id":"s6-318","number":318,"surah":6,"verses":[46],"verseLabel":"الأنعام: 46","question":"لماذا أظهر الضمير ﴿هم﴾ في ﴿ثم هم يصدفون﴾؟","answer":"إظهار ﴿هم﴾ يقوي إسناد الصدوف إليهم ويخصهم به؛ فالآيات صُرفت ووضحت، وهم أنفسهم الذين اختاروا الانصراف عنها، وفيه تقريع وتعجيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص694–706.","url":""}]},{"id":"s6-319","number":319,"surah":6,"verses":[46],"verseLabel":"الأنعام: 46","question":"لماذا اختير ﴿يصدفون﴾، لا: يعرضون؟","answer":"الصدوف إعراض مع ميل وانصراف عن الشيء، فهو يصور حركة المتولي بجانبه بعد أن تبين له وجه الحق؛ لذلك كان أبلغ من مطلق الإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص694–706.","url":""}]},{"id":"s6-320","number":320,"surah":6,"verses":[47],"verseLabel":"الأنعام: 47","question":"لماذا تكرر ﴿قل أرأيتكم﴾ بعد وروده في الآية السابقة؟","answer":"تكرر ﴿قل أرأيتكم﴾ لأن الفرض تغير: في الأولى سلب أدوات الإدراك، وفي الثانية مجيء العذاب نفسه. فكل استفهام يفتتح حجة مستقلة ويستحضر المخاطبين لعاقبة جديدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص707–714.","url":""}]},{"id":"s6-321","number":321,"surah":6,"verses":[47],"verseLabel":"الأنعام: 47","question":"لماذا قابل بين مجيء العذاب ﴿بغتة أو جهرة﴾؟","answer":"﴿بغتة﴾ عذاب يفجؤهم من غير شعور، و﴿جهرة﴾ عذاب يجيء عيانًا وهم يبصرون مقدماته؛ فالمقابلة تستوعب حالتي مجيئه، خفي المقدمة وظاهرها، وتقرر أنهم لا ينجون في أيهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص707–714.","url":""}]},{"id":"s6-322","number":322,"surah":6,"verses":[47],"verseLabel":"الأنعام: 47","question":"ما سرّ التعبير في قوله تعالى: ﴿هل يهلك إلا القوم الظالمون﴾ بطريق الاستفهام والقصر؟","answer":"الاستفهام مع الاستثناء يفيد القصر والإنكار: لا يقع الهلاك الاستئصالي إلا بمن استحقه بالظلم. وفيه طمأنة للمؤمنين وإلزام للمكذبين بأن سبب المصير هو عملهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص707–714.","url":""}]},{"id":"s6-323","number":323,"surah":6,"verses":[47],"verseLabel":"الأنعام: 47","question":"ما سرّ التعبير في قوله تعالى: ﴿القوم الظالمون﴾، دون أن يقال: أنتم؟","answer":"العدول عن ﴿أنتم﴾ إلى ﴿القوم الظالمون﴾ يذكر علة الهلاك ويصوغ قاعدة تتجاوز المخاطبين؛ فمن تحقق فيه وصف الظلم دخل في الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص707–714.","url":""}]},{"id":"s6-324","number":324,"surah":6,"verses":[48],"verseLabel":"الأنعام: 48","question":"ما سرّ التعبير في قوله تعالى: ﴿وما نرسل المرسلين إلا مبشرين ومنذرين﴾ بطريق القصر؟","answer":"القصر ينفي عن الرسل ما اقترحه المكذبون من امتلاك الخزائن أو التصرف في الغيب، ويثبت وظيفتهم: تبشير الطائع وإنذار العاصي. أما الهداية والحساب وإنزال الآيات فمن شأن الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص715–721.","url":""}]},{"id":"s6-325","number":325,"surah":6,"verses":[48],"verseLabel":"الأنعام: 48","question":"ما سرّ تقديم التبشير على الإنذار؟","answer":"قُدم التبشير لأن الرحمة سابقة، ولأن الأصل فتح باب الاستجابة قبل التخويف، ولملاءمته ما يعقبه من أمن المؤمنين؛ ثم جاء الإنذار لمن أعرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص715–721.","url":""}]},{"id":"s6-326","number":326,"surah":6,"verses":[48],"verseLabel":"الأنعام: 48","question":"ما سرّ التعبير في قوله تعالى: ﴿فمن آمن وأصلح﴾، ولم يكتف بالإيمان؟","answer":"الإيمان يصحح الاعتقاد، والإصلاح يظهر أثره في العمل ويزيل الفساد من النفس والسلوك؛ فلا يكفي ادعاء الإيمان مع الإصرار على ما يناقضه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص715–721.","url":""}]},{"id":"s6-327","number":327,"surah":6,"verses":[48],"verseLabel":"الأنعام: 48","question":"لماذا اختير ﴿أصلح﴾، لا: عمل صالحًا؟","answer":"﴿أصلح﴾ أوسع من ﴿عمل صالحًا﴾؛ فهو يتناول إصلاح النفس والعمل وما أفسده المرء، ويدل على انتقال حقيقي من الفساد إلى الاستقامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص715–721.","url":""}]},{"id":"s6-328","number":328,"surah":6,"verses":[48],"verseLabel":"الأنعام: 48","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا خوف عليهم ولا هم يحزنون﴾، فنفى الخوف ثم الحزن؟","answer":"الخوف يتعلق بما يُستقبل، والحزن بما فات أو نزل؛ فنفيهما يستوعب آلام المستقبل والماضي. وقُدم الخوف لأن المقام مقام إنذار بما ينتظر الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص715–721.","url":""}]},{"id":"s6-329","number":329,"surah":6,"verses":[48],"verseLabel":"الأنعام: 48","question":"لماذا كرر أداة النفي، وأظهر الضمير في ﴿ولا هم يحزنون﴾؟","answer":"تكرار ﴿لا﴾ يجعل نفي الحزن حكمًا مستقلًا مؤكدًا لا تابعًا لنفي الخوف، وإظهار ﴿هم﴾ يقوي اختصاصهم بالأمن وينفي عنهم الحزن نفيًا ثابتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص715–721.","url":""}]},{"id":"s6-330","number":330,"surah":6,"verses":[49],"verseLabel":"الأنعام: 49","question":"ما سرّ التعبير في قوله تعالى: ﴿والذين كذبوا بآياتنا يمسهم العذاب﴾، فعبّر عن إصابة العذاب بالمس؟","answer":"المس أقل درجات الإصابة عادة، لكنه إذا أضيف إلى العذاب أفاد أن أدنى ملامسة منه كافية في الإيلام؛ وفي المضارع استحضار للعذاب وهو يباشرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص722–727.","url":""}]},{"id":"s6-331","number":331,"surah":6,"verses":[49],"verseLabel":"الأنعام: 49","question":"لماذا أضيفت الآيات إلى ضمير العظمة: ﴿بآياتنا﴾؟","answer":"إضافة الآيات إلى ضمير العظمة تشرفها وتبين عظم جناية المكذبين؛ فهم لم يكذبوا كلامًا بشريًا، بل دلائل الله المنسوبة إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص722–727.","url":""}]},{"id":"s6-332","number":332,"surah":6,"verses":[49],"verseLabel":"الأنعام: 49","question":"ما سرّ التعبير في قوله تعالى: ﴿بما كانوا يفسقون﴾، دون أن يقال: بتكذيبهم؟","answer":"التكذيب صورة من جرمهم، أما الفسق فهو خروجهم المستمر عن طاعة الله ويشمل التكذيب وسائر ما نشأ عنه. فالباء تربط العذاب بسبب راسخ متكرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص722–727.","url":""}]},{"id":"s6-333","number":333,"surah":6,"verses":[49],"verseLabel":"الأنعام: 49","question":"لماذا اختير ﴿يفسقون﴾، لا: يكفرون؟","answer":"اختير ﴿يفسقون﴾ لأن المقام يبرز خروجهم العملي المتجدد عن حدود الطاعة بعد تكذيب الآيات؛ والكفر يصف أصل الاعتقاد، أما الفسق فيصور أثره وسلوكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص722–727.","url":""}]},{"id":"s6-334","number":334,"surah":6,"verses":[50],"verseLabel":"الأنعام: 50","question":"لماذا أُمر النبي أن يقول: ﴿لا أقول لكم عندي خزائن الله﴾؛ وما صلة الخزائن باقتراحاتهم؟","answer":"الخزائن كناية عن موارد قدرة الله ورزقه التي لا تنفد، ونفي امتلاكها يرد اقتراحاتهم للآيات والمنافع الخارقة؛ فالرسول مبلغ لا متصرف في ملك الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص728–736.","url":""}]},{"id":"s6-335","number":335,"surah":6,"verses":[50],"verseLabel":"الأنعام: 50","question":"لماذا جُمعت ﴿خزائن الله﴾؟","answer":"جُمعت الخزائن لتعدد ما عند الله من أنواع الأرزاق والمقادير والقدرات، وللدلالة على السعة التي لا يحيط بها مخلوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص728–736.","url":""}]},{"id":"s6-336","number":336,"surah":6,"verses":[50],"verseLabel":"الأنعام: 50","question":"ما سرّ تقديم ﴿عندي﴾ على ﴿خزائن الله﴾؟","answer":"قُدم ﴿عندي﴾ لأنه محل الدعوى المنفية: ليس عندي أنا خزائن الله. أما ثبوت الخزائن لله فليس موضع الإنكار، فسلط التقديم النفي على دعوى امتلاك الرسول لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص728–736.","url":""}]},{"id":"s6-337","number":337,"surah":6,"verses":[50],"verseLabel":"الأنعام: 50","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا أعلم الغيب﴾، دون أن يقال: ولا عندي علم الغيب موازنًا للجملة الأولى؟","answer":"جاء ﴿ولا أعلم الغيب﴾ فعلًا لأن العلم إدراك يتجدد بتجدد متعلقاته، فنفى مباشرة فعل الإحاطة بالغيب؛ أما الخزائن فأعيان يُتصور وجودها عند مالك فقيل ﴿عندي﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص728–736.","url":""}]},{"id":"s6-338","number":338,"surah":6,"verses":[50],"verseLabel":"الأنعام: 50","question":"لماذا تكرر ﴿ولا أقول لكم﴾ قبل ﴿إني ملك﴾، ولم يكتف بالعطف؟","answer":"أعيد ﴿ولا أقول لكم﴾ لأن دعوى الملَكية جنس آخر غير امتلاك الخزائن وعلم الغيب؛ فالتكرار يفصل الدعاوى ويوجه النفي صريحًا إلى ما توهموه في بشرية الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص728–736.","url":""}]},{"id":"s6-339","number":339,"surah":6,"verses":[50],"verseLabel":"الأنعام: 50","question":"لماذا نفى أن يكون ملكًا مع أن المعترضين طلبوا إنزال ملك؟","answer":"نفي الملَكية يقرر بشرية الرسول ويرد توهمهم أن حامل الرسالة لا بد أن يكون ملكًا؛ فكونه بشرًا لا ينقص الوحي، بل يمكّن الناس من تلقيه والاقتداء به.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص728–736.","url":""}]},{"id":"s6-340","number":340,"surah":6,"verses":[50],"verseLabel":"الأنعام: 50","question":"لماذا حصر منهجه في قوله: ﴿إن أتبع إلا ما يوحى إلي﴾؟","answer":"القصر بـ﴿إن... إلا﴾ يحدد منهج الرسول في اتباع الوحي وحده؛ فلا يدعي من خصائص الربوبية شيئًا، ولا يجيب اقتراحاتهم من عند نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص728–736.","url":""}]},{"id":"s6-341","number":341,"surah":6,"verses":[50],"verseLabel":"الأنعام: 50","question":"لماذا بُني ﴿يوحى﴾ للمجهول؟","answer":"بُني ﴿يوحى﴾ للمجهول لأن موضع العناية هو الوحي الذي يتبعه الرسول، لا ذكر الفاعل وقد عُلم أنه الله؛ وفيه إبراز خضوعه الكامل لما يأتيه من ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص728–736.","url":""}]},{"id":"s6-342","number":342,"surah":6,"verses":[50],"verseLabel":"الأنعام: 50","question":"لماذا مثّل المؤمن والكافر بـ﴿الأعمى والبصير﴾؟","answer":"الأعمى مثل لمن حُجب عن دلائل الوحي فلم يهتد بها، والبصير مثل لمن أبصر الحق واتبعه؛ فالصورة تجعل الفرق بين الكافر والمؤمن كفرق محسوس لا يشتبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص728–736.","url":""}]},{"id":"s6-343","number":343,"surah":6,"verses":[50],"verseLabel":"الأنعام: 50","question":"ما سرّ تقديم ﴿الأعمى﴾ على ﴿البصير﴾؟","answer":"قُدم الأعمى لأنه يمثل حال المخاطبين المنكرين التي سيقت الآية لإبطالها، ولأنه يقابل حال الاتباع على بصيرة المذكورة قبل الاستفهام.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص728–736.","url":""}]},{"id":"s6-344","number":344,"surah":6,"verses":[50],"verseLabel":"الأنعام: 50","question":"ما سرّ التعبير في قوله تعالى: ﴿هل يستوي الأعمى والبصير﴾ بالإفراد، مع أن المراد فريقان؟","answer":"أُفرد الأعمى والبصير لأن المراد جنس كل فريق وصفته، لا عد أفراده؛ فالمقابلة بين حقيقتين: العمى عن الحق والبصيرة به.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص728–736.","url":""}]},{"id":"s6-345","number":345,"surah":6,"verses":[50],"verseLabel":"الأنعام: 50","question":"لماذا خُتمت الآية بـ﴿أفلا تتفكرون﴾، بينما ورد في الآية 32 ﴿أفلا تعقلون﴾؟","answer":"خُتم هنا بالتفكر لأن الآية تضرب مثلًا يحتاج إلى إعمال النظر للعبور من صورة الأعمى والبصير إلى حال الضال والمهتدي؛ أما الآية 32 فتوازن الدنيا والآخرة بحكم ظاهر يناسب التعقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص728–736.","url":""}]},{"id":"s6-346","number":346,"surah":6,"verses":[50],"verseLabel":"الأنعام: 50","question":"ما سرّ التعبير في قوله تعالى في الأنعام: ﴿عندي خزائن الله﴾، وفي هود: ﴿عندي خزائن ربك﴾؟","answer":"أضيفت الخزائن في الأنعام إلى اسم الجلالة لأن السياق في توحيد الله وإبطال الشرك؛ وفي هود أضيفت إلى ﴿ربك﴾ في خطاب نوح لقومه لإبراز أن ما يطلبونه من تدبير الرب لا من شأن الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص69.","url":""}]},{"id":"s6-347","number":347,"surah":6,"verses":[51],"verseLabel":"الأنعام: 51","question":"ما سرّ التعبير في قوله تعالى: ﴿وأنذر به﴾، وإلى ماذا يعود الضمير في ﴿به﴾؟","answer":"الضمير في ﴿به﴾ يعود إلى القرآن المفهوم من قوله قبلها ﴿ما يوحى إلي﴾؛ أي أنذر بالوحي الذين يخافون الحشر. والإضمار يصل الكلام بما قبله ويبين أن أداة الإنذار هي الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص737–742.","url":""}]},{"id":"s6-348","number":348,"surah":6,"verses":[51],"verseLabel":"الأنعام: 51","question":"لماذا خُصّ بالإنذار ﴿الذين يخافون أن يحشروا إلى ربهم﴾؟","answer":"خُصوا بالإنذار لأن خوف الحشر يجعلهم أقرب إلى الانتفاع بالموعظة والاستعداد للقاء الله؛ فالمراد من يتوقع الحشر ويهابه، لا من يجحده فلا يصغي إلى الإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص737–742.","url":""}]},{"id":"s6-349","number":349,"surah":6,"verses":[51],"verseLabel":"الأنعام: 51","question":"ما سرّ التعبير في قوله تعالى: ﴿أن يحشروا إلى ربهم﴾ بالبناء للمجهول؟","answer":"بُني ﴿يحشروا﴾ للمجهول لتوجيه العناية إلى نفس الحشر وهوله، ولأن فاعله معلوم لا يلتبس؛ فلا يملك جمع الخلق إلى ربهم إلا الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص737–742.","url":""}]},{"id":"s6-350","number":350,"surah":6,"verses":[51],"verseLabel":"الأنعام: 51","question":"ما سرّ التعبير في قوله تعالى: ﴿إلى ربهم﴾، دون أن يقال: إلى الله؟","answer":"﴿ربهم﴾ تستحضر صلة الملك والتدبير والتربية، وتذكرهم أنهم راجعون إلى من أنشأهم ورباهم؛ فليس الحشر إلى جهة مجهولة بل إلى مالك أمرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص737–742.","url":""}]},{"id":"s6-351","number":351,"surah":6,"verses":[51],"verseLabel":"الأنعام: 51","question":"لماذا نُفي عنهم الولي والشفيع معًا؟","answer":"الولي هو الناصر الذي يتولى أمر الإنسان استقلالًا، والشفيع هو الواسطة التي تطلب له النفع أو دفع الضر؛ فنفيهما يستوعب كل طريق توهموه للنجاة من دون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص737–742.","url":""}]},{"id":"s6-352","number":352,"surah":6,"verses":[51],"verseLabel":"الأنعام: 51","question":"ما سرّ التعبير في قوله تعالى: ﴿من دونه﴾ بين نفي الولي والشفيع؟","answer":"﴿من دونه﴾ متعلقة بالولي والشفيع معًا؛ أي لا نصير ولا شفيع متجاوزًا حكم الله أو مستقلًا عنه. فالنفي ليس للشفاعات المأذون بها، بل لما اتخذوه من دون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص737–742.","url":""}]},{"id":"s6-353","number":353,"surah":6,"verses":[51],"verseLabel":"الأنعام: 51","question":"لماذا خُتمت الآية بـ﴿لعلهم يتقون﴾ لا: لعلهم يؤمنون؟","answer":"التقوى هي الغاية العملية للإنذار: أن يجعل المرء بينه وبين عذاب الله وقاية بالإيمان والطاعة وترك المعصية. وهي أوسع من ابتداء الإيمان لأنها تشمل دوام الاستجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص737–742.","url":""}]},{"id":"s6-354","number":354,"surah":6,"verses":[52],"verseLabel":"الأنعام: 52","question":"لماذا نهى الله نبيه عن ﴿طرد﴾ ضعفاء المؤمنين؟","answer":"الطرد إبعاد بقسوة وإهانة، وقد طلبه المستكبرون ليخلو لهم مجلس النبي. فجاء النهي صيانة للمؤمنين المخلصين وإبطالًا لميزان الجاه والمال في القرب من الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص743–752.","url":""}]},{"id":"s6-355","number":355,"surah":6,"verses":[52],"verseLabel":"الأنعام: 52","question":"لماذا وصفهم بقوله: ﴿الذين يدعون ربهم﴾، لا: المؤمنين أو الفقراء؟","answer":"وُصفوا بعبادتهم لا بفقرهم لأن قيمتهم في إخلاصهم واتصالهم بربهم، لا في منزلتهم الاجتماعية. والصلة نفسها تقيم الحجة على بطلان طردهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص743–752.","url":""}]},{"id":"s6-356","number":356,"surah":6,"verses":[52],"verseLabel":"الأنعام: 52","question":"لماذا اختير ﴿يدعون﴾، لا: يعبدون؟","answer":"الدعاء يجمع دعاء العبادة ودعاء المسألة، فيصور توجههم الدائم إلى ربهم افتقارًا وعبادة؛ فهو في هذا المقام أوسع تصويرًا لحالهم من مجرد تسمية العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص743–752.","url":""}]},{"id":"s6-357","number":357,"surah":6,"verses":[52],"verseLabel":"الأنعام: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿ربهم﴾، دون أن يقال: الله؟","answer":"إضافة الرب إليهم تشعر بالقرب والعناية والتربية؛ فالذين احتقرهم الناس لهم رب يتولاهم، وفي ذلك تكريم لهم وتقوية للنهي عن طردهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص743–752.","url":""}]},{"id":"s6-358","number":358,"surah":6,"verses":[52],"verseLabel":"الأنعام: 52","question":"لماذا خُصّ الدعاء بـ﴿الغداة والعشي﴾ مع أنهم يعبدونه في سائر الأوقات؟","answer":"الغداة والعشي طرفا النهار، وذكرهما كناية عن المواظبة واستغراق الأوقات، كما أنه يشير إلى أوقات العبادة الظاهرة التي لزموا عليها؛ فلا يراد حصر دعائهم فيهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص743–752.","url":""}]},{"id":"s6-359","number":359,"surah":6,"verses":[52],"verseLabel":"الأنعام: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿يريدون وجهه﴾، وهل المراد الوجه حقيقة في هذا السياق؟","answer":"المراد أنهم يخلصون قصدهم لله وحده ويطلبون رضاه؛ فذكر الوجه يعبر عن الذات والجهة المقصودة، لا عن منفعة دنيوية أو رياء، مع إثبات ما أثبته الله لنفسه من غير تكييف.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص743–752.","url":""}]},{"id":"s6-360","number":360,"surah":6,"verses":[52],"verseLabel":"الأنعام: 52","question":"لماذا جاءت جملتا الحساب متعاكستين: ﴿ما عليك من حسابهم من شيء وما من حسابك عليهم من شيء﴾؟","answer":"عكس الجملتين يستوفي نفي التبعة من الطرفين: لا يحمل النبي حسابهم، ولا يحملون حسابه. فلكل نفس عملها، ولا مسوغ لطردهم بناء على ظن في باطنهم أو حسابهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص743–752.","url":""}]},{"id":"s6-361","number":361,"surah":6,"verses":[52],"verseLabel":"الأنعام: 52","question":"ما سرّ تقديم ﴿عليك﴾ في الأولى، وقُدّم ﴿من حسابك﴾ في الثانية؟","answer":"قُدم ﴿عليك﴾ في الأولى لأن الخطاب يبدأ بتبرئة النبي من حسابهم، ثم قُدم ﴿من حسابك﴾ في الثانية لمقابلة حسابهم بحسابه؛ فانتظم العكس واشتد الفصل بين المسؤوليتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص743–752.","url":""}]},{"id":"s6-362","number":362,"surah":6,"verses":[52],"verseLabel":"الأنعام: 52","question":"لماذا تكررت ﴿من﴾ مرتين في كل جملة من جملتي الحساب؟","answer":"﴿من﴾ الأولى بيانية تتصل بالحساب، والثانية زائدة في سياق النفي لتأكيد الاستغراق مع ﴿شيء﴾؛ فتتكرر الصيغة لتنفي أدنى قدر من تحمل الحساب في الاتجاهين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص743–752.","url":""}]},{"id":"s6-363","number":363,"surah":6,"verses":[52],"verseLabel":"الأنعام: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿فتطردهم فتكون من الظالمين﴾ بفاءين متتابعتين؟","answer":"الفاء الأولى تجعل الطرد نتيجة مترتبة على توهم محاسبتهم، والثانية تجعل الدخول في الظلم نتيجة للطرد؛ فترسم الفاءان سلسلة العاقبة وتحذران من أول خطوة فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص743–752.","url":""}]},{"id":"s6-364","number":364,"surah":6,"verses":[52],"verseLabel":"الأنعام: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿فتكون من الظالمين﴾، دون أن يقال: فتظلم؟","answer":"﴿فتكون من الظالمين﴾ أبلغ من ﴿فتظلم﴾؛ لأنه يصور الطرد إدخالًا في زمرة اتصفت بالظلم، لا هفوة عابرة منفصلة عن أصحابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص743–752.","url":""}]},{"id":"s6-365","number":365,"surah":6,"verses":[53],"verseLabel":"الأنعام: 53","question":"ما سرّ التعبير في قوله تعالى: ﴿وكذلك فتنا بعضهم ببعض﴾، فجعل تفاوت الناس فتنة؟","answer":"جعل الله اختلاف الغنى والفقر والسبق إلى الإيمان امتحانًا متبادلًا: أيشكر المفضَّل دنيويًا أم يستكبر، ويثبت الضعيف أم يفتتن؟ فليس التفاوت دليل كرامة أو هوان عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص753–761.","url":""}]},{"id":"s6-366","number":366,"surah":6,"verses":[53],"verseLabel":"الأنعام: 53","question":"لماذا كرر ﴿بعض﴾ فقال: ﴿بعضهم ببعض﴾؟","answer":"تكرار ﴿بعض﴾ يبرز تبادل الفتنة بين فريقين؛ فكل بعض ممتحن بالبعض الآخر من جهة مختلفة، لا أن فريقًا واحدًا هو موضع الامتحان وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص753–761.","url":""}]},{"id":"s6-367","number":367,"surah":6,"verses":[53],"verseLabel":"الأنعام: 53","question":"لماذا كانت نتيجة الفتنة قولهم: ﴿أهؤلاء من الله عليهم من بيننا﴾؟","answer":"كشفت الفتنة ما في نفوس المستكبرين؛ فقد قاسوا فضل الله بموازين المال والجاه، فاستبعدوا أن يختص بالإيمان من رأوهم دونهم منزلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص753–761.","url":""}]},{"id":"s6-368","number":368,"surah":6,"verses":[53],"verseLabel":"الأنعام: 53","question":"لماذا أشاروا إلى المؤمنين بـ﴿هؤلاء﴾؟","answer":"اسم الإشارة للقريب يجعل المؤمنين كأنهم معروضون أمام أعين المستكبرين، وفي نبرة قولهم تحقير وتعجب إنكاري من اختصاص أولئك بالهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص753–761.","url":""}]},{"id":"s6-369","number":369,"surah":6,"verses":[53],"verseLabel":"الأنعام: 53","question":"لماذا عبّر عن الهداية بقوله: ﴿من الله عليهم﴾؟","answer":"التعبير بالمنّ يقرر أن الهداية فضل عظيم من الله، لا ثمرة مال أو نسب. وهو يرد عليهم بأن معيار العطاء مشيئة الله وعلمه باستعداد القلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص753–761.","url":""}]},{"id":"s6-370","number":370,"surah":6,"verses":[53],"verseLabel":"الأنعام: 53","question":"ما دلالة قولهم: ﴿من بيننا﴾؟","answer":"قولهم ﴿من بيننا﴾ يكشف اعتدادهم بأنفسهم؛ استبعدوا أن يتجاوزهم الفضل إلى من عدوهم أقل شأنًا، فجعلوا منزلتهم الدنيوية مقياسًا للاختيار الإلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص753–761.","url":""}]},{"id":"s6-371","number":371,"surah":6,"verses":[53],"verseLabel":"الأنعام: 53","question":"لماذا جاء الرد في صورة سؤال: ﴿أليس الله بأعلم بالشاكرين﴾؟","answer":"الاستفهام تقريري إنكاري يرد حكمهم إلى العلم الإلهي: أليس الله أعلم بمن يشكر نعمته ويستحق مزيد هدايته؟ وبذلك يبطل اعتراضهم من أصله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص753–761.","url":""}]},{"id":"s6-372","number":372,"surah":6,"verses":[53],"verseLabel":"الأنعام: 53","question":"ما سرّ التعبير في قوله تعالى: ﴿بأعلم﴾ بصيغة التفضيل؟","answer":"﴿أعلم﴾ هنا لتقرير كمال علم الله وتفرده بالحكم، لا لمشاركة غيره له في علم القلوب؛ وصيغة التفضيل تجاري دعواهم الضمنية أنهم أعرف بمن يستحق الفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص753–761.","url":""}]},{"id":"s6-373","number":373,"surah":6,"verses":[53],"verseLabel":"الأنعام: 53","question":"لماذا وصف المؤمنين هنا بـ﴿الشاكرين﴾، لا: المؤمنين؟","answer":"وصفهم بالشاكرين لأنهم عرفوا نعمة الهدى وقبلوها واستعملوها في الطاعة، بخلاف المستكبرين الذين جحدوا النعمة؛ فالشكر هو الصفة المناسبة للمنّ المذكور قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص753–761.","url":""}]},{"id":"s6-374","number":374,"surah":6,"verses":[54],"verseLabel":"الأنعام: 54","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذا جاءك الذين يؤمنون بآياتنا﴾، فعرّفهم بصلة الإيمان؟","answer":"عُرفوا بصلة الإيمان بآيات الله تكريمًا لهم وبيانًا لعلة استقبالهم، وجاء المضارع ﴿يؤمنون﴾ للدلالة على تجدد إيمانهم وثباتهم عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص762–771.","url":""}]},{"id":"s6-375","number":375,"surah":6,"verses":[54],"verseLabel":"الأنعام: 54","question":"لماذا أُمر النبي أن يبدأهم بقوله: ﴿سلام عليكم﴾؟","answer":"السلام تكريم وأمان يقابلان ما طلبه المشركون من طردهم؛ فأُمر النبي أن يستقبلهم بالتحية والطمأنينة، تمهيدًا لبشارة الرحمة والتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص762–771.","url":""}]},{"id":"s6-376","number":376,"surah":6,"verses":[54],"verseLabel":"الأنعام: 54","question":"لماذا جاء ﴿سلام﴾ نكرة، لا: السلام عليكم؟","answer":"التنكير في ﴿سلام﴾ للتعظيم والعموم؛ أي سلام عظيم شامل ثابت لكم، لا مجرد تحية معهودة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص762–771.","url":""}]},{"id":"s6-377","number":377,"surah":6,"verses":[54],"verseLabel":"الأنعام: 54","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿كتب ربكم على نفسه الرحمة﴾، وفي الآية 12: ﴿كتب على نفسه الرحمة﴾ بلا ﴿ربكم﴾؟","answer":"في الآية 12 جاء ﴿كتب على نفسه الرحمة﴾ في سياق الاستدلال العام على ملك الله ووعده بالحشر، أما هنا فالمقام خطاب للمؤمنين والتائبين، فزيد ﴿ربكم﴾ إشعارًا بالقرب والعناية والتربية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص762–771.","url":""}]},{"id":"s6-378","number":378,"surah":6,"verses":[54],"verseLabel":"الأنعام: 54","question":"ما سرّ التعبير في قوله تعالى: ﴿من عمل منكم سوءًا بجهالة﴾، وهل كل ذنب يُفعل بجهالة؟","answer":"الجهالة هنا ليست انعدام العلم بالحكم فقط، بل خفة وسفه يغلبان العاقل عند المعصية؛ فكل من عصى الله وقت فعله جاهل بسوء اختياره وإن كان يعرف التحريم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص762–771.","url":""}]},{"id":"s6-379","number":379,"surah":6,"verses":[54],"verseLabel":"الأنعام: 54","question":"لماذا نُكّرت ﴿جهالة﴾؟","answer":"نُكرت ﴿جهالة﴾ لتشمل أي حالة من خفة النفس وغلبة الشهوة التي توقع في السوء، فلا يضيق باب التوبة بنوع واحد منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص762–771.","url":""}]},{"id":"s6-380","number":380,"surah":6,"verses":[54],"verseLabel":"الأنعام: 54","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم تاب من بعده وأصلح﴾، وما دلالة ﴿ثم﴾؟","answer":"﴿ثم﴾ تصور مهلة بين وقوع السوء وبين الرجوع، وقد تفيد رفعة الانتقال من حال المعصية إلى مقام التوبة؛ و﴿من بعده﴾ تؤكد أن باب الرحمة مفتوح بعد الذنب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص762–771.","url":""}]},{"id":"s6-381","number":381,"surah":6,"verses":[54],"verseLabel":"الأنعام: 54","question":"لماذا عطف ﴿وأصلح﴾ على التوبة؟","answer":"عطف الإصلاح لأن التوبة ليست قولًا مجردًا؛ بل رجوع يصدقه إصلاح العمل وما أفسده الذنب ورد الحقوق عند تعلقها بالناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص762–771.","url":""}]},{"id":"s6-382","number":382,"surah":6,"verses":[54],"verseLabel":"الأنعام: 54","question":"لماذا خُتمت الآية بـ﴿فأنه غفور رحيم﴾ بصيغتي المبالغة؟","answer":"﴿غفور﴾ تدل على كثرة المغفرة وستر الذنوب، و﴿رحيم﴾ على إيصال الرحمة بعد محو السيئة؛ فاجتمعت إزالة أثر الماضي ومنح الخير في المستقبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص762–771.","url":""}]},{"id":"s6-383","number":383,"surah":6,"verses":[55],"verseLabel":"الأنعام: 55","question":"ما سرّ التعبير في قوله تعالى: ﴿وكذلك نفصل الآيات﴾ بالمضارع والتشديد؟","answer":"المضارع يدل على تجدد تفصيل الآيات واستمراره، والتشديد في ﴿نفصل﴾ يفيد شدة البيان والتمييز؛ فالحق يعرض مفصلًا لا ملتبسًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص772–777.","url":""}]},{"id":"s6-384","number":384,"surah":6,"verses":[55],"verseLabel":"الأنعام: 55","question":"لماذا عطف على تفصيل الآيات قوله: ﴿ولتستبين سبيل المجرمين﴾؟","answer":"استبانة سبيل المجرمين إحدى غايات تفصيل الآيات؛ فبوضوح الحق ينكشف ضده، ويعرف المؤمن طريق الجريمة ليحذره كما يعرف طريق الهدى ليسلكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص772–777.","url":""}]},{"id":"s6-385","number":385,"surah":6,"verses":[55],"verseLabel":"الأنعام: 55","question":"لماذا أُفردت ﴿سبيل﴾ مع أن للمجرمين طرقًا متعددة؟","answer":"أُفردت ﴿سبيل﴾ لأن المراد جنس طريق المجرمين أو منهجهم الجامع، وإن تعددت صوره وفروعه؛ فجميعها تنتظم في وجهة واحدة مخالفة للحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص772–777.","url":""}]},{"id":"s6-386","number":386,"surah":6,"verses":[55],"verseLabel":"الأنعام: 55","question":"لماذا أضيف السبيل إلى ﴿المجرمين﴾، لا: الكافرين؟","answer":"الإجرام يبرز ما اكتسبوه من ذنب واعتداء بعد وضوح الآيات؛ فهو أنسب بتفصيل طريقهم العملي، بينما الكفر يصف أصل موقفهم العقدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص772–777.","url":""}]},{"id":"s6-387","number":387,"surah":6,"verses":[56],"verseLabel":"الأنعام: 56","question":"ما سرّ التعبير في قوله تعالى: ﴿إني نهيت أن أعبد﴾، دون أن يقال: لا أعبد؟","answer":"﴿إني نهيت﴾ يبين أن ترك عبادتهم امتثال لوحي الله وحكم ملزم، لا موقف شخصي قابل للمساومة؛ وفيه إعلان براءة حاسمة من الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص778–784.","url":""}]},{"id":"s6-388","number":388,"surah":6,"verses":[56],"verseLabel":"الأنعام: 56","question":"لماذا وصف آلهتهم بقوله: ﴿الذين تدعون من دون الله﴾؟","answer":"صلة ﴿الذين تدعون من دون الله﴾ تكشف حقيقة معبوداتهم من فعل المشركين أنفسهم: هم الذين يدعونها متجاوزين عبادة الله، من غير دليل على استحقاقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص778–784.","url":""}]},{"id":"s6-389","number":389,"surah":6,"verses":[56],"verseLabel":"الأنعام: 56","question":"لماذا تكرر الأمر ﴿قل﴾ في وسط الآية؟","answer":"تكرر ﴿قل﴾ للفصل بين إعلان النهي وبين بيان علته وعاقبته؛ فالثانية تستأنف ردًا مستقلًا: اتباع معبوداتهم ليس إلا اتباعًا للأهواء يفضي إلى الضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص778–784.","url":""}]},{"id":"s6-390","number":390,"surah":6,"verses":[56],"verseLabel":"الأنعام: 56","question":"لماذا عبّر عن عبادتهم بقوله: ﴿لا أتبع أهواءكم﴾؟","answer":"عبادتهم ليست قائمة على برهان، وإنما تنشأ من أهواء موروثة وشهوات؛ لذلك سماها اتباعًا للأهواء، فكشف باطن الشرك بعد النهي عن ظاهره.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص778–784.","url":""}]},{"id":"s6-391","number":391,"surah":6,"verses":[56],"verseLabel":"الأنعام: 56","question":"لماذا جُمعت ﴿أهواءكم﴾؟","answer":"جُمعت ﴿أهواءكم﴾ لتعدد ميول المشركين وتناقض معبوداتهم ودوافعهم؛ فالحق واحد، أما الهوى فطرق متفرقة بتفرق أصحابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص778–784.","url":""}]},{"id":"s6-392","number":392,"surah":6,"verses":[56],"verseLabel":"الأنعام: 56","question":"ما سرّ التعبير في قوله تعالى: ﴿قد ضللت إذًا﴾ بالماضي مع أن الضلال مفترض؟","answer":"الماضي مع ﴿قد﴾ يصور الضلال المفروض متحققًا لا شك فيه إن وقع اتباع أهوائهم؛ فجواب الشرط مقدر المعنى كأنه حدث لتيقن نتيجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص778–784.","url":""}]},{"id":"s6-393","number":393,"surah":6,"verses":[56],"verseLabel":"الأنعام: 56","question":"ما سرّ التعبير في قوله تعالى: ﴿وما أنا من المهتدين﴾، دون أن يقال: وما اهتديت؟","answer":"الجملة الاسمية ﴿وما أنا من المهتدين﴾ أبلغ من نفي فعل اهتداء عابر؛ إذ تنفي الثبات في زمرة المهتدين كلها لو اتبع أهواءهم، وتقابل تحقق الضلال قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص778–784.","url":""}]},{"id":"s6-394","number":394,"surah":6,"verses":[57],"verseLabel":"الأنعام: 57","question":"ما سرّ التعبير في قوله تعالى: ﴿إني على بينة من ربي﴾ بحرف الاستعلاء ﴿على﴾؟","answer":"﴿على﴾ للاستعلاء والتمكن؛ تصور النبي ثابتًا مستمسكًا ببينة تحمل حجته، وفيها ثقته بنصر الله ووضوح ما جاءه من الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص785–793.","url":""}]},{"id":"s6-395","number":395,"surah":6,"verses":[57],"verseLabel":"الأنعام: 57","question":"لماذا نُكّرت ﴿بينة﴾؟","answer":"نُكرت ﴿بينة﴾ للتفخيم؛ أي حجة عظيمة واضحة من ربي، ويزيدها تعظيمًا وصف مصدرها بقوله ﴿من ربي﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص785–793.","url":""}]},{"id":"s6-396","number":396,"surah":6,"verses":[57],"verseLabel":"الأنعام: 57","question":"ما سرّ التعبير في قوله تعالى: ﴿وكذبتم به﴾، وإلى ماذا يعود الضمير؟","answer":"اختلف في مرجع الضمير: فالظاهر عوده إلى ﴿ربي﴾ لقربه، أي كذبتم بالله، وقيل يعود إلى ﴿بينة﴾ لأنها بمعنى البيان والقرآن. والأولى عوده إلى الرب لقرب المرجع وعدم احتياجه إلى تأويل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص785–793.","url":""}]},{"id":"s6-397","number":397,"surah":6,"verses":[57],"verseLabel":"الأنعام: 57","question":"ما سرّ التعبير في قوله تعالى: ﴿ما عندي ما تستعجلون به﴾ بتكرار ﴿ما﴾؟","answer":"﴿ما﴾ الأولى نافية: ليس عندي، والثانية موصولة بمعنى الذي: الذي تستعجلون به. وتجاورهما يقصر نفي الامتلاك على العذاب المطلوب، من غير أن ينفي عن الرسول ما آتاه الله من الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص785–793.","url":""}]},{"id":"s6-398","number":398,"surah":6,"verses":[57],"verseLabel":"الأنعام: 57","question":"لماذا وصف طلبهم للعذاب بـ﴿تستعجلون﴾؟","answer":"الاستعجال طلب الشيء قبل وقته؛ وقد كانوا يطلبون العذاب استهزاءً وتكذيبًا، فسماه استعجالًا ليكشف تهورهم في طلب ما لو نزل لم يمهلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص785–793.","url":""}]},{"id":"s6-399","number":399,"surah":6,"verses":[57],"verseLabel":"الأنعام: 57","question":"ما سرّ التعبير في قوله تعالى: ﴿إن الحكم إلا لله﴾ بطريق القصر؟","answer":"القصر بـ﴿إن... إلا﴾ يرد الحكم كله إلى الله وحده: هو الذي يقدر وقت العذاب ويفصل بين الرسول والمكذبين؛ فلا يملكه الرسول ولا مقترحو الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص785–793.","url":""}]},{"id":"s6-400","number":400,"surah":6,"verses":[57],"verseLabel":"الأنعام: 57","question":"ما سرّ التعبير في قوله تعالى: ﴿يقص الحق﴾، لا: يقضي الحق في القراءة المشهورة؟","answer":"﴿يقص الحق﴾ يفيد بيان الحق وتتبّع وجوهه وإظهاره قولًا وفعلًا، لا مجرد إصدار القضاء؛ ومن قصه الحق إخباره الصادق ووعده النافذ الذي ينتهي إلى الفصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص785–793.","url":""}]},{"id":"s6-401","number":401,"surah":6,"verses":[57],"verseLabel":"الأنعام: 57","question":"لماذا خُتمت الآية بـ﴿وهو خير الفاصلين﴾ بعد ﴿إن الحكم إلا لله﴾؟","answer":"لما حصر الحكم في الله وصفه بأنه خير الفاصلين؛ فهو يفصل بين الحق والباطل وبين الرسول ومكذبيه بعلم وعدل، فتجيء الخاتمة تعليلًا لاستئثاره بالحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص785–793.","url":""}]},{"id":"s6-402","number":402,"surah":6,"verses":[58],"verseLabel":"الأنعام: 58","question":"ما سرّ التعبير في قوله تعالى: ﴿لو أن عندي ما تستعجلون به﴾، فجعل امتلاك العذاب فرضًا ممتنعًا؟","answer":"أداة ﴿لو﴾ تجعل امتلاك الرسول للعذاب فرضًا ممتنعًا، وتبين أنه لو كان في قدرته لما أمهل المستهزئين؛ لكن الأمر لله الحليم الذي ينزله في الوقت الذي اقتضته حكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص794–803.","url":""}]},{"id":"s6-403","number":403,"surah":6,"verses":[58],"verseLabel":"الأنعام: 58","question":"ما سرّ تقديم ﴿عندي﴾ على ﴿ما تستعجلون به﴾؟","answer":"قُدم ﴿عندي﴾ لأنه موضع النفي والتصحيح: ليس العذاب في قدرتي وتمكني. فالتقديم يركز على بشرية الرسول وانتفاء التصرف المستقل عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص794–803.","url":""}]},{"id":"s6-404","number":404,"surah":6,"verses":[58],"verseLabel":"الأنعام: 58","question":"ما سرّ التعبير في قوله تعالى: ﴿لقضي الأمر بيني وبينكم﴾، وحذف بيان الأمر؟","answer":"الأمر المقضي هو إهلاك المكذبين وإنهاء الخصومة، وحذف بيانه للعلم به من السياق ولتهويله؛ فكأن عاقبته أعظم من أن تحتاج إلى تفصيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص794–803.","url":""}]},{"id":"s6-405","number":405,"surah":6,"verses":[58],"verseLabel":"الأنعام: 58","question":"لماذا عبّر بـ﴿قضي الأمر﴾ بالبناء للمجهول؟","answer":"بُني ﴿قضي الأمر﴾ للمجهول للعناية بوقوع الإهلاك نفسه، ولأن قاضيه معلوم وهو الله؛ وفي ترك التصريح أدب مع الله وتهويل للمخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص794–803.","url":""}]},{"id":"s6-406","number":406,"surah":6,"verses":[58],"verseLabel":"الأنعام: 58","question":"لماذا خُتم بقوله: ﴿والله أعلم بالظالمين﴾ بدل: والله أحلم بكم؟","answer":"العلم هنا كناية عن المجازاة مع دليلها؛ فمن أحاط بظلمهم كان أقدر على تقدير وقت عقوبتهم. أما الحلم وحده فلا يبين العلم بالحكمة ولا يتضمن التهديد الذي يقتضيه المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص794–803.","url":""}]},{"id":"s6-407","number":407,"surah":6,"verses":[58],"verseLabel":"الأنعام: 58","question":"لماذا أظهر اسم ﴿الظالمين﴾ ولم يقل: والله أعلم بكم؟","answer":"وُضع الظاهر موضع الضمير لكشف صفتهم وسبب الوعيد؛ فهم ظالمون بالشرك وباستعجال العذاب، والحكم يعم كل من اتصف بظلمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص794–803.","url":""}]},{"id":"s6-408","number":408,"surah":6,"verses":[59],"verseLabel":"الأنعام: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿وعنده مفاتح الغيب﴾ بتقديم ﴿عنده﴾؟","answer":"تقديم ﴿عنده﴾ يفيد الاختصاص: مفاتح الغيب عند الله وحده، فلا يملكها رسول ولا ملك إلا ما أطلعه الله عليه. ثم صرح القصر بعده بقوله ﴿لا يعلمها إلا هو﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص10–19.","url":""}]},{"id":"s6-409","number":409,"surah":6,"verses":[59],"verseLabel":"الأنعام: 59","question":"لماذا اختيرت صورة ﴿مفاتح الغيب﴾ للتعبير عن علم الغيب؟","answer":"صوّر الغيب كأبواب مغلقة لها مفاتيح لا يملكها إلا الله، أو كخزائن مستورة عنده؛ فتجعل الصورة اختصاصه بعلمه وتمكنه منه أمرًا محسوسًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص10–19.","url":""}]},{"id":"s6-410","number":410,"surah":6,"verses":[59],"verseLabel":"الأنعام: 59","question":"هل ﴿مفاتح﴾ جمع مفتاح أم جمع مَفْتَح بمعنى الخزائن، وما أثر المعنيين؟","answer":"تحتمل ﴿مفاتح﴾ أن تكون جمع مفتاح، أي وسائل فتح المغلق والوصول إلى الغيب، وأن تكون جمع مَفْتَح بمعنى الخزائن. وعلى الوجهين لا يملك طرق الغيب ولا خزائنه إلا الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص10–19.","url":""}]},{"id":"s6-411","number":411,"surah":6,"verses":[59],"verseLabel":"الأنعام: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿لا يعلمها إلا هو﴾ بطريق القصر، دون أن يقال: يعلمها الله؟","answer":"القصر ينفي علم هذه المفاتح عن كل ما سوى الله، والضمير ﴿هو﴾ يستحضر المعلوم من المقام ويؤكد انفراده؛ أما قول: يعلمها الله، فلا يؤدي قوة النفي والاختصاص نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص10–19.","url":""}]},{"id":"s6-412","number":412,"surah":6,"verses":[59],"verseLabel":"الأنعام: 59","question":"لماذا انتقل من الغيب إلى قوله: ﴿ويعلم ما في البر والبحر﴾؟","answer":"انتقل من الغيب المستور إلى عالمي البر والبحر المشاهدين ليجمع علم الغائب والحاضر، ثم انتقل من سعتهما إلى أدق جزئياتهما؛ فاستوى في علمه الكلي والجزئي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص10–19.","url":""}]},{"id":"s6-413","number":413,"surah":6,"verses":[59],"verseLabel":"الأنعام: 59","question":"ما سرّ تقديم ﴿البر﴾ على ﴿البحر﴾؟","answer":"قُدم البر لأنه موطن المخاطبين ومجال حركتهم الغالب، وهو الأقرب إلى الحس، ثم ذُكر البحر تتميمًا للاستيعاب؛ فبدأ بالمألوف ثم ثنى بما يخفى أمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص10–19.","url":""}]},{"id":"s6-414","number":414,"surah":6,"verses":[59],"verseLabel":"الأنعام: 59","question":"لماذا خُصّ سقوط الورقة بالذكر بعد عموم علم البر والبحر؟","answer":"خُص سقوط الورقة لأنه حادث بالغ الدقة والكثرة لا يلتفت إليه الناس؛ فإذا كان كل سقوط منها معلومًا لله، فما هو أعظم منه أولى أن يحيط به علمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص10–19.","url":""}]},{"id":"s6-415","number":415,"surah":6,"verses":[59],"verseLabel":"الأنعام: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿وما تسقط من ورقة إلا يعلمها﴾ بالمضارع؟","answer":"المضارع يستحضر سقوط الأوراق حادثًا متجددًا في كل لحظة ومكان، ويقرر أن علم الله يصاحبه على الدوام، لا أنه علم بجنسه مرة وانقضى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص10–19.","url":""}]},{"id":"s6-416","number":416,"surah":6,"verses":[59],"verseLabel":"الأنعام: 59","question":"لماذا نُكّرت ﴿ورقة﴾ وزيدت ﴿من﴾ قبلها؟","answer":"دخلت ﴿من﴾ الزائدة بعد النفي لتأكيد الاستغراق، ونُكرت ﴿ورقة﴾ لتشمل أي ورقة مهما دقت وبعد مكانها؛ فلا تسقط واحدة إلا بعلمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص10–19.","url":""}]},{"id":"s6-417","number":417,"surah":6,"verses":[59],"verseLabel":"الأنعام: 59","question":"لماذا كرر فعل العلم فقال: ﴿إلا يعلمها﴾ بعد ﴿ويعلم ما في البر والبحر﴾؟","answer":"أعيد فعل العلم لتوكيد إحاطته بهذه الصورة الدقيقة خاصة، ولئلا تكون الورقة داخلة في العموم دخولًا ذهنيًا فقط؛ فجعل علم كل سقوط مشهدًا مستقلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص10–19.","url":""}]},{"id":"s6-418","number":418,"surah":6,"verses":[59],"verseLabel":"الأنعام: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا حبة في ظلمات الأرض﴾، فجعل الحبة في ظلمات جمع؟","answer":"جمع الظلمات لأن الحبة تستتر تحت طبقات من التراب وفي ظلمة العمق والليل وما يحيط بها؛ فكلما تعددت حجبها بقيت مكشوفة لعلم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص10–19.","url":""}]},{"id":"s6-419","number":419,"surah":6,"verses":[59],"verseLabel":"الأنعام: 59","question":"لماذا قابل بين ﴿رطب﴾ و﴿يابس﴾؟","answer":"الرطب واليابس ضدان يستوعبان أحوال الموجودات: الحي والميت، واللين والجامد، وما فيه ماء وما جف؛ فالمقابلة كناية عن شمول العلم لكل شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص10–19.","url":""}]},{"id":"s6-420","number":420,"surah":6,"verses":[59],"verseLabel":"الأنعام: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا رطب ولا يابس﴾، وكرر ﴿لا﴾؟","answer":"تكرار ﴿لا﴾ يفرد كل قسم بالنفي المستقل ويؤكد الاستيعاب؛ فلا يخرج من العلم رطب ولا يابس، لا أن الثاني تابع للأول تبعية ضعيفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص10–19.","url":""}]},{"id":"s6-421","number":421,"surah":6,"verses":[59],"verseLabel":"الأنعام: 59","question":"لماذا خُتمت الآية بـ﴿إلا في كتاب مبين﴾ بعد إثبات علم الله؟","answer":"الكتاب المبين هو اللوح المحفوظ؛ فبعد إثبات العلم أثبت الكتابة، توكيدًا لضبط المقادير وأعداد الأشياء وأوقاتها، لا لأن علم الله محتاج إلى كتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص10–19.","url":""}]},{"id":"s6-422","number":422,"surah":6,"verses":[59],"verseLabel":"الأنعام: 59","question":"لماذا وُصف الكتاب بـ﴿مبين﴾، لا: محفوظ؟","answer":"﴿مبين﴾ أي ظاهر مبين لما أثبت فيه من المقادير، فناسب مقام الكشف عن تفاصيل العلم. ولفظ محفوظ يبرز الحماية، أما المقام فيبرز البيان والإحاطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص10–19.","url":""}]},{"id":"s6-423","number":423,"surah":6,"verses":[60],"verseLabel":"الأنعام: 60","question":"لماذا عبّر عن النوم بقوله: ﴿يتوفاكم بالليل﴾؟","answer":"التوفي استيفاء الشيء وقبضه؛ والنوم قبض مؤقت لإدراك الإنسان وحركته، فشبه بالموت وسمي وفاة صغرى، ثم يكون الاستيقاظ بعثًا مصغرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص20–35.","url":""}]},{"id":"s6-424","number":424,"surah":6,"verses":[60],"verseLabel":"الأنعام: 60","question":"ما سرّ التعبير في قوله تعالى: ﴿بالليل﴾، مع أن الإنسان قد ينام نهارًا؟","answer":"ذُكر الليل لأنه الزمن المعتاد لاجتماع الناس على النوم والسكون، فالكلام على الغالب الذي تنتظم به دورة الحياة، ولا ينفي نوم النهار.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص20–35.","url":""}]},{"id":"s6-425","number":425,"surah":6,"verses":[60],"verseLabel":"الأنعام: 60","question":"لماذا عُدّيت الوفاة بالباء: ﴿يتوفاكم بالليل﴾، لا: في الليل؟","answer":"الباء في ﴿بالليل﴾ بمعنى ﴿في﴾؛ وأفادت الظرفية من أصل معنى الملابسة، لأن الفعل الملاصق للزمان واقع فيه. فالمعنى: يتوفاكم في الليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص20–35.","url":""}]},{"id":"s6-426","number":426,"surah":6,"verses":[60],"verseLabel":"الأنعام: 60","question":"لماذا قابل النوم بقوله: ﴿ويعلم ما جرحتم بالنهار﴾؟","answer":"قوبل توفي الليل بكسب النهار لتصوير دورة الإنسان كاملة: يسكن فتقبض حواسه، ثم يبعث للعمل مع كون أعماله كلها معلومة لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص20–35.","url":""}]},{"id":"s6-427","number":427,"surah":6,"verses":[60],"verseLabel":"الأنعام: 60","question":"لماذا عبّر عن الأعمال بـ﴿ما جرحتم﴾؟","answer":"الجرح أصله أثر تحدثه الجارحة، ثم استعمل في الكسب لأن الإنسان يكتسب بجوارحه خيرًا أو شرًا؛ فالتعبير يربط العمل بآثاره ومسؤوليته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص20–35.","url":""}]},{"id":"s6-428","number":428,"surah":6,"verses":[60],"verseLabel":"الأنعام: 60","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم يبعثكم فيه﴾، فجعل الاستيقاظ بعثًا؟","answer":"الاستيقاظ إعادة للحس والحركة بعد قبضهما في النوم، فسمي بعثًا لتمثيله البعث الأكبر وتقريب إمكانه بتجربة تتكرر كل يوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص20–35.","url":""}]},{"id":"s6-429","number":429,"surah":6,"verses":[60],"verseLabel":"الأنعام: 60","question":"إلى ماذا يعود الضمير في ﴿فيه﴾: إلى النهار أم إلى الزمن؟","answer":"الضمير في ﴿فيه﴾ عائد إلى النهار، أي يوقظكم فيه لتعملوا وتستوفوا آجالكم؛ وهو أقرب مذكور، وبه تكتمل مقابلة الليل بالنهار.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص20–35.","url":""}]},{"id":"s6-430","number":430,"surah":6,"verses":[60],"verseLabel":"الأنعام: 60","question":"ما سرّ التعبير في قوله تعالى: ﴿ليقضى أجل مسمى﴾ بالبناء للمجهول؟","answer":"بُني ﴿ليقضى﴾ للمجهول للعناية باستيفاء الأجل نفسه، ولأن مقدره وقاضيه معلوم وهو الله؛ فكل بعث يومي يمضي بالإنسان نحو الحد المكتوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص20–35.","url":""}]},{"id":"s6-431","number":431,"surah":6,"verses":[60],"verseLabel":"الأنعام: 60","question":"لماذا وصف الأجل بـ﴿مسمى﴾؟","answer":"المسمى هو المحدد المقدر الذي لا يتقدم ولا يتأخر؛ فالوصف ينفي العبث والجهالة عن أعمارهم ويقرر أن لكل حياة نهاية معلومة عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص20–35.","url":""}]},{"id":"s6-432","number":432,"surah":6,"verses":[60],"verseLabel":"الأنعام: 60","question":"لماذا تكرر ﴿ثم﴾ في قوله: ﴿ثم إليه مرجعكم ثم ينبئكم﴾؟","answer":"﴿ثم﴾ الأولى تنقل من تتابع النوم واليقظة في الدنيا إلى الرجوع الأكبر بعد انقضاء الأجل، والثانية تنقل من الحشر إلى الحساب؛ فكل انتقال أعظم رتبة مما قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص20–35.","url":""}]},{"id":"s6-433","number":433,"surah":6,"verses":[60],"verseLabel":"الأنعام: 60","question":"ما سرّ تقديم ﴿إليه﴾ في ﴿ثم إليه مرجعكم﴾؟","answer":"قُدم ﴿إليه﴾ لقصر المرجع على الله وتأكيده؛ فلا تنتهي الخلائق إلى غير حكمه، كما لم تكن حياتهم وموتهم إلا بتدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص20–35.","url":""}]},{"id":"s6-434","number":434,"surah":6,"verses":[60],"verseLabel":"الأنعام: 60","question":"ما سرّ التعبير في قوله تعالى: ﴿ينبئكم بما كنتم تعملون﴾، والله يعلم أعمالهم وهم يعرفونها؟","answer":"الإنباء ليس لإعلامهم بشيء مجهول، بل لمواجهتهم بأعمالهم مفصلة وإقامة الحجة والجزاء عليها؛ لذلك علق بما كانوا يعملون.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص20–35.","url":""}]},{"id":"s6-435","number":435,"surah":6,"verses":[61],"verseLabel":"الأنعام: 61","question":"لماذا أعيد قوله: ﴿وهو القاهر فوق عباده﴾ بعد وروده في الآية 18؟","answer":"ورد القهر في الآية 18 مع العلم والقدرة على دفع الضر، وأعيد هنا في سياق حفظ الأنفس وتوفيها وردها؛ فالتكرار يربط سلطان الحياة والموت بالقهر الذي لا يمتنع عليه عبد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص36–46.","url":""}]},{"id":"s6-436","number":436,"surah":6,"verses":[61],"verseLabel":"الأنعام: 61","question":"لماذا عطف على القهر قوله: ﴿ويرسل عليكم حفظة﴾؟","answer":"إرسال الحفظة أثر من آثار قهره وتدبيره؛ فهم يراقبون أعمال العباد ويحفظون ما وُكل إليهم، فلا يخرج أحد عن سلطانه مع أن الحفظ نفسه عناية ورحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص36–46.","url":""}]},{"id":"s6-437","number":437,"surah":6,"verses":[61],"verseLabel":"الأنعام: 61","question":"لماذا عُدّي إرسال الحفظة بـ﴿عليكم﴾، لا: إليكم؟","answer":"﴿عليكم﴾ تفيد الاستعلاء والرقابة والملازمة؛ فالحفظة موكلون بالعباد ومهيمنون على تسجيل أعمالهم، لا مجرد رسل يصلون إليهم ثم ينصرفون.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص36–46.","url":""}]},{"id":"s6-438","number":438,"surah":6,"verses":[61],"verseLabel":"الأنعام: 61","question":"لماذا جُمعت الملائكة في ﴿حفظة﴾؟","answer":"جُمعت ﴿حفظة﴾ لتعدد الملائكة الموكلين بالإنسان وتعاقبهم وتنوع وظائفهم في الحفظ والكتابة، مع شمول الحفظ للعباد جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص36–46.","url":""}]},{"id":"s6-439","number":439,"surah":6,"verses":[61],"verseLabel":"الأنعام: 61","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى إذا جاء أحدكم الموت﴾، فجعل الموت آتيًا؟","answer":"صُور الموت كآت يقصد كل إنسان ويصل إليه في موعده، فيجعل حتميته وقربه مشهدًا حيًا لا يستطيع أحد الهرب منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص36–46.","url":""}]},{"id":"s6-440","number":440,"surah":6,"verses":[61],"verseLabel":"الأنعام: 61","question":"ما سرّ التعبير في قوله تعالى: ﴿أحدكم﴾، لا: الإنسان أو أحدهم؟","answer":"﴿أحدكم﴾ تفرد كل مخاطب بالموت وتجعله معنيًا بالإنذار، فلا يضيع الفرد في لفظ عام؛ وإضافته إلى ضميرهم تقرب المشهد منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص36–46.","url":""}]},{"id":"s6-441","number":441,"surah":6,"verses":[61],"verseLabel":"الأنعام: 61","question":"ما سرّ التعبير في قوله تعالى: ﴿توفته رسلنا﴾ بالجمع، مع قوله في موضع آخر: ﴿يتوفاكم ملك الموت﴾؟","answer":"نُسب التوفي إلى الله لأنه الآمر الحقيقي، وإلى ملك الموت لأنه الموكل به، وإلى الرسل لأن لملك الموت أعوانًا من الملائكة؛ فتعدد الإسناد بتعدد مراتب الفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص36–46.","url":""}]},{"id":"s6-442","number":442,"surah":6,"verses":[61],"verseLabel":"الأنعام: 61","question":"لماذا أضيفت الرسل إلى ضمير العظمة: ﴿رسلنا﴾؟","answer":"إضافة الرسل إلى ضمير العظمة تشرفهم وتبين أنهم لا يعملون استقلالًا، بل ينفذون أمر الله في الوقت والكيفية اللذين قدرهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص36–46.","url":""}]},{"id":"s6-443","number":443,"surah":6,"verses":[61],"verseLabel":"الأنعام: 61","question":"لماذا خُتمت الآية بـ﴿وهم لا يفرطون﴾؟","answer":"الخاتمة تنفي عن رسل الموت أي تقصير أو تأخير أو تجاوز؛ فتوفي كل نفس يقع على وفق الأمر والأجل المقدرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص36–46.","url":""}]},{"id":"s6-444","number":444,"surah":6,"verses":[61],"verseLabel":"الأنعام: 61","question":"لماذا اختير ﴿يفرطون﴾، لا: يخطئون أو يتأخرون؟","answer":"التفريط أعم من الخطأ والتأخر؛ فهو تضييع ما أُمر به أو تجاوز حده. فنفيه يشمل وجوه التقصير كلها ويثبت تمام انضباطهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص36–46.","url":""}]},{"id":"s6-445","number":445,"surah":6,"verses":[62],"verseLabel":"الأنعام: 62","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم ردوا إلى الله﴾ بالبناء للمجهول؟","answer":"بُني ﴿ردوا﴾ للمجهول لأن العناية بمصيرهم الحتمي، ولأن الراد معلوم من السياق؛ فهم مسوقون إلى الله ولا يملكون الامتناع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص47–68.","url":""}]},{"id":"s6-446","number":446,"surah":6,"verses":[62],"verseLabel":"الأنعام: 62","question":"لماذا اختير فعل ﴿ردوا﴾، لا: رجعوا؟","answer":"الرد إعادة الشيء إلى من له السلطان عليه، وقد يكون قسرًا؛ فهو أنسب بحشر العباد من ﴿رجعوا﴾ التي قد توحي بالاختيار، ويكشف أنهم عادوا إلى حكم مولاهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص47–68.","url":""}]},{"id":"s6-447","number":447,"surah":6,"verses":[62],"verseLabel":"الأنعام: 62","question":"لماذا وصف الله بعد الرد إليه بقوله: ﴿مولاهم الحق﴾؟","answer":"وصف الله عند ردهم إليه بأنه ﴿مولاهم﴾ لأن سلطان الملك والحكم يظهر يومئذ بلا منازع، وتسقط كل ولاية ادعوها لغيره؛ فهو الذي يتولى حسابهم ومصيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص47–68.","url":""}]},{"id":"s6-448","number":448,"surah":6,"verses":[62],"verseLabel":"الأنعام: 62","question":"لماذا أضيف المولى إليهم: ﴿مولاهم﴾، مع أن منهم كافرين؟","answer":"أضيف إليهم لأنه مولاهم خلقًا وملكًا وتدبيرًا وإن جحد الكافرون ولايته أو اتخذوا أولياء سواه؛ فملك الله لهم حقيقة لا يزيلها إنكارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص47–68.","url":""}]},{"id":"s6-449","number":449,"surah":6,"verses":[62],"verseLabel":"الأنعام: 62","question":"لماذا وُصف المولى بـ﴿الحق﴾؟","answer":"﴿الحق﴾ يثبت أن ولايته وحدها ثابتة نافذة، ويكشف بطلان ما اتخذوه من أولياء؛ فلا ناصر ولا حاكم يومئذ إلا المولى الحقيقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص47–68.","url":""}]},{"id":"s6-450","number":450,"surah":6,"verses":[62],"verseLabel":"الأنعام: 62","question":"لماذا افتتح التذييل بـ﴿ألا﴾ في قوله: ﴿ألا له الحكم﴾؟","answer":"﴿ألا﴾ أداة تنبيه واستفتاح، تستدعي السمع لما بعدها من حقيقة عظيمة: الحكم كله لله. وجاءت بعد مشهد الرد لتقطع أوهام الشرك والشفاعة المستقلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص47–68.","url":""}]},{"id":"s6-451","number":451,"surah":6,"verses":[62],"verseLabel":"الأنعام: 62","question":"ما سرّ تقديم ﴿له﴾ في ﴿له الحكم﴾؟","answer":"تقديم ﴿له﴾ يفيد الاختصاص؛ فالحكم له وحده لا يشاركه فيه من اتخذوهم أولياء، وهو نتيجة لازمة لكونه مولاهم الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص47–68.","url":""}]},{"id":"s6-452","number":452,"surah":6,"verses":[62],"verseLabel":"الأنعام: 62","question":"لماذا خُتمت الآية بـ﴿وهو أسرع الحاسبين﴾، وكيف يوصف الحساب بالسرعة؟","answer":"سرعة الحساب تعني أنه يحاسب الخلق جميعًا بلا إبطاء ولا انشغال بحساب عن حساب، ويجازي عند تمام الأجل؛ فقدرته وعلمه لا يلحقهما عجز البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص47–68.","url":""}]},{"id":"s6-453","number":453,"surah":6,"verses":[63],"verseLabel":"الأنعام: 63","question":"ما سرّ التعبير في قوله تعالى: ﴿من ينجيكم من ظلمات البر والبحر﴾، فجمع الظلمات؟","answer":"الظلمات تشمل ظلمة الليل والسحاب والبحر، وظلمات الحيرة والخوف والتباس الطريق؛ فجمعها يستوعب طبقات الخطر الحسي والنفسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص47–68.","url":""}]},{"id":"s6-454","number":454,"surah":6,"verses":[63],"verseLabel":"الأنعام: 63","question":"كيف تكون في البر ظلمات مع انكشافه واتساعه؟","answer":"للبر ظلمات الليل والغبار والسحاب، وظلمات الضلال عن الطريق والحيرة في الفلاة؛ فالانكشاف نهارًا لا يمنع أن تحيط بسالكه أسباب العمى والخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص47–68.","url":""}]},{"id":"s6-455","number":455,"surah":6,"verses":[63],"verseLabel":"الأنعام: 63","question":"ما سرّ تقديم البر على البحر هنا؟","answer":"قُدم البر لأنه موطنهم الأقرب والأغلب في معاشهم، ثم ذُكر البحر لاستكمال جهتي السفر والخطر؛ فبدأ بالمألوف قبل الأبعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص47–68.","url":""}]},{"id":"s6-456","number":456,"surah":6,"verses":[63],"verseLabel":"الأنعام: 63","question":"ما سرّ التعبير في قوله تعالى: ﴿تدعونه تضرعًا وخفية﴾، فجمع بين التضرع والخفية؟","answer":"التضرع إظهار الذل والافتقار، والخفية إسرار الدعاء وإخلاصه في الباطن؛ فجمع بين هيئة القلب والجوارح وبين صدق التوجه الذي لا رياء فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص47–68.","url":""}]},{"id":"s6-457","number":457,"surah":6,"verses":[63],"verseLabel":"الأنعام: 63","question":"ما سرّ التعبير بقوله تعالى: ﴿خُفية﴾ لا ﴿جَهرة﴾ في مقام الشدة؟","answer":"الخوف الصادق يقطع التظاهر للناس ويرد القلب إلى من يملك النجاة، فيدعونه خفية بإخلاص؛ وذكرها في الشدة يكشف أن سرائرهم تقر بتوحيده وإن جهروا بالشرك في الرخاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص47–68.","url":""}]},{"id":"s6-458","number":458,"surah":6,"verses":[63],"verseLabel":"الأنعام: 63","question":"لماذا انتقل من خطاب الجمع إلى حكاية قولهم: ﴿لئن أنجانا من هذه﴾؟","answer":"انتقل إلى حكاية قولهم ليجعل اعترافهم ووعدهم مسموعين بألفاظهما، فتقوم عليهم الحجة حين ينجيهم ثم يعودون إلى الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص47–68.","url":""}]},{"id":"s6-459","number":459,"surah":6,"verses":[63],"verseLabel":"الأنعام: 63","question":"إلى ماذا تشير ﴿هذه﴾ في ﴿لئن أنجانا من هذه﴾؟","answer":"تشير ﴿هذه﴾ إلى الظلمات أو الشدة الحاضرة التي أحاطت بهم؛ واسم الإشارة يستحضرها كأنها ماثلة أمامهم ويبرز قربها وهولها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص47–68.","url":""}]},{"id":"s6-460","number":460,"surah":6,"verses":[63],"verseLabel":"الأنعام: 63","question":"لماذا أكدوا وعدهم باللام والنون: ﴿لنكونن من الشاكرين﴾؟","answer":"اللام موطئة للقسم، ونون التوكيد الثقيلة تثبت الوعد؛ فشدة الكرب حملتهم على أغلظ صيغة في التعهد بالشكر إن وقعت النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص47–68.","url":""}]},{"id":"s6-461","number":461,"surah":6,"verses":[63],"verseLabel":"الأنعام: 63","question":"ما دلالة تعبيرهم بقوله: ﴿لنكونن من الشاكرين﴾، دون: لنشكرن؟","answer":"قولهم ﴿من الشاكرين﴾ يتعهد بأن يكونوا ثابتين في زمرة عُرفت بالشكر، وهو أبلغ من وعد بفعل شكر مرة واحدة؛ ثم يكشف رجوعهم إلى الشرك كذب هذا التعهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص47–68.","url":""}]},{"id":"s6-462","number":462,"surah":6,"verses":[64],"verseLabel":"الأنعام: 64","question":"لماذا جاء الجواب صريحًا: ﴿قل الله ينجيكم منها﴾، ولم يقل: هو ينجيكم؟","answer":"أظهر اسم الجلالة لأنه الجواب الصريح عن ﴿من ينجيكم﴾، وليقرر أن المنجي المعروف في الشدة هو الله نفسه، فلا يبقى للضمير مجال يوهم شريكًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص47–68.","url":""}]},{"id":"s6-463","number":463,"surah":6,"verses":[64],"verseLabel":"الأنعام: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿منها ومن كل كرب﴾، فعطف العام على الخاص؟","answer":"عطف ﴿من كل كرب﴾ تعميم بعد تخصيص؛ فبعد إنجائهم من تلك الشدة يذكرهم بأن كل ضيق سواها لا يكشفه على الحقيقة إلا الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص47–68.","url":""}]},{"id":"s6-464","number":464,"surah":6,"verses":[64],"verseLabel":"الأنعام: 64","question":"لماذا اختير لفظ ﴿كرب﴾ بعد ظلمات البر والبحر؟","answer":"الكرب هو الغم الشديد الذي يضيق به الصدر كأنه يعقد النفس؛ فناسب ظلمات البر والبحر بما تثيره من خوف واختناق وحيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص47–68.","url":""}]},{"id":"s6-465","number":465,"surah":6,"verses":[64],"verseLabel":"الأنعام: 64","question":"لماذا أعقب النجاة بقوله: ﴿ثم أنتم تشركون﴾؟","answer":"﴿ثم﴾ للتراخي الرتبي والاستبعاد؛ فبعد اعترافهم بالله ووعدهم بالشكر كان المتوقع التوحيد، فجاء الشرك بعيدًا في القبح عن مقدمة النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص47–68.","url":""}]},{"id":"s6-466","number":466,"surah":6,"verses":[64],"verseLabel":"الأنعام: 64","question":"لماذا أظهر الضمير ﴿أنتم﴾ في ﴿ثم أنتم تشركون﴾؟","answer":"إظهار ﴿أنتم﴾ يقوي نسبة الشرك إليهم ويعجب من فعلهم هم خاصة بعد أن دعوا الله وحده؛ فلا ينسب رجوعهم إلى غموض الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص47–68.","url":""}]},{"id":"s6-467","number":467,"surah":6,"verses":[65],"verseLabel":"الأنعام: 65","question":"ما سرّ التعبير في قوله تعالى: ﴿قل هو القادر﴾ بإظهار الضمير ﴿هو﴾؟","answer":"إظهار ﴿هو﴾ يثبت القدرة لله ويقصرها عليه في هذا المقام؛ فالذي ينجي من الكرب قادر أيضًا على إنزال العذاب من كل جهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص69–79.","url":""}]},{"id":"s6-468","number":468,"surah":6,"verses":[65],"verseLabel":"الأنعام: 65","question":"لماذا عبر عن العذاب بقوله: ﴿أن يبعث عليكم عذابًا﴾؟","answer":"البعث إرسال وإثارة بقوة؛ فصوّر العذاب كشيء يطلقه الله عليهم من حيث يشاء، وفيه معنى المفاجأة والنفاذ لا مجرد وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص69–79.","url":""}]},{"id":"s6-469","number":469,"surah":6,"verses":[65],"verseLabel":"الأنعام: 65","question":"لماذا قُسّم العذاب إلى ﴿من فوقكم﴾ و﴿من تحت أرجلكم﴾؟","answer":"قسّم العذاب إلى ما يأتي من فوق وما ينبع من تحت لاستيعاب الجهات وإحاطة القدرة؛ فلا تحميهم سماء ولا أرض من أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص69–79.","url":""}]},{"id":"s6-470","number":470,"surah":6,"verses":[65],"verseLabel":"الأنعام: 65","question":"لماذا زاد ﴿أرجلكم﴾ بعد قوله: ﴿من تحت﴾؟","answer":"زاد ﴿أرجلكم﴾ لتقريب الخطر وتصويره ملاصقًا لموضع ثباتهم؛ فما يعتمدون عليه قد يصير مصدر الخسف والزلزال والعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص69–79.","url":""}]},{"id":"s6-471","number":471,"surah":6,"verses":[65],"verseLabel":"الأنعام: 65","question":"لماذا عطف النوعين الأولين بـ﴿أو﴾ ثم قال: ﴿أو يلبسكم شيعًا﴾؟","answer":"تكرر ﴿أو﴾ لتقسيم صور العذاب الممكنة: عذاب من فوق، أو من تحت، أو تفريق داخلي؛ وكل واحد منها مقدور لله وقد يقع مستقلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص69–79.","url":""}]},{"id":"s6-472","number":472,"surah":6,"verses":[65],"verseLabel":"الأنعام: 65","question":"لماذا عبّر عن تفريق الناس بقوله: ﴿يلبسكم شيعًا﴾؟","answer":"اللبس هو الخلط والإشكال؛ فـ﴿يلبسكم شيعًا﴾ يصور الجماعة الواحدة وقد خلطت فرقًا متنازعة لا يتميز لها طريق جامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص69–79.","url":""}]},{"id":"s6-473","number":473,"surah":6,"verses":[65],"verseLabel":"الأنعام: 65","question":"لماذا نُكرت ﴿شيعًا﴾ وجُمعت؟","answer":"جُمعت ﴿شيعًا﴾ لتعدد الفرق والأهواء، ونُكرت للتهويل والتكثير؛ أي جماعات شتى لا يحصي اختلافها جامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص69–79.","url":""}]},{"id":"s6-474","number":474,"surah":6,"verses":[65],"verseLabel":"الأنعام: 65","question":"ما سرّ التعبير في قوله تعالى: ﴿ويذيق بعضكم بأس بعض﴾، فجعل الحرب ذوقًا؟","answer":"الذوق مباشرة الشيء واختباره بالحس، فاستعير للحرب ليصور أن كل فريق يباشر ألم قوة الآخر ولا يسمع عنها سماعًا؛ وأدنى ذوق من البأس موجع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص69–79.","url":""}]},{"id":"s6-475","number":475,"surah":6,"verses":[65],"verseLabel":"الأنعام: 65","question":"لماذا كرر ﴿بعض﴾ في ﴿بعضكم بأس بعض﴾؟","answer":"تكرار ﴿بعض﴾ يبين تبادل البأس؛ فبعض الأمة يذيق بعضًا آخر، ثم ينقلب المذيق مذوقًا له، فتعم الفتنة أطرافها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص69–79.","url":""}]},{"id":"s6-476","number":476,"surah":6,"verses":[65],"verseLabel":"الأنعام: 65","question":"لماذا أعيد قوله: ﴿انظر كيف نصرف الآيات﴾ بعد الآية 46؟","answer":"أعيد الأمر بالنظر لأن الآيات المصرفة هنا ألوان جديدة من القدرة والعذاب بعد آيات سلب الحواس؛ فكل مقام يدعو إلى نظر مستقل في تنوع الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص69–79.","url":""}]},{"id":"s6-477","number":477,"surah":6,"verses":[65],"verseLabel":"الأنعام: 65","question":"لماذا خُتمت هنا بـ﴿لعلهم يفقهون﴾، لا ﴿ثم هم يصدفون﴾ كما في الآية 46؟","answer":"خُتم هنا بـ﴿يفقهون﴾ لأن صور العذاب وتداخل أسبابها تحتاج إلى فهم يجاوز ظاهر الألفاظ إلى سننها وعواقبها؛ أما الآية 46 فحكت واقع إعراضهم بعد وضوح الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص69–79.","url":""}]},{"id":"s6-478","number":478,"surah":6,"verses":[66],"verseLabel":"الأنعام: 66","question":"ما سرّ التعبير في قوله تعالى: ﴿وكذب به قومك﴾، وإلى ماذا يعود الضمير في ﴿به﴾؟","answer":"يحتمل الضمير العذاب الموعود في الآيات السابقة، ويحتمل القرآن المتضمن خبره وسائر العقيدة والشريعة؛ والمعنيان متلازمان، إذ كذبوا بالكتاب وبوعيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص80–83.","url":""}]},{"id":"s6-479","number":479,"surah":6,"verses":[66],"verseLabel":"الأنعام: 66","question":"ما سرّ التعبير في قوله تعالى: ﴿قومك﴾ مع أن إضافة القوم إلى النبي مظنة القرب؟","answer":"إضافتهم إلى النبي في ﴿قومك﴾ تشنع تكذيبهم؛ فقد كذبوه مع رابطة القرابة ومعرفتهم بصدقه، فكان جفاؤهم ممن هو منهم أشد قبحًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص80–83.","url":""}]},{"id":"s6-480","number":480,"surah":6,"verses":[66],"verseLabel":"الأنعام: 66","question":"لماذا اعترض بقوله: ﴿وهو الحق﴾ بين التكذيب والأمر بالجواب؟","answer":"جملة ﴿وهو الحق﴾ اعتراض يثبت حقيقة ما كذبوا به ويعجل بيانها؛ فالتكذيب لا يغير ثبوته، بل يضاعف قبح فعلهم لأنهم قابلوا الحق المبين بالإنكار.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص80–83.","url":""}]},{"id":"s6-481","number":481,"surah":6,"verses":[66],"verseLabel":"الأنعام: 66","question":"ما سرّ التعبير في قوله تعالى: ﴿لست عليكم بوكيل﴾، دون أن يقال: لست وكيلكم؟","answer":"تعدية الوكالة بـ﴿على﴾ تفيد السلطة والحفظ والمحاسبة؛ فنفى أن يكون هو مهيمنًا عليهم يمنع تكذيبهم أو يجازيهم، وإنما عليه البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص80–83.","url":""}]},{"id":"s6-482","number":482,"surah":6,"verses":[66],"verseLabel":"الأنعام: 66","question":"لماذا دخلت الباء على ﴿وكيل﴾؟","answer":"الباء زائدة لتوكيد النفي في خبر ﴿ليس﴾؛ فتفيد أنه ليس عليهم بوكيل أدنى ملابسة، وتثبت براءته من وظيفة الحفظ والحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص80–83.","url":""}]},{"id":"s6-483","number":483,"surah":6,"verses":[67],"verseLabel":"الأنعام: 67","question":"ما سرّ التعبير في قوله تعالى: ﴿لكل نبإ مستقر﴾، دون أن يقال: لكل خبر؟","answer":"النبأ خبر عظيم له شأن ونتيجة، وهو أنسب بالوعيد والوحي من مطلق الخبر؛ فلكل نبأ إلهي وقت يظهر فيه صدقه ويقع مضمونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص84–86.","url":""}]},{"id":"s6-484","number":484,"surah":6,"verses":[67],"verseLabel":"الأنعام: 67","question":"لماذا نُكرت ﴿نبإ﴾ و﴿مستقر﴾؟","answer":"نُكر ﴿نبإ﴾ للعموم، فيشمل أخبار الوحي ووعده ووعيده، ونُكر ﴿مستقر﴾ للتهويل؛ فلكل واحد منها وقت أو غاية يستقر عندها على وجه لا يتخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص84–86.","url":""}]},{"id":"s6-485","number":485,"surah":6,"verses":[67],"verseLabel":"الأنعام: 67","question":"كيف يكون للنبأ ﴿مستقر﴾؟","answer":"استقرار النبأ كناية عن وقوع مضمونه وثبوت صدقه في الوقت المقدر؛ فما يبدو خبرًا منتظرًا يصير واقعًا مشهودًا لا مجال لدفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص84–86.","url":""}]},{"id":"s6-486","number":486,"surah":6,"verses":[67],"verseLabel":"الأنعام: 67","question":"لماذا خُتم الوعيد بقوله: ﴿وسوف تعلمون﴾، ولم يذكر ما سيعلمونه؟","answer":"حُذف مفعول ﴿تعلمون﴾ للتهويل والتعميم؛ سيعلمون صدق القرآن وعاقبة التكذيب وما يحل بهم، وتركه مبهمًا يملأ النفس بوجوه الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص84–86.","url":""}]},{"id":"s6-487","number":487,"surah":6,"verses":[67],"verseLabel":"الأنعام: 67","question":"لماذا اختيرت ﴿سوف﴾، لا السين؟","answer":"﴿سوف﴾ أوسع زمنًا من السين، فتلائم الإمهال إلى وقت استقرار النبأ، وفيها تهديد بأن تأخر الوعيد لا يعني تخلفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص84–86.","url":""}]},{"id":"s6-488","number":488,"surah":6,"verses":[68],"verseLabel":"الأنعام: 68","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذا رأيت الذين يخوضون في آياتنا﴾، فعبّر عن كلامهم بالخوض؟","answer":"الخوض أصله الدخول في الماء والاضطراب فيه بلا ثبات، فاستعير لحديثهم في الآيات بالباطل؛ يصورهم منغمسين في جدل مضطرب لا يقصد الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص87–93.","url":""}]},{"id":"s6-489","number":489,"surah":6,"verses":[68],"verseLabel":"الأنعام: 68","question":"لماذا عُدّي الخوض بـ﴿في﴾؟","answer":"﴿في﴾ تصورهم داخلين في الخوض ومحاطين به، كمن غمره الماء؛ فليست زلة كلمة عابرة بل استغراقًا في العبث بالآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص87–93.","url":""}]},{"id":"s6-490","number":490,"surah":6,"verses":[68],"verseLabel":"الأنعام: 68","question":"ما سرّ التعبير في قوله تعالى: ﴿فأعرض عنهم﴾، ولم يأمره بالرد عليهم؟","answer":"أُمر بالإعراض لأن مجلس الاستهزاء ليس مقام طلب حق ينفع معه الجدل؛ ومفارقته إنكار عملي يحفظ حرمة الآيات ولا يمنح باطلهم شرعية الإصغاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص87–93.","url":""}]},{"id":"s6-491","number":491,"surah":6,"verses":[68],"verseLabel":"الأنعام: 68","question":"لماذا جعل غاية الإعراض: ﴿حتى يخوضوا في حديث غيره﴾؟","answer":"جعل الإعراض مؤقتًا بانتهاء الخوض ليبين أن المنهي عنه مجالستهم حال الاستهزاء لا مقاطعتهم مطلقًا؛ فإذا انتقلوا إلى حديث غيره زال سبب الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص87–93.","url":""}]},{"id":"s6-492","number":492,"surah":6,"verses":[68],"verseLabel":"الأنعام: 68","question":"لماذا أعاد فعل ﴿يخوضوا﴾ مع الحديث الآخر؟","answer":"أعيد ﴿يخوضوا﴾ لأن الخوض وصف عادتهم في الكلام، ولو انتقل متعلقه؛ لكن الممنوع هنا خوضهم في آيات الله خاصة، فيزول المنع بتغير الحديث.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص87–93.","url":""}]},{"id":"s6-493","number":493,"surah":6,"verses":[68],"verseLabel":"الأنعام: 68","question":"لماذا نُسب النسيان إلى الشيطان: ﴿وإما ينسينك الشيطان﴾؟","answer":"نُسب الإنساء إلى الشيطان لأنه سببه بالوسوسة والإشغال، أما النسيان البشري العارض فجائز؛ ثم جاء الأمر بالمفارقة عند التذكر فحفظ المقصود.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص87–93.","url":""}]},{"id":"s6-494","number":494,"surah":6,"verses":[68],"verseLabel":"الأنعام: 68","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا تقعد بعد الذكرى﴾، دون أن يقال: فانصرف فور تذكرك؟","answer":"النهي عن القعود يقطع دوام الصحبة والمشاركة في المجلس فور التذكر، وهو أبلغ من مجرد وصف الانصراف؛ إذ يمنع هيئة الاستقرار معهم ما دام الظلم قائمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص87–93.","url":""}]},{"id":"s6-495","number":495,"surah":6,"verses":[68],"verseLabel":"الأنعام: 68","question":"لماذا أظهر وصفهم فقال: ﴿مع القوم الظالمين﴾، ولم يقل: معهم؟","answer":"إظهار ﴿القوم الظالمين﴾ يبين علة النهي: خوضهم في الآيات ظلم، ومجالستهم على حالهم مظنة الرضا به. كما يعمم الحكم في كل مجلس اتصف بذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص87–93.","url":""}]},{"id":"s6-496","number":496,"surah":6,"verses":[69],"verseLabel":"الأنعام: 69","question":"ما سرّ التعبير في قوله تعالى: ﴿وما على الذين يتقون من حسابهم من شيء﴾ بتكرار ﴿من﴾؟","answer":"﴿من﴾ الأولى بيانية في ﴿من حسابهم﴾، والثانية زائدة بعد النفي لتأكيد الاستغراق مع ﴿شيء﴾؛ أي لا يتحمل المتقون أدنى شيء من حساب الخائضين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص94–101.","url":""}]},{"id":"s6-497","number":497,"surah":6,"verses":[69],"verseLabel":"الأنعام: 69","question":"لماذا نُفي حساب الخائضين عن المتقين، ثم قيل: ﴿ولكن ذكرى﴾؟","answer":"ليس على المتقين شيء من حساب الخائضين، لكن عليهم تذكيرهم وإنكار باطلهم قبل مفارقة المجلس؛ فانتفاء المؤاخذة لا يعني ترك واجب النصيحة، ولعل الذكرى تردع الخائضين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص94–101.","url":""}]},{"id":"s6-498","number":498,"surah":6,"verses":[69],"verseLabel":"الأنعام: 69","question":"لماذا حُذف فعل الأمر أو الخبر قبل ﴿ذكرى﴾؟","answer":"﴿ذكرى﴾ مصدر ناب عن فعل محذوف، والتقدير: ولكن ذكّروهم ذكرى، أو: ولكن عليهم ذكرى. وحذفه أوجز وأجمع لمعنيي التذكير والاتعاظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص94–101.","url":""}]},{"id":"s6-499","number":499,"surah":6,"verses":[69],"verseLabel":"الأنعام: 69","question":"لماذا خُتمت الآية بـ﴿لعلهم يتقون﴾؛ ومن المراد بالضمير؟","answer":"الضمير في ﴿لعلهم يتقون﴾ يعود في الأظهر إلى الخائضين؛ لعل تذكير المتقين يحملهم على ترك الخوض. ويحتمل عوده إلى المتقين، أي يثبتون على التقوى باجتناب مجالس الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص94–101.","url":""}]},{"id":"s6-500","number":500,"surah":6,"verses":[70],"verseLabel":"الأنعام: 70","question":"ما سرّ التعبير في قوله تعالى: ﴿وذر الذين اتخذوا دينهم لعبًا ولهوًا﴾، دون أن يقال: اتركهم؟","answer":"﴿ذر﴾ تفيد الترك مع الإعراض والتخلية، وهي أقوى في قطع الالتفات إليهم من مطلق ﴿اترك﴾؛ فلا ينشغل الرسول بمن جعل الدين لعبًا بعد قيام الحجة، مع استمرار التذكير.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص102–128.","url":""}]},{"id":"s6-501","number":501,"surah":6,"verses":[70],"verseLabel":"الأنعام: 70","question":"كيف يتخذ الإنسان دينه ﴿لعبًا ولهوًا﴾؟","answer":"اتخذوا ما يجب تعظيمه وسيلة للسخرية والعبث، أو جعلوا أهواءهم وعاداتهم التي يتلهون بها بمنزلة الدين؛ فلم يحملهم دينهم على جد ولا عمل للآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص102–128.","url":""}]},{"id":"s6-502","number":502,"surah":6,"verses":[70],"verseLabel":"الأنعام: 70","question":"ما سرّ تقديم ﴿اللعب﴾ على ﴿اللهو﴾ كما في الآية 32؟","answer":"اللعب عمل لا يقصد به غرض صحيح، واللهو ما يصرف عن الغرض المهم؛ فقدم اللعب لأنه الفعل الظاهر الذي ينشأ عنه الانشغال عن الحق والآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص102–128.","url":""}]},{"id":"s6-503","number":503,"surah":6,"verses":[70],"verseLabel":"الأنعام: 70","question":"ما سرّ التعبير في قوله تعالى: ﴿وغرتهم الحياة الدنيا﴾، فجعل الحياة نفسها غارّة؟","answer":"أُسند الغرور إلى الحياة مجازًا لأنها بما فيها من زينة ومتاع صارت سببًا لخداعهم؛ والغار حقيقة هو الشيطان والنفس، لكن الإسناد يصور الدنيا كأنها تستدرجهم بنفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص102–128.","url":""}]},{"id":"s6-504","number":504,"surah":6,"verses":[70],"verseLabel":"الأنعام: 70","question":"لماذا أعقب الأمر بتركهم بقوله: ﴿وذكر به﴾؟","answer":"ترك مجالس المستهزئين لا يعني ترك دعوتهم؛ لذلك عطف ﴿وذكر به﴾ ليجمع بين الإعراض عن عبثهم ومواصلة إنذارهم بالقرآن، فلا تتحول المفاصلة إلى إهمال للبلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص102–128.","url":""}]},{"id":"s6-505","number":505,"surah":6,"verses":[70],"verseLabel":"الأنعام: 70","question":"إلى ماذا يعود الضمير في ﴿وذكر به﴾؟","answer":"الضمير في ﴿به﴾ يعود إلى القرآن، أو إلى ما أوحي إلى النبي المذكور في السياق؛ فهو أداة التذكير التي تحذر النفس من الارتهان بعملها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص102–128.","url":""}]},{"id":"s6-506","number":506,"surah":6,"verses":[70],"verseLabel":"الأنعام: 70","question":"ما سرّ التعبير في قوله تعالى: ﴿أن تبسل نفس بما كسبت﴾، واختار لفظ ﴿تبسل﴾؟","answer":"الإبسال تسليم النفس للهلاك وحبسها بما لا فكاك منه؛ فصورت الكلمة النفس مرتهنة بكسبها، منقطعة عن كل ولي أو فداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص102–128.","url":""}]},{"id":"s6-507","number":507,"surah":6,"verses":[70],"verseLabel":"الأنعام: 70","question":"لماذا نُكرت ﴿نفس﴾؟","answer":"نُكرت ﴿نفس﴾ للعموم؛ أي لئلا تسلم أي نفس إلى الهلاك بما كسبت، مهما كان صاحبها، فالمسؤولية فردية شاملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص102–128.","url":""}]},{"id":"s6-508","number":508,"surah":6,"verses":[70],"verseLabel":"الأنعام: 70","question":"ما سرّ التعبير في قوله تعالى: ﴿بما كسبت﴾، فجعل العمل كسبًا يعود على صاحبه؟","answer":"الكسب تحصيل يعود أثره إلى صاحبه؛ فكل عمل كأنه مال يجمعه الإنسان ثم يجده ملكًا له يوم الجزاء، خيرًا كان أو شرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص102–128.","url":""}]},{"id":"s6-509","number":509,"surah":6,"verses":[70],"verseLabel":"الأنعام: 70","question":"لماذا جمع بين نفي ﴿ولي﴾ و﴿شفيع﴾؟","answer":"الولي ناصر يتولى الأمر ابتداءً، والشفيع واسطة تطلب دفع الضر؛ فنفيهما يسد طريقي النجاة المتوهمين، النصرة المباشرة والوساطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص102–128.","url":""}]},{"id":"s6-510","number":510,"surah":6,"verses":[70],"verseLabel":"الأنعام: 70","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن تعدل كل عدل لا يؤخذ منها﴾، فاستعمل العدل بمعنى الفداء؟","answer":"العدل هنا ما يعادل النفس من فدية؛ فلو بذلت كل بدل يمكن أن يفتدى به لم يقبل منها، لأن النجاة يومئذ بالإيمان والعمل لا بالمقايضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص102–128.","url":""}]},{"id":"s6-511","number":511,"surah":6,"verses":[70],"verseLabel":"الأنعام: 70","question":"لماذا أسند الأخذ إلى المجهول: ﴿لا يؤخذ منها﴾؟","answer":"بُني ﴿لا يؤخذ﴾ للمجهول للعناية برفض الفداء نفسه، ولأن الآخذ معلوم وهو الله أو ملائكته بأمره؛ فلا جهة يمكن أن تقبله منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص102–128.","url":""}]},{"id":"s6-512","number":512,"surah":6,"verses":[70],"verseLabel":"الأنعام: 70","question":"لماذا كرر: ﴿أولئك الذين أبسلوا بما كسبوا﴾ بعد التحذير من أن تبسل نفس؟","answer":"الأول تحذير عام من الإبسال، ثم جاء ﴿أولئك﴾ لتعيين الذين وقع عليهم الوعيد وتقرير سببه: هم الذين سلموا للهلاك بكسبهم، لا بظلم من غيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص102–128.","url":""}]},{"id":"s6-513","number":513,"surah":6,"verses":[70],"verseLabel":"الأنعام: 70","question":"لماذا اختير لهم ﴿شراب من حميم﴾ في مقابلة ما كسبوا؟","answer":"الحميم ماء بلغ غاية الحرارة، فجاء شرابًا بدل ما كانوا يتلذذون به في الدنيا؛ وكلما طلبوا ما يطفئ العطش زادهم ألمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص102–128.","url":""}]},{"id":"s6-514","number":514,"surah":6,"verses":[70],"verseLabel":"الأنعام: 70","question":"لماذا وصف العذاب بـ﴿أليم﴾، مع أن الألم مفهوم من العذاب؟","answer":"وصف العذاب بالأليم لتوكيد بلوغ الألم وتمييزه بأنه عذاب يباشر إحساسهم، لا مجرد حرمان أو تهديد؛ فاجتمع شراب الحميم وسائر الألم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص102–128.","url":""}]},{"id":"s6-515","number":515,"surah":6,"verses":[70],"verseLabel":"الأنعام: 70","question":"لماذا خُتم بقوله: ﴿بما كانوا يكفرون﴾، لا: بما كسبوا كما تقدم؟","answer":"﴿بما كسبوا﴾ يقرر المسؤولية العامة عن الأعمال، ثم خص الكفر في الخاتمة لأنه أصل تلك المكاسب الفاسدة وسبب خلود العذاب؛ فانتقل من الفروع إلى الجذر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص102–128.","url":""}]},{"id":"s6-516","number":516,"surah":6,"verses":[71],"verseLabel":"الأنعام: 71","question":"ما سرّ التعبير في قوله تعالى: ﴿أندعو من دون الله ما لا ينفعنا ولا يضرنا﴾ في صورة سؤال؟","answer":"الاستفهام إنكاري يرفض عبادة من لا يملك نفعًا ولا ضرًا؛ وصيغته تلزم المخاطبين أن يجيبوا بأن دعاء هذه المعبودات سفه بعد معرفة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص129–147.","url":""}]},{"id":"s6-517","number":517,"surah":6,"verses":[71],"verseLabel":"الأنعام: 71","question":"ما سرّ تقديم نفي النفع على نفي الضر؟","answer":"قُدم النفع لأن العابد يطلب من معبوده جلب الخير أولًا، فإذا كان لا ينفع ولا يدفع الضر بطلت عبادته من جهتي الرجاء والخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص129–147.","url":""}]},{"id":"s6-518","number":518,"surah":6,"verses":[71],"verseLabel":"الأنعام: 71","question":"لماذا عبر عن الارتداد بقوله: ﴿ونرد على أعقابنا﴾؟","answer":"الرجوع على الأعقاب صورة للارتداد إلى الوراء بعد التقدم في طريق الهدى؛ تجعل ترك التوحيد انتكاسًا لا انتقالًا متكافئًا بين طريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص129–147.","url":""}]},{"id":"s6-519","number":519,"surah":6,"verses":[71],"verseLabel":"الأنعام: 71","question":"لماذا عُدّي الرد بـ﴿على﴾ في ﴿على أعقابنا﴾؟","answer":"﴿على﴾ تصورهم منقلبين مستقرين فوق أعقابهم، وتفيد التمكن من هيئة النكوص؛ فليست رجعة عابرة بل انقلابًا كاملًا عن وجهة الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص129–147.","url":""}]},{"id":"s6-520","number":520,"surah":6,"verses":[71],"verseLabel":"الأنعام: 71","question":"ما سرّ التعبير في قوله تعالى: ﴿بعد إذ هدانا الله﴾، دون أن يقال: بعد هدايتنا؟","answer":"﴿بعد إذ﴾ تستحضر وقت تحقق الهداية وتبرز قبح الارتداد بعد ذوقها، والفعل ﴿هدانا﴾ يجعل نعمة الهداية واقعة مكتملة لا اسمًا مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص129–147.","url":""}]},{"id":"s6-521","number":521,"surah":6,"verses":[71],"verseLabel":"الأنعام: 71","question":"لماذا أظهر اسم الله في ﴿هدانا الله﴾؟","answer":"أظهر اسم الجلالة ليعظم نعمة الهدى ويبين مصدرها وحده؛ فالارتداد ليس ترك رأي بشري، بل رد لهداية تفضل الله بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص129–147.","url":""}]},{"id":"s6-522","number":522,"surah":6,"verses":[71],"verseLabel":"الأنعام: 71","question":"لماذا شُبّه المرتد بـ﴿الذي استهوته الشياطين في الأرض حيران﴾؟","answer":"شُبه المرتد برجل أضلته الشياطين في فلاة، تتجاذبه فيبقى حيران، بينما أصحابه على الطريق ينادونه؛ فالصورة تجمع ضياع البصيرة وتعدد دواعي الباطل ووضوح صوت الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص129–147.","url":""}]},{"id":"s6-523","number":523,"surah":6,"verses":[71],"verseLabel":"الأنعام: 71","question":"لماذا جُمعت ﴿الشياطين﴾ مع إفراد ﴿الذي﴾؟","answer":"أُفرد الضال لأن كل مرتد يتحمل حيرته منفردًا، وجُمعت الشياطين لتعدد جهات الإغواء والأهواء التي تتجاذبه بعيدًا عن الطريق الواحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص129–147.","url":""}]},{"id":"s6-524","number":524,"surah":6,"verses":[71],"verseLabel":"الأنعام: 71","question":"لماذا اختير ﴿استهوته﴾، لا: أضلته؟","answer":"الاستهواء طلب الهوي وإسقاط الإنسان في الهوة، ويأتي بمعنى استمالته بالهوى؛ فهو يصور الإضلال جذبًا إلى السقوط، لا مجرد تعريف بطريق خاطئ.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص129–147.","url":""}]},{"id":"s6-525","number":525,"surah":6,"verses":[71],"verseLabel":"الأنعام: 71","question":"لماذا قُيّد الحيران بقوله: ﴿في الأرض﴾؟","answer":"﴿في الأرض﴾ تكمل صورة التائه في فلاة واسعة لا علم له بمعالمها، وتبرز أنه حائر في موضع كان ينبغي أن يهتدي فيه بآيات الله المنتشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص129–147.","url":""}]},{"id":"s6-526","number":526,"surah":6,"verses":[71],"verseLabel":"الأنعام: 71","question":"ما سرّ التعبير في قوله تعالى: ﴿له أصحاب يدعونه إلى الهدى ائتنا﴾، ولم يصل إليهم مع وضوح دعوتهم؟","answer":"الحيرة عطلت قدرته على الاستجابة مع وضوح النداء؛ تتجاذبه الشياطين بعيدًا بينما أصحابه يدعونه إلى الطريق، فالصورة تبين أن معرفة الهدى لا تنفع من استسلم للهوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص129–147.","url":""}]},{"id":"s6-527","number":527,"surah":6,"verses":[71],"verseLabel":"الأنعام: 71","question":"لماذا حُكي نداء أصحابه بكلمة واحدة: ﴿ائتنا﴾؟","answer":"اختصر نداءهم في ﴿ائتنا﴾ لأنه أصرح كلمة في طلب الرجوع إلى جماعتهم وطريقهم، وتوحي بقرب الهدى وسهولته: ليس عليه إلا أن يقبل ويتجه إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص129–147.","url":""}]},{"id":"s6-528","number":528,"surah":6,"verses":[71],"verseLabel":"الأنعام: 71","question":"ما سرّ التعبير في قوله تعالى: ﴿إن هدى الله هو الهدى﴾ بضمير الفصل وتعريف الطرفين؟","answer":"ضمير الفصل وتعريف الطرفين يفيدان القصر: هدى الله وحده هو الهدى الكامل الحقيقي، وما عداه استهواء وحيرة وإن سماه أصحابه هداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص129–147.","url":""}]},{"id":"s6-529","number":529,"surah":6,"verses":[71],"verseLabel":"الأنعام: 71","question":"ما سرّ التعبير في قوله تعالى: ﴿وأمرنا لنسلم لرب العالمين﴾ باللام؟","answer":"اللام في ﴿لنسلم﴾ للتعليل، ومتعلق الأمر محذوف؛ أي أُمرنا بما أُمرنا به لأجل أن نخلص الاستسلام لرب العالمين، أو هي بمعنى الباء: أُمرنا بأن نسلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص129–147.","url":""}]},{"id":"s6-530","number":530,"surah":6,"verses":[71],"verseLabel":"الأنعام: 71","question":"لماذا اختير ﴿لرب العالمين﴾ في مقام الاستسلام؟","answer":"﴿رب العالمين﴾ يعلل الاستسلام؛ فمن يربي الخلق جميعًا ويملك أمرهم هو وحده المستحق أن تسلم له الوجوه، لا معبود عاجز من العالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص129–147.","url":""}]},{"id":"s6-531","number":531,"surah":6,"verses":[72],"verseLabel":"الأنعام: 72","question":"لماذا عطف: ﴿وأن أقيموا الصلاة واتقوه﴾ على ﴿لنسلم لرب العالمين﴾؟","answer":"عطف إقامة الصلاة والتقوى لأن الاستسلام الباطن يصدقه العمل؛ فالصلاة أعظم مظهر للعبودية، والتقوى سياج يشمل امتثال الأوامر واجتناب النواهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص148–153.","url":""}]},{"id":"s6-532","number":532,"surah":6,"verses":[72],"verseLabel":"الأنعام: 72","question":"ما سرّ التعبير في قوله تعالى: ﴿أقيموا الصلاة﴾، دون أن يقال: صلوا؟","answer":"إقامة الصلاة أداؤها مستقيمة تامة بأوقاتها وأركانها وخشوعها والمداومة عليها؛ فهي أوسع من مجرد وقوع فعل الصلاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص148–153.","url":""}]},{"id":"s6-533","number":533,"surah":6,"verses":[72],"verseLabel":"الأنعام: 72","question":"ما سرّ تقديم الصلاة على التقوى؟","answer":"قُدمت الصلاة لأنها عمود العبادة وأظهر دليل على الاستسلام المذكور قبلها، ثم جاءت التقوى وصفًا جامعًا لسائر الطاعات والمحظورات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص148–153.","url":""}]},{"id":"s6-534","number":534,"surah":6,"verses":[72],"verseLabel":"الأنعام: 72","question":"ما سرّ التعبير في قوله تعالى: ﴿واتقوه﴾ بالضمير بعد ذكر رب العالمين؟","answer":"عاد الضمير إلى ﴿رب العالمين﴾ لقرب ذكره ولربط التقوى بالرب الذي أمر بالاستسلام والصلاة؛ والإضمار يوحد سلسلة الأوامر ولا يحتاج إلى إعادة الاسم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص148–153.","url":""}]},{"id":"s6-535","number":535,"surah":6,"verses":[72],"verseLabel":"الأنعام: 72","question":"لماذا خُتمت الآية بـ﴿وهو الذي إليه تحشرون﴾؟","answer":"ذكّر بالحشر بعد أمر الاستسلام والصلاة والتقوى لأن الرجوع إلى الله موضع الجزاء عليها؛ فالخاتمة تجعل التكليف مرتبطًا بالمآل الذي لا مهرب منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص148–153.","url":""}]},{"id":"s6-536","number":536,"surah":6,"verses":[72],"verseLabel":"الأنعام: 72","question":"ما سرّ تقديم ﴿إليه﴾ في ﴿إليه تحشرون﴾؟","answer":"قُدم ﴿إليه﴾ لقصر الحشر على الله وتأكيد الرجوع إلى حكمه وحده؛ فلا تنفع عنده الأرباب التي دُعيت من دونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص148–153.","url":""}]},{"id":"s6-537","number":537,"surah":6,"verses":[72],"verseLabel":"الأنعام: 72","question":"لماذا بُني ﴿تحشرون﴾ للمجهول؟","answer":"بُني ﴿تحشرون﴾ للمجهول للعناية بحتمية الحشر الواقع عليهم، ولأن حاشرهم معلوم وهو الله؛ كما يشعر بأنهم مجموعون قسرًا لا باختيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص148–153.","url":""}]},{"id":"s6-538","number":538,"surah":6,"verses":[73],"verseLabel":"الأنعام: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿خلق السماوات والأرض بالحق﴾، وما الذي تضيفه ﴿بالحق﴾؟","answer":"﴿بالحق﴾ تعني أنه خلقهما بالحكمة والغاية الثابتة، لا عبثًا ولا باطلًا؛ ومن مقتضى هذا الحق البعث والجزاء وظهور العدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص154–168.","url":""}]},{"id":"s6-539","number":539,"surah":6,"verses":[73],"verseLabel":"الأنعام: 73","question":"لماذا انتقل من خلق السماوات والأرض إلى ﴿ويوم يقول كن فيكون﴾؟","answer":"انتقل من الخلق الأول المشاهد إلى يوم البعث ليدل بالأول على الثاني؛ فمن خلق السماوات والأرض بالحق ينشئ الخلق يوم القيامة بكلمة نافذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص154–168.","url":""}]},{"id":"s6-540","number":540,"surah":6,"verses":[73],"verseLabel":"الأنعام: 73","question":"ما متعلق ﴿يوم﴾ في قوله: ﴿ويوم يقول كن فيكون﴾؟","answer":"في ﴿يوم﴾ أوجه، أبرزها تعلقه بمحذوف تقديره: واذكر يوم يقول، أو تعلقه بمعنى الملك والحشر في السياق؛ والمقصود استحضار يوم نفاذ الأمر بالبعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص154–168.","url":""}]},{"id":"s6-541","number":541,"surah":6,"verses":[73],"verseLabel":"الأنعام: 73","question":"لماذا اختُصر الخلق كله في قوله: ﴿كن فيكون﴾؟","answer":"﴿كن فيكون﴾ تمثل تمام القدرة وسرعة نفاذ المشيئة بلا معالجة ولا آلة ولا مهلة؛ وليس المراد احتياج الخلق إلى صوت، بل أنه متى أراد شيئًا وجد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص154–168.","url":""}]},{"id":"s6-542","number":542,"surah":6,"verses":[73],"verseLabel":"الأنعام: 73","question":"لماذا جاء ﴿فيكون﴾ بالمضارع بعد الأمر ﴿كن﴾؟","answer":"المضارع ﴿فيكون﴾ يستحضر تكون المأمور عقب الأمر، ويدل على تجدد تعلق القدرة بما يشاء؛ فالمشهد حاضر كلما تعلقت الإرادة بشيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص154–168.","url":""}]},{"id":"s6-543","number":543,"surah":6,"verses":[73],"verseLabel":"الأنعام: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿قوله الحق﴾ بتعريف الخبر؟","answer":"تعريف ﴿الحق﴾ يفيد أن قوله هو الحق الكامل الثابت الذي لا يدخله خلف ولا باطل؛ فكأن حقيقة الحق محصورة في قوله النافذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص154–168.","url":""}]},{"id":"s6-544","number":544,"surah":6,"verses":[73],"verseLabel":"الأنعام: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿وله الملك يوم ينفخ في الصور﴾، أليس الملك له في كل يوم؟","answer":"الملك لله في كل وقت، لكن خُص يوم النفخ لأن ملكه يظهر يومئذ بلا دعوى ولا منازع، وتسقط أملاك الخلق وسلطاتهم التي توهموها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص154–168.","url":""}]},{"id":"s6-545","number":545,"surah":6,"verses":[73],"verseLabel":"الأنعام: 73","question":"لماذا بُني ﴿ينفخ﴾ للمجهول؟","answer":"بُني ﴿ينفخ﴾ للمجهول لتوجيه العناية إلى النفخ وهوله وآثاره، ولأن النافخ معلوم من السنة وهو إسرافيل المأمور من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص154–168.","url":""}]},{"id":"s6-546","number":546,"surah":6,"verses":[73],"verseLabel":"الأنعام: 73","question":"لماذا اختير لفظ ﴿الصور﴾، وما المراد به؟","answer":"الصور هو القرن الذي ينفخ فيه للبعث؛ واختير اللفظ لأنه يجمع قصر العبارة وهول النداء العام الذي تتغير به أحوال الخلق دفعة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص154–168.","url":""}]},{"id":"s6-547","number":547,"surah":6,"verses":[73],"verseLabel":"الأنعام: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿عالم الغيب والشهادة﴾، دون أن يقال: يعلم الغيب والشهادة؟","answer":"اسم الفاعل ﴿عالم﴾ يدل على ثبوت صفة العلم ودوامها، لا على فعل يتجدد بعد خفاء؛ فالغيب والشهادة معلومان له علمًا قائمًا لا يسبقه جهل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص154–168.","url":""}]},{"id":"s6-548","number":548,"surah":6,"verses":[73],"verseLabel":"الأنعام: 73","question":"ما سرّ تقديم الغيب على الشهادة؟","answer":"قُدم الغيب لأنه أخفى وأدل على كمال العلم، ولأن السياق في البعث والنفخ وما غاب عن إدراك الناس؛ ثم عطفت الشهادة لاستيعاب كل معلوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص154–168.","url":""}]},{"id":"s6-549","number":549,"surah":6,"verses":[73],"verseLabel":"الأنعام: 73","question":"لماذا خُتمت الآية بـ﴿وهو الحكيم الخبير﴾؟","answer":"هو ﴿الحكيم﴾ في خلقه وأمره وبعثه، يضع كل شيء موضعه، و﴿الخبير﴾ بدقائق الغيب والشهادة وعواقب الأمور؛ فالخاتمة تعلل ما سبق من الخلق والملك والعلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص154–168.","url":""}]},{"id":"s6-550","number":550,"surah":6,"verses":[74],"verseLabel":"الأنعام: 74","question":"لماذا افتتحت قصة إبراهيم بقوله: ﴿وإذ قال إبراهيم لأبيه آزر﴾؟","answer":"جاءت قصة إبراهيم بعد تقرير التوحيد والبعث مثالًا عمليًا للنظر في ملكوت السماوات والأرض؛ فانتقل السياق من عرض الحجة إلى محاجة نبي قومه بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص169–185.","url":""}]},{"id":"s6-551","number":551,"surah":6,"verses":[74],"verseLabel":"الأنعام: 74","question":"لماذا ذُكر اسم الأب ﴿آزر﴾ هنا؟","answer":"ذُكر ﴿آزر﴾ لتعيين المخاطب وإبراز أن إبراهيم بدأ الدعوة بأقرب الناس إليه، فلم تمنعه رابطة الأبوة من إنكار الشرك مع بقاء أدب الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص169–185.","url":""}]},{"id":"s6-552","number":552,"surah":6,"verses":[74],"verseLabel":"الأنعام: 74","question":"ما سرّ التعبير في قوله تعالى: ﴿أتتخذ أصنامًا آلهة﴾، مع أن الأصنام هي الآلهة التي اتخذوها؟","answer":"﴿أصنامًا﴾ مفعول أول يصف حقيقتها الجامدة، و﴿آلهة﴾ مفعول ثان يصف المنزلة التي جعلوها لها؛ فالسؤال ينكر تحويل حجر مصنوع إلى معبود.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص169–185.","url":""}]},{"id":"s6-553","number":553,"surah":6,"verses":[74],"verseLabel":"الأنعام: 74","question":"ما سرّ تقديم ﴿أصنامًا﴾ على ﴿آلهة﴾؟","answer":"قُدمت ﴿أصنامًا﴾ لتعرض حقيقتها أولًا قبل الدعوى الباطلة فيها؛ فإذا ثبت أنها تماثيل جامدة ظهر تناقض اتخاذها آلهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص169–185.","url":""}]},{"id":"s6-554","number":554,"surah":6,"verses":[74],"verseLabel":"الأنعام: 74","question":"لماذا جاء الإنكار بصيغة المضارع: ﴿أتتخذ﴾؟","answer":"المضارع يستحضر اتخاذه المتجدد واستمراره عليه، ويجعل المنكر حاضرًا كأنه يشاهد؛ فهو ليس فعلًا مضى ثم تُرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص169–185.","url":""}]},{"id":"s6-555","number":555,"surah":6,"verses":[74],"verseLabel":"الأنعام: 74","question":"ما سرّ التعبير في قوله تعالى: ﴿إني أراك وقومك في ضلال مبين﴾، فبدأ بالأب قبل قومه؟","answer":"بدأ بالأب لأنه المخاطب المباشر والأقرب إليه ولأنه صاحب أثر في قومه، ثم عطف قومه ليعم الحكم من شاركه؛ فجمع النصيحة الخاصة والإنذار العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص169–185.","url":""}]},{"id":"s6-556","number":556,"surah":6,"verses":[74],"verseLabel":"الأنعام: 74","question":"ما سرّ التعبير في قوله تعالى: ﴿في ضلال﴾، فجعل الضلال كأنه مكان يحيط بهم؟","answer":"﴿في﴾ تصور الضلال كحيز أحاط بهم واستقروا داخله، فلا يرون خارجه طريق الحق؛ وهي أبلغ من مجرد وصفهم بأنهم ضالون.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص169–185.","url":""}]},{"id":"s6-557","number":557,"surah":6,"verses":[74],"verseLabel":"الأنعام: 74","question":"لماذا وصف الضلال بـ﴿مبين﴾؟","answer":"﴿مبين﴾ أي ظاهر بين لمن نظر، كما أنه مظهر لسوء عاقبته؛ فعبادة المصنوع بدل الخالق ضلال لا خفاء في بطلانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص169–185.","url":""}]},{"id":"s6-558","number":558,"surah":6,"verses":[75],"verseLabel":"الأنعام: 75","question":"ما سرّ التعبير في قوله تعالى: ﴿وكذلك نري إبراهيم ملكوت السماوات والأرض﴾، لا: ملك السماوات والأرض؟","answer":"الملكوت صيغة تفيد سعة الملك وعظم السلطان ودقائقه، فرؤية إبراهيم لم تقف عند الأجرام بل نفذت إلى نظامها وتدبيرها ودلالتها على المالك الواحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص186–195.","url":""}]},{"id":"s6-559","number":559,"surah":6,"verses":[75],"verseLabel":"الأنعام: 75","question":"لماذا عبّر بالمضارع ﴿نري﴾ مع أن الرؤية وقعت في الماضي؟","answer":"المضارع ﴿نري﴾ يحكي الرؤية الماضية في صورة حاضرة متجددة، ويستحضر تدرج إبراهيم في النظر كأن القارئ يشهده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص186–195.","url":""}]},{"id":"s6-560","number":560,"surah":6,"verses":[75],"verseLabel":"الأنعام: 75","question":"لماذا أُضيف الملكوت إلى السماوات والأرض مع أن إبراهيم رأى كواكب مخصوصة؟","answer":"كانت الكواكب والقمر والشمس دلائل مخصوصة تكشف نظام الملكوت كله؛ فمن انتظام حركتها وأفولها ظهر سلطان خالق السماوات والأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص186–195.","url":""}]},{"id":"s6-561","number":561,"surah":6,"verses":[75],"verseLabel":"الأنعام: 75","question":"ما سرّ التعبير في قوله تعالى: ﴿وليكون من الموقنين﴾، دون أن يقال: ليوقن؟","answer":"﴿من الموقنين﴾ يدل على ثباته في زمرة أهل اليقين ورسوخ الصفة فيه، وهو أبلغ من حصول فعل يقين في لحظة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص186–195.","url":""}]},{"id":"s6-562","number":562,"surah":6,"verses":[75],"verseLabel":"الأنعام: 75","question":"لماذا جيء بواو قبل ﴿ليكون﴾؟","answer":"الواو عطفت علة مذكورة على علة محذوفة يفهمها السياق؛ أي أريناه الملكوت ليستدل به وليكون من الموقنين. فالرؤية لها ثمرات متعددة لا غاية واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص186–195.","url":""}]},{"id":"s6-563","number":563,"surah":6,"verses":[76],"verseLabel":"الأنعام: 76","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما جن عليه الليل﴾، فعبّر عن إظلام الليل بالجنّ؟","answer":"﴿جن﴾ معناه ستر وغطى، فصوّر الليل غطاءً أطبق على إبراهيم وحجب ضوء النهار؛ ومن مادته الجن لاستتارهم والجَنين لخفائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص196–207.","url":""}]},{"id":"s6-564","number":564,"surah":6,"verses":[76],"verseLabel":"الأنعام: 76","question":"لماذا عُدّي ﴿جن﴾ بـ﴿على﴾؟","answer":"عُدي بـ﴿على﴾ لأن ظلمة الليل تعلو الإنسان وتغشاه من فوقه وتحيط به؛ فصار الليل كغطاء مطبق عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص196–207.","url":""}]},{"id":"s6-565","number":565,"surah":6,"verses":[76],"verseLabel":"الأنعام: 76","question":"لماذا نُكّر ﴿كوكبًا﴾، ولم يعيّن اسمه؟","answer":"نُكر ﴿كوكبًا﴾ لأن المقصود جنس الكوكب وصفته في البزوغ والأفول، لا تعيين اسمه؛ فالحجة تصح في أي جرم من هذا النوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص196–207.","url":""}]},{"id":"s6-566","number":566,"surah":6,"verses":[76],"verseLabel":"الأنعام: 76","question":"هل كان قول إبراهيم ﴿هذا ربي﴾ اعتقادًا أم افتراضًا في مقام المحاجة؟","answer":"لم يكن قوله ﴿هذا ربي﴾ اعتقادًا بالشرك، بل افتراضًا حجاجيًا جارى به قومه ليبطل قولهم من داخله؛ يدل عليه أفوله ثم تصريحه بالبراءة والتوجه إلى الفاطر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص196–207.","url":""}]},{"id":"s6-567","number":567,"surah":6,"verses":[76],"verseLabel":"الأنعام: 76","question":"لماذا أشار إلى الكوكب بالمذكر فقال: ﴿هذا ربي﴾؟","answer":"أشار بالمذكر لأن المشار إليه ﴿كوكب﴾ وهو مذكر، وجاء الخبر ﴿ربي﴾ موافقًا له؛ فالإشارة إلى الجرم المشاهد لا إلى لفظ مؤنث.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص196–207.","url":""}]},{"id":"s6-568","number":568,"surah":6,"verses":[76],"verseLabel":"الأنعام: 76","question":"لماذا جعل أفول الكوكب هو الحجة على بطلان ربوبيته؟","answer":"الأفول انتقال وغياب وتغير، ومن كان محكومًا بالحركة والاحتجاب لا يصلح أن يكون ربًا مدبرًا دائمًا؛ فاتخذ الصفة المشاهدة حجة يفهمها قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص196–207.","url":""}]},{"id":"s6-569","number":569,"surah":6,"verses":[76],"verseLabel":"الأنعام: 76","question":"ما سرّ التعبير في قوله تعالى: ﴿لا أحب الآفلين﴾، دون أن يقال: ليس هذا ربي؟","answer":"﴿لا أحب الآفلين﴾ ينقل الحجة من نفي ربوبية جرم واحد إلى قاعدة عامة: المعبود لا يكون غائبًا متغيرًا. وفي نفي المحبة إعلان أن القلب لا يتعلق بما يزول.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص196–207.","url":""}]},{"id":"s6-570","number":570,"surah":6,"verses":[76],"verseLabel":"الأنعام: 76","question":"لماذا جُمعت ﴿الآفلين﴾ مع أن المذكور كوكب واحد؟","answer":"جمع ﴿الآفلين﴾ ليعم الحكم الكوكب وكل ما يشاركه في الأفول؛ فالحجة لا تختص بالمشاهد الأول بل تبطل ربوبية جميع الأجرام المتغيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص196–207.","url":""}]},{"id":"s6-571","number":571,"surah":6,"verses":[77],"verseLabel":"الأنعام: 77","question":"لماذا وصف القمر بأنه ﴿بازغًا﴾، ولم يصف الكوكب بمثله؟","answer":"وُصف القمر بالبزوغ لأن طلوعه أوضح ونوره أعظم من الكوكب، فناسب إبراز ظهوره مرحلةً أقوى في الحجة؛ أما رؤية الكوكب فتكفي فيها تسميته من غير وصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص208–216.","url":""}]},{"id":"s6-572","number":572,"surah":6,"verses":[77],"verseLabel":"الأنعام: 77","question":"لماذا كرر: ﴿قال هذا ربي فلما أفل﴾؟","answer":"تكرر القول والأفول لتمثيل الحجة درجة بعد درجة؛ انتقل من الكوكب إلى القمر الأكبر، مجاريًا قومه حتى يقروا بأن كل آفل لا يصلح للربوبية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص208–216.","url":""}]},{"id":"s6-573","number":573,"surah":6,"verses":[77],"verseLabel":"الأنعام: 77","question":"لماذا انتقل بعد أفول القمر إلى الدعاء: ﴿لئن لم يهدني ربي﴾؟","answer":"بعد سقوط المرشح الثاني أعلن افتقاره إلى هداية ربه، ليبين أن النجاة من ضلال القوم ليست بقوة العقل وحده بل بتوفيق الله، وليمهد للبراءة النهائية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص208–216.","url":""}]},{"id":"s6-574","number":574,"surah":6,"verses":[77],"verseLabel":"الأنعام: 77","question":"ما سرّ التعبير في قوله تعالى: ﴿يهدني ربي﴾، دون أن يقال: يهدني الله؟","answer":"إضافة الرب إليه تشعر بالقرب والتربية والعناية؛ فهو يطلب الهداية ممن تولى أمره، في مقابل أجرام تأفل ولا ترعى عابدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص208–216.","url":""}]},{"id":"s6-575","number":575,"surah":6,"verses":[77],"verseLabel":"الأنعام: 77","question":"لماذا أكد الجواب باللام والنون: ﴿لأكونن من القوم الضالين﴾؟","answer":"اللام موطئة للقسم ونون التوكيد الثقيلة تثبت الجواب؛ فبيّن أن انتفاء هداية الله يفضي حتمًا إلى الضلال، لا إلى احتمال متردد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص208–216.","url":""}]},{"id":"s6-576","number":576,"surah":6,"verses":[77],"verseLabel":"الأنعام: 77","question":"ما سرّ التعبير في قوله تعالى: ﴿من القوم الضالين﴾، دون أن يقال: ضالًا؟","answer":"﴿من القوم الضالين﴾ أبلغ من ﴿ضالًا﴾؛ لأنها تصور الدخول في جماعة استقر فيها الضلال، وتلمح إلى قومه الذين رأى طريقهم وعاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص208–216.","url":""}]},{"id":"s6-577","number":577,"surah":6,"verses":[78],"verseLabel":"الأنعام: 78","question":"لماذا خُصّت الشمس بقوله: ﴿هذا أكبر﴾؟","answer":"الشمس أكبر الأجرام الثلاثة في الحس وأشدها ضوءًا، فخصها بذلك ليبلغ افتراض قومه أقصى قوته؛ فإذا أفل الأكبر بطل ما دونه من باب أولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص217–225.","url":""}]},{"id":"s6-578","number":578,"surah":6,"verses":[78],"verseLabel":"الأنعام: 78","question":"ما سرّ التعبير في قوله تعالى عن الشمس المؤنثة: ﴿هذا ربي﴾ لا ﴿هذه﴾؟","answer":"ذُكر اسم الإشارة مراعاةً للمشار إليه بمعنى الجرم أو الطالع، وقيل لمراعاة الخبر المذكر ﴿ربي﴾؛ فالمقصود محاكاة دعواهم لا تأنيث لفظ الشمس.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص217–225.","url":""}]},{"id":"s6-579","number":579,"surah":6,"verses":[78],"verseLabel":"الأنعام: 78","question":"ما سرّ التعبير في قوله تعالى في القمر ﴿أفل﴾ وفي الشمس ﴿أفلت﴾؟","answer":"جاء ﴿أفل﴾ مع القمر لمراعاة تذكيره، و﴿أفلت﴾ مع الشمس لمراعاة تأنيثها اللفظي؛ فاختلاف الصيغة موافق لاختلاف الاسمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص217–225.","url":""}]},{"id":"s6-580","number":580,"surah":6,"verses":[78],"verseLabel":"الأنعام: 78","question":"لماذا نادى قومه عند أفول الشمس: ﴿يا قوم﴾ ولم ينادهم في المرحلتين السابقتين؟","answer":"نادى قومه عند اكتمال التجربة وظهور النتيجة ليعلن الحكم العام أمامهم؛ أما المرحلتان السابقتان فكانتا تمهيدًا متدرجًا للمحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص217–225.","url":""}]},{"id":"s6-581","number":581,"surah":6,"verses":[78],"verseLabel":"الأنعام: 78","question":"ما سرّ التعبير في قوله تعالى: ﴿إني بريء مما تشركون﴾ بالاسم، لا: أتبرأ؟","answer":"الاسم ﴿بريء﴾ يدل على ثبوت البراءة واستقرارها، لا على فعل يتجدد مرة؛ فهو إعلان قاطع لانفصاله عن الشرك وأهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص217–225.","url":""}]},{"id":"s6-582","number":582,"surah":6,"verses":[78],"verseLabel":"الأنعام: 78","question":"ما سرّ التعبير في قوله تعالى: ﴿مما تشركون﴾، ولم يسم الشمس والقمر والكوكب؟","answer":"الموصول ﴿ما تشركون﴾ يعم الشمس والقمر والكوكب وسائر الشركاء، ويجعل العلة فعل الإشراك نفسه لا أسماء معبودات بعينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص217–225.","url":""}]},{"id":"s6-583","number":583,"surah":6,"verses":[79],"verseLabel":"الأنعام: 79","question":"ما سرّ التعبير في قوله تعالى: ﴿إني وجهت وجهي﴾، فكرر مادة الوجه؟","answer":"تكرار مادة الوجه يجانس بين الفعل ومتعلقه ويؤكد تمام القصد: صرفت وجهي كله وجهة واحدة، فلا التفات فيه إلى معبود آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص226–233.","url":""}]},{"id":"s6-584","number":584,"surah":6,"verses":[79],"verseLabel":"الأنعام: 79","question":"لماذا عبّر بالوجه عن الذات كلها؟","answer":"الوجه أشرف ما يظهر من الإنسان وبه تعرف وجهته، فعبّر به عن الذات والقصد كله؛ أي أخلصت كياني وعبادتي لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص226–233.","url":""}]},{"id":"s6-585","number":585,"surah":6,"verses":[79],"verseLabel":"الأنعام: 79","question":"لماذا وصف الله بأنه ﴿الذي فطر السماوات والأرض﴾ في ختام محاجة الكواكب؟","answer":"وصفه بالفاطر لأن من ابتدأ خلق السماوات والأرض هو رب الأجرام كلها، فلا يكون شيء مخلوق فيها ندًا لخالقها؛ وبه ختمت محاجة الأفول بدليل الأصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص226–233.","url":""}]},{"id":"s6-586","number":586,"surah":6,"verses":[79],"verseLabel":"الأنعام: 79","question":"ما سرّ التعبير في قوله تعالى: ﴿حنيفًا﴾، وما الصورة التي تحملها مادة الحنف؟","answer":"الحنف ميل عن الاعوجاج إلى الاستقامة؛ فـ﴿حنيفًا﴾ يصور إبراهيم مائلًا عن الشرك كله، متجهًا بقصد واحد إلى التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص226–233.","url":""}]},{"id":"s6-587","number":587,"surah":6,"verses":[79],"verseLabel":"الأنعام: 79","question":"لماذا جاء ﴿حنيفًا﴾ مفردًا منصوبًا بعد ﴿وجهت وجهي﴾؟","answer":"﴿حنيفًا﴾ حال من فاعل ﴿وجهت﴾، فبين هيئة إبراهيم وقت توجيه وجهه؛ وجاء مفردًا لأنه وصف للمتكلم الواحد، ومنصوبًا لأنه حال.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص226–233.","url":""}]},{"id":"s6-588","number":588,"surah":6,"verses":[79],"verseLabel":"الأنعام: 79","question":"ما سرّ التعبير في قوله تعالى: ﴿وما أنا من المشركين﴾ بالجملة الاسمية، دون أن يقال: ولا أشرك؟","answer":"الجملة الاسمية تنفي عنه الثبات في جنس المشركين نفيًا مستمرًا، وهي أبلغ من نفي فعل إشراك عارض؛ فجمعت التوحيد والبراءة الدائمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص226–233.","url":""}]},{"id":"s6-589","number":589,"surah":6,"verses":[80],"verseLabel":"الأنعام: 80","question":"لماذا عبّر عن مجادلة قومه بقوله: ﴿وحاجه قومه﴾؟","answer":"المحاجة مقابلة الحجة بالحجة؛ فالتعبير يصور قومه يخاصمونه بما يعدونه دليلًا، ثم يرد عليهم ببرهان الهداية والأمن، وإن كانت حجتهم باطلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص234–247.","url":""}]},{"id":"s6-590","number":590,"surah":6,"verses":[80],"verseLabel":"الأنعام: 80","question":"ما سرّ التعبير في قوله تعالى: ﴿أتحاجوني في الله وقد هدان﴾، فجعل الهداية جوابًا للمحاجة؟","answer":"هداية الله بينة واقعة في نفسه، فلا معنى لمحاجته في ربه بعد أن أوصله إلى اليقين؛ والجملة تقابل دعواهم النظرية بتجربة هداية محققة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص234–247.","url":""}]},{"id":"s6-591","number":591,"surah":6,"verses":[80],"verseLabel":"الأنعام: 80","question":"ما سرّ التعبير في قوله تعالى: ﴿في الله﴾، لا: في وجود الله أو وحدانيته؟","answer":"﴿في الله﴾ أوجز وأشمل من تقييد المحاجة بوجوده أو وحدانيته؛ فهي تتناول ذاته وربوبيته واستحقاقه العبادة وكل ما جادلوا فيه من شأنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص234–247.","url":""}]},{"id":"s6-592","number":592,"surah":6,"verses":[80],"verseLabel":"الأنعام: 80","question":"لماذا عبّر بالماضي: ﴿وقد هدان﴾؟","answer":"الماضي مع ﴿قد﴾ يحقق وقوع الهداية وثبوتها؛ فهي نعمة حصلت واستقرت، فلا تزعزعها محاجة قومه ولا تخويفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص234–247.","url":""}]},{"id":"s6-593","number":593,"surah":6,"verses":[80],"verseLabel":"الأنعام: 80","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا أخاف ما تشركون به﴾، لا: لا أخاف آلهتكم؟","answer":"الموصول ﴿ما تشركون به﴾ يعم كل معبود جعلوه شريكًا، ويكشف سبب بطلان الخوف منه وهو إشراكهم إياه بالله، بدل أن يشرفه باسم الآلهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص234–247.","url":""}]},{"id":"s6-594","number":594,"surah":6,"verses":[80],"verseLabel":"الأنعام: 80","question":"لماذا استثنى بقوله: ﴿إلا أن يشاء ربي شيئًا﴾ بعد نفي الخوف؟","answer":"الاستثناء يرد القدرة والمشيئة كلها إلى الله؛ فلا يخاف شركاءهم استقلالًا، وإنما قد يقع شيء إن شاءه ربه. وفيه كمال التوحيد والأدب مع القدرة الإلهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص234–247.","url":""}]},{"id":"s6-595","number":595,"surah":6,"verses":[80],"verseLabel":"الأنعام: 80","question":"لماذا نُكّر ﴿شيئًا﴾ بعد مشيئة الرب؟","answer":"نُكر ﴿شيئًا﴾ للعموم؛ أي أي شيء شاءه الله قل أو عظم، فلا يخرج ممكن عن مشيئته، ولا يدل وقوعه على قدرة الشركاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص234–247.","url":""}]},{"id":"s6-596","number":596,"surah":6,"verses":[80],"verseLabel":"الأنعام: 80","question":"ما سرّ التعبير في قوله تعالى: ﴿وسع ربي كل شيء علمًا﴾، فجعل العلم واسعًا محيطًا؟","answer":"اختير فعل ﴿وسع﴾ لأنه أشمل من مجرد الإحاطة، ولأن المقام يبين تعلق علم الله بجميع العوالم. ونصب ﴿علمًا﴾ على التمييز يجعل سعة العلم علة للحكم والتدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص234–247.","url":""}]},{"id":"s6-597","number":597,"surah":6,"verses":[80],"verseLabel":"الأنعام: 80","question":"ما سرّ التعبير في قوله تعالى: ﴿أفلا تتذكرون﴾، لا: تتفكرون؟","answer":"اختير التذكر لأن بطلان عبادة ما لا يضر ولا ينفع أمر مركوز في العقول، فلا يحتاج إلى إنشاء نظر جديد بقدر حاجته إلى إيقاظ ما غفلوا عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص234–247.","url":""}]},{"id":"s6-598","number":598,"surah":6,"verses":[80],"verseLabel":"الأنعام: 80","question":"ما سرّ التعبير في قوله تعالى عن قوم إبراهيم: ﴿وحاجه قومه﴾، بينما يكثر التعبير عن الخصومة الباطلة بـ﴿يجادلون﴾؟","answer":"المحاجة مراجعة الحجة بالحجة، والمقصود فيها ظهور الحجة؛ أما الجدال فيغلب عليه قصد إلزام الخصم ومغالبته، وقد يستعمل في الخصومة. فناسب ﴿حاجه قومه﴾ مقام تبادل الحجج حول توحيد الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص279.","url":""}]},{"id":"s6-599","number":599,"surah":6,"verses":[81],"verseLabel":"الأنعام: 81","question":"لماذا بدأ بقوله: ﴿وكيف أخاف ما أشركتم ولا تخافون﴾؟","answer":"الاستفهام بـ﴿كيف﴾ للتعجب والإنكار من أصل تصور خوفه من معبوداتهم، وهو أبلغ من مجرد نفي الخوف؛ إذ ينفي كل كيفية يمكن أن يقع بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص248–257.","url":""}]},{"id":"s6-600","number":600,"surah":6,"verses":[81],"verseLabel":"الأنعام: 81","question":"لماذا نسب الشرك إليهم: ﴿ما أشركتم﴾؟","answer":"نسب الشرك إليهم لبيان أنهم هم الذين أحدثوا هذه النسبة الباطلة من غير حجة، وفيه تحميلهم تبعة اختيارهم مع تحقير المعبودات بلفظ ﴿ما﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص248–257.","url":""}]},{"id":"s6-601","number":601,"surah":6,"verses":[81],"verseLabel":"الأنعام: 81","question":"ما سرّ التعبير في قوله تعالى: ﴿أشركتم بالله ما لم ينزل به عليكم سلطانًا﴾، فجعل البرهان سلطانًا؟","answer":"السلطان أصله القوة والقهر، وسميت الحجة سلطانًا لأن الحق يقهر الباطل ويتسلط على القلوب والعقول بقوة بيانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص248–257.","url":""}]},{"id":"s6-602","number":602,"surah":6,"verses":[81],"verseLabel":"الأنعام: 81","question":"ما سرّ التعبير في قوله تعالى: ﴿لم ينزل به عليكم سلطانًا﴾، مع أن الحجة عقلية لا جسم ينزل؟","answer":"عبر بالإنزال لأن الحجة المعتبرة في أمر العبادة لا تكون إلا بإذن من الله ووحي منه؛ فنفى أن يكون قد نزل عليهم أي مستند يجيز الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص248–257.","url":""}]},{"id":"s6-603","number":603,"surah":6,"verses":[81],"verseLabel":"الأنعام: 81","question":"لماذا نُكّر ﴿سلطانًا﴾ في سياق النفي؟","answer":"نُكر ﴿سلطانًا﴾ في سياق النفي لاستغراق الجنس؛ أي لم ينزل لهم أي حجة، مهما دقت أو عظمت، تثبت ما زعموه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص248–257.","url":""}]},{"id":"s6-604","number":604,"surah":6,"verses":[81],"verseLabel":"الأنعام: 81","question":"لماذا انتقل من الخوف إلى سؤال الأمن: ﴿فأي الفريقين أحق بالأمن﴾؟","answer":"انتقل من نفي الخوف إلى الأمن ليقلب حجتهم عليهم: من يعبد بلا برهان هو الجدير بالخوف، أما الموحد فله سبب الأمن. فصار السؤال حاكمًا بين الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص248–257.","url":""}]},{"id":"s6-605","number":605,"surah":6,"verses":[81],"verseLabel":"الأنعام: 81","question":"ما سرّ التعبير في قوله تعالى: ﴿الفريقين﴾، دون أن يقال: أنا وأنتم؟","answer":"عبر بـ﴿الفريقين﴾ بدل «أنا وأنتم» على طريقة المنصف الذي يعرض القضية كحكم عام، فيستدرج المخالف إلى النظر بعيدًا عن المكابرة الشخصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص248–257.","url":""}]},{"id":"s6-606","number":606,"surah":6,"verses":[81],"verseLabel":"الأنعام: 81","question":"ما سرّ التعبير في قوله تعالى: ﴿أحق بالأمن﴾ بصيغة التفضيل؟","answer":"جاء ﴿أحق﴾ بصيغة التفضيل على أسلوب الإنصاف في المحاورة، كأن الأمن مفترض للفريقين ثم يطلب تعيين الأجدر به؛ ليكون إلزام الخصم أبلغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص248–257.","url":""}]},{"id":"s6-607","number":607,"surah":6,"verses":[81],"verseLabel":"الأنعام: 81","question":"لماذا خُتم السؤال بـ﴿إن كنتم تعلمون﴾؟","answer":"جيء بـ﴿إن﴾ للإشعار بأن علمهم غير متحقق أو غير راجح؛ فهم بين الجهل والتجاهل. وجواب الشرط محذوف، أي: إن كنتم تعلمون فأخبروني، حثًا لهم على الجواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص248–257.","url":""}]},{"id":"s6-608","number":608,"surah":6,"verses":[82],"verseLabel":"الأنعام: 82","question":"لماذا جاء الجواب بصفة عامة: ﴿الذين آمنوا﴾، ولم يقل: إبراهيم ومن اتبعه؟","answer":"جاء الجواب عامًا بـ﴿الذين آمنوا﴾ ليقرر قاعدة لا تختص بإبراهيم: الأمن لكل من جمع الإيمان الخالص وترك خلطه بالظلم. والموصول يبين سبب استحقاقهم الأمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص257–267.","url":""}]},{"id":"s6-609","number":609,"surah":6,"verses":[82],"verseLabel":"الأنعام: 82","question":"ما سرّ التعبير في قوله تعالى: ﴿ولم يلبسوا إيمانهم بظلم﴾، فصوّر الظلم لباسًا يختلط بالإيمان؟","answer":"اللبس هو الخلط والتغطية؛ فصور إدخال الظلم على الإيمان بمزج يفسد صفاءه ويستر أثره، كما يلتبس الشيء بغيره فلا يتميز.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص257–267.","url":""}]},{"id":"s6-610","number":610,"surah":6,"verses":[82],"verseLabel":"الأنعام: 82","question":"لماذا نُكّر ﴿ظلم﴾، وهل المراد كل ظلم أم الشرك؟","answer":"المراد بالظلم هنا الشرك، كما يفسره قوله تعالى: ﴿إن الشرك لظلم عظيم﴾. وتنكيره يعظم شأنه ويعم كل صورة من صور الشرك التي تفسد خلوص الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص257–267.","url":""}]},{"id":"s6-611","number":611,"surah":6,"verses":[82],"verseLabel":"الأنعام: 82","question":"ما سرّ التعبير في قوله تعالى: ﴿أولئك لهم الأمن﴾ بتقديم ﴿لهم﴾؟","answer":"قُدم ﴿لهم﴾ للاختصاص والعناية؛ فالأمن الحق ثابت لهؤلاء دون من خلط إيمانه بالشرك، وهو جواب مباشر لسؤال: أي الفريقين أحق بالأمن؟","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص257–267.","url":""}]},{"id":"s6-612","number":612,"surah":6,"verses":[82],"verseLabel":"الأنعام: 82","question":"لماذا عُرّف ﴿الأمن﴾؟","answer":"عُرّف ﴿الأمن﴾ للدلالة على الأمن المعهود في السؤال السابق، وعلى كمال جنسه: أمن القلب في الدنيا والنجاة من الخلود في العذاب في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص257–267.","url":""}]},{"id":"s6-613","number":613,"surah":6,"verses":[82],"verseLabel":"الأنعام: 82","question":"ما سرّ التعبير في قوله تعالى: ﴿وهم مهتدون﴾ بالاسم، دون أن يقال: ويهتدون؟","answer":"الجملة الاسمية تدل على ثبوت اهتدائهم ودوامه، لا على حدوث عابر؛ فمن خلص إيمانه استقر على الهدى ولم يكن اهتداؤه مؤقتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص257–267.","url":""}]},{"id":"s6-614","number":614,"surah":6,"verses":[83],"verseLabel":"الأنعام: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿وتلك حجتنا﴾ باسم الإشارة للبعيد؟","answer":"أشير إلى الحجة باسم البعيد تعظيمًا لشأنها ورفعة منزلتها، مع استحضار ما سبق من وجوه البرهان كأنه أمر متميز مشاهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص268–279.","url":""}]},{"id":"s6-615","number":615,"surah":6,"verses":[83],"verseLabel":"الأنعام: 83","question":"لماذا أضيفت الحجة إلى الله: ﴿حجتنا﴾، مع أن إبراهيم هو الذي نطق بها؟","answer":"أضيفت الحجة إلى الله لأنها بتعليمه وتوفيقه وإيتائه، وإن جرت على لسان إبراهيم؛ فمصدر نورها وقوتها من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص268–279.","url":""}]},{"id":"s6-616","number":616,"surah":6,"verses":[83],"verseLabel":"الأنعام: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿آتيناها إبراهيم﴾، فجعل الحجة عطاء؟","answer":"التعبير بالإيتاء يجعل الحجة نعمة موهوبة من الله لا ثمرة استقلال بشري؛ وفيه بيان فضل الله على إبراهيم بالعلم والبيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص268–279.","url":""}]},{"id":"s6-617","number":617,"surah":6,"verses":[83],"verseLabel":"الأنعام: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿على قومه﴾، وما دلالة ﴿على﴾؟","answer":"تفيد ﴿على﴾ الاستعلاء؛ فقد علت حجة إبراهيم حجج قومه وغلبتها، فكانت له منزلة الانتصار بالحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص268–279.","url":""}]},{"id":"s6-618","number":618,"surah":6,"verses":[83],"verseLabel":"الأنعام: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿نرفع درجات من نشاء﴾، وجمع الدرجات؟","answer":"جُمعت الدرجات لتفاوت مراتب الرفعة وتعددها: إيمان وعلم وحكمة وحجة، ولكثرة من تشملهم مشيئة الله، فلكل مرفوع درجة تناسب فضله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص268–279.","url":""}]},{"id":"s6-619","number":619,"surah":6,"verses":[83],"verseLabel":"الأنعام: 83","question":"لماذا خُتمت الآية بـ﴿إن ربك حكيم عليم﴾؟","answer":"ناسب الختام أن رفع الدرجات واقع بحكمة تضع الفضل موضعه، وبعلم بمن يستحقه وبمقادير أحوال العباد؛ فلا يكون الرفع اعتباطًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص268–279.","url":""}]},{"id":"s6-620","number":620,"surah":6,"verses":[83],"verseLabel":"الأنعام: 83","question":"ما سرّ التعبير هنا في قوله تعالى ﴿حكيم عليم﴾، وفي الآية 73 ﴿الحكيم الخبير﴾؟","answer":"جاء ﴿حكيم عليم﴾ هنا لأن المقام مقام إيتاء الحجة ورفع الدرجات، وذلك يحتاج إلى حكمة في الوضع وعلم بالاستحقاق. أما ﴿الحكيم الخبير﴾ في الآية 73 فجاءت بعد ذكر الغيب والشهادة، فناسبها الخبير بدقائق الظاهر والباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص268–279.","url":""}]},{"id":"s6-621","number":621,"surah":6,"verses":[84],"verseLabel":"الأنعام: 84","question":"ما سرّ التعبير في قوله تعالى: ﴿ووهبنا له إسحاق ويعقوب﴾، فجعل الابن والحفيد هبة واحدة؟","answer":"الهبة عطاء بلا عوض؛ وقد جمع إسحاق ويعقوب لأن نعمة الذرية امتدت إلى الابن والحفيد، ثم أكد تمام الهبة بقوله ﴿كلًا هدينا﴾؛ فالذرية لا تكمل نعمتها إلا بالصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص280–294.","url":""}]},{"id":"s6-622","number":622,"surah":6,"verses":[84],"verseLabel":"الأنعام: 84","question":"ما سرّ تقديم إسحاق ويعقوب على نوح مع أن نوحًا أسبق زمنًا؟","answer":"قُدم إسحاق ويعقوب لاتصالهما المباشر بإبراهيم الذي يساق الكلام في إنعام الله عليه، ثم استؤنف بنوح السابق زمنًا لبيان تأصل الهداية في أصول هذه السلسلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص280–294.","url":""}]},{"id":"s6-623","number":623,"surah":6,"verses":[84],"verseLabel":"الأنعام: 84","question":"ما سرّ التعبير في قوله تعالى: ﴿كلًّا هدينا﴾ ثم كرر: ﴿ونوحًا هدينا من قبل﴾؟","answer":"قوله ﴿كلًا هدينا﴾ يثبت تمام النعمة في إسحاق ويعقوب، ثم أفرد نوحًا بالهداية مع ﴿من قبل﴾ للتنبيه على سبق زمنه وتأصل طريق الهداية قبل إبراهيم وذريته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص280–294.","url":""}]},{"id":"s6-624","number":624,"surah":6,"verses":[84],"verseLabel":"الأنعام: 84","question":"إلى من يعود الضمير في ﴿ومن ذريته﴾: إلى إبراهيم أم نوح؟","answer":"يعيد السياق الضمير في ﴿ومن ذريته﴾ إلى إبراهيم للتنويه بشرف ذريته واستمرار الهداية فيها، وقيل: يعود إلى نوح لقرب ذكره ولدخول لوط في ذريته بلا إشكال. فالموضع محتمل، ولا يصح الجزم بوجه واحد دون ذكر الخلاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص280–294.","url":""}]},{"id":"s6-625","number":625,"surah":6,"verses":[84],"verseLabel":"الأنعام: 84","question":"لماذا بدأ من الذرية بداود وسليمان؟","answer":"بدأ بداود وسليمان لأنهما زوج يجمع النبوة والملك مع علاقة الأب والابن، ثم نُظمت الأسماء في مجموعات تقوم على مناسبات كالحكم والابتلاء والقرابة، لا على التسلسل الزمني.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص280–294.","url":""}]},{"id":"s6-626","number":626,"surah":6,"verses":[84],"verseLabel":"الأنعام: 84","question":"لماذا خُتمت قائمة هذه الآية بقوله: ﴿وكذلك نجزي المحسنين﴾؟","answer":"وسع قوله ﴿وكذلك نجزي المحسنين﴾ الحكم بعد ذكر الأنبياء؛ فمثل جزائهم على الإحسان يجري لكل محسن، وفيه ربط الهداية والإكرام بالإحسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص280–294.","url":""}]},{"id":"s6-627","number":627,"surah":6,"verses":[84],"verseLabel":"الأنعام: 84","question":"لماذا اختلف ترتيب أسماء الأنبياء في الأنعام: 84–86 عن ترتيبهم في النساء: 163، ولم يُرتبوا زمنيًا؟","answer":"ترتيب الأنعام تابع لمقام تعداد ذرية إبراهيم ومراتب الهداية، فجمع الأنبياء بحسب مناسبات الملك والابتلاء والصلاح وتنوع الرسالات. أما النساء فسياقها وحدة الوحي والرد على أهل الكتاب؛ لذلك بدأ بنوح ثم ذكر أصحاب الكتب ووجوه الوحي، فالترتيبان موضوعيان لا زمنيان.","sources":[{"label":"ابن جماعة، كشف المعاني في المتشابه من المثاني، ص144؛ وموسوعة التفسير البلاغي، ج11، ص280–302.","url":""}]},{"id":"s6-628","number":628,"surah":6,"verses":[85],"verseLabel":"الأنعام: 85","question":"لماذا جُمِع زكريا ويحيى وعيسى وإلياس في آية واحدة؟","answer":"راعى الترتيب أكثر من مناسبة: زكريا قبل يحيى لأنه أبوه، وهما قبل عيسى لقرب الزمن، وقُدم عيسى على إلياس لأنه صاحب كتاب. وجمع الأربعة وصف الصلاح والزهد عن زخارف الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص295–297.","url":""}]},{"id":"s6-629","number":629,"surah":6,"verses":[85],"verseLabel":"الأنعام: 85","question":"ما سرّ التعبير في قوله تعالى: ﴿كل من الصالحين﴾، دون أن يقال: كلهم صالحون؟","answer":"قوله ﴿كل من الصالحين﴾ يثبت دخول كل واحد منهم على انفراده في زمرة الصالحين، فـ﴿من﴾ تبين الجنس أو التبعيض في جماعة عظيمة، وهو أبلغ من خبر جمعي مجمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص295–297.","url":""}]},{"id":"s6-630","number":630,"surah":6,"verses":[86],"verseLabel":"الأنعام: 86","question":"لماذا جُمِع إسماعيل واليسع ويونس ولوط في نسق واحد؟","answer":"هذه المجموعة تكمل أصناف الأنبياء بعد أصحاب الملك والحكم وأهل الزهد الشديد؛ فجمعت رسلًا تنوعت أقوامهم وأحوال دعوتهم، واتحدوا في أصل الهداية والرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص298–302.","url":""}]},{"id":"s6-631","number":631,"surah":6,"verses":[86],"verseLabel":"الأنعام: 86","question":"ما سرّ التعبير في قوله تعالى: ﴿وكلًّا فضلنا على العالمين﴾ بعد قوله سابقًا ﴿كلًّا هدينا﴾؟","answer":"الهداية في ﴿كلًا هدينا﴾ أصل التوفيق إلى الحق، أما التفضيل فهو زيادة المنزلة والاصطفاء بعد الهداية؛ فانتقل من إثبات الأصل إلى بيان رفعة قدرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص298–302.","url":""}]},{"id":"s6-632","number":632,"surah":6,"verses":[86],"verseLabel":"الأنعام: 86","question":"لماذا عُمّم تفضيل كل واحد منهم على ﴿العالمين﴾؟","answer":"المراد تفضيل كل نبي على عالمي زمانه أو على من عدا الأنبياء، لا تفضيل كل واحد على جميع الأنبياء الآخرين؛ فالتعميم مقيد بما يليق بمقام النبوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص298–302.","url":""}]},{"id":"s6-633","number":633,"surah":6,"verses":[87],"verseLabel":"الأنعام: 87","question":"لماذا عطف الآباء والذريات والإخوان بعد تسمية الأنبياء؟","answer":"عطف الآباء والذريات والإخوان لتوسيع دائرة الاجتباء بعد الأنبياء المسمين، وبيان أن الهداية امتدت إلى الصالحين من جهات القرابة كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص303–309.","url":""}]},{"id":"s6-634","number":634,"surah":6,"verses":[87],"verseLabel":"الأنعام: 87","question":"لماذا جُمعت ﴿آبائهم وذرياتهم وإخوانهم﴾، وحُذف بيان من اصطفى منهم؟","answer":"جُمعت الجهات الثلاث لاستيعاب أصول القرابة وفروعها ونظرائها، وحذف بيان المفعول منهم لأن ﴿واجتبيناهم﴾ يدل على أن المصطفى بعضهم لا جميع كل أب وذرية وأخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص303–309.","url":""}]},{"id":"s6-635","number":635,"surah":6,"verses":[87],"verseLabel":"الأنعام: 87","question":"ما سرّ التعبير في قوله تعالى: ﴿واجتبيناهم﴾، دون أن يقال: اخترناهم؟","answer":"الاجتباء جمع على طريق الاصطفاء مع تخصيص العبد بفيض من النعم من غير سعي سابق؛ وهو أنسب لجماعة مختارة جمعها الله بعد اصطفائها، وأخص من مطلق الاختيار.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص303–309.","url":""}]},{"id":"s6-636","number":636,"surah":6,"verses":[87],"verseLabel":"الأنعام: 87","question":"ما سرّ التعبير في قوله تعالى: ﴿وهديناهم إلى صراط مستقيم﴾ بعد إثبات الاجتباء؟","answer":"الاجتباء يبين اختيار الأشخاص، ثم جاءت الهداية لتبين الطريق الذي سلكوه والغاية التي أوصلوا إليها؛ فلا يكفي الاصطفاء بلا تثبيت على الصراط.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص303–309.","url":""}]},{"id":"s6-637","number":637,"surah":6,"verses":[87],"verseLabel":"الأنعام: 87","question":"لماذا نُكّر ﴿صراط مستقيم﴾ هنا، وعُرّف في مواضع أخرى؟","answer":"نُكّر ﴿صراط﴾ للتفخيم، ووصفه بـ﴿مستقيم﴾ تصريحًا بكمال استقامته، مع أن أصل معنى الصراط يوحي بالطريق الواضح؛ فجمع التنكير والوصف تعظيم الطريق وتأكيد سلامته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص303–309.","url":""}]},{"id":"s6-638","number":638,"surah":6,"verses":[88],"verseLabel":"الأنعام: 88","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلك هدى الله﴾ باسم الإشارة للبعيد؟","answer":"اسم الإشارة للبعيد يرفع منزلة مجموع الهدايات السابقة، ويجعلها لشدة ظهورها وتميزها كأنها مشاهد يشار إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص310–321.","url":""}]},{"id":"s6-639","number":639,"surah":6,"verses":[88],"verseLabel":"الأنعام: 88","question":"لماذا أضيف الهدى إلى الله: ﴿هدى الله﴾؟","answer":"أضيف الهدى إلى الله لتعظيمه وتشريفه، ولبيان اختصاص التوفيق الحقيقي به؛ فما ناله الأنبياء ليس مستقلًا عن مشيئته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص310–321.","url":""}]},{"id":"s6-640","number":640,"surah":6,"verses":[88],"verseLabel":"الأنعام: 88","question":"ما سرّ التعبير في قوله تعالى: ﴿يهدي به من يشاء من عباده﴾، وإلى ماذا يعود ﴿به﴾؟","answer":"يعود الضمير في ﴿به﴾ إلى هدى الله المذكور، أي بهذا الهدى يوفق من يشاء. فجعل الهدى سببًا موصلًا، مع بقاء التوفيق متعلقًا بالمشيئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص310–321.","url":""}]},{"id":"s6-641","number":641,"surah":6,"verses":[88],"verseLabel":"الأنعام: 88","question":"لماذا قُيّدت المشيئة بقوله: ﴿من عباده﴾؟","answer":"قوله ﴿من عباده﴾ يذكر أن المهديين مع علو منزلتهم عبيد لله، ويشرفهم بالإضافة إليه، ويبين أن الاختيار فضل يقع في دائرة عبوديته لا استحقاقًا مستقلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص310–321.","url":""}]},{"id":"s6-642","number":642,"surah":6,"verses":[88],"verseLabel":"الأنعام: 88","question":"لماذا افترض الشرك في حق الأنبياء: ﴿ولو أشركوا لحبط عنهم﴾؟","answer":"ذكر الشرك في حق الأنبياء على سبيل الفرض الممتنع ليقرر قاعدة لا تحابي أحدًا: لو وقع الشرك ممن علت منزلته لحبط عمله؛ فكيف بغيره؟ وفيه تغليظ شأن الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص310–321.","url":""}]},{"id":"s6-643","number":643,"surah":6,"verses":[88],"verseLabel":"الأنعام: 88","question":"ما سرّ التعبير في قوله تعالى: ﴿لحبط عنهم ما كانوا يعملون﴾، وعدّى الحبوط بـ﴿عن﴾؟","answer":"الحبوط فساد العمل وذهاب أثره، وتعديته بـ﴿عن﴾ تصور انفصال الأعمال عن أصحابها وذهاب نفعها عنهم، فلا تبقى لهم ثمرة يعتمدون عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص310–321.","url":""}]},{"id":"s6-644","number":644,"surah":6,"verses":[89],"verseLabel":"الأنعام: 89","question":"لماذا وصف الأنبياء بثلاثة أشياء: ﴿الكتاب والحكم والنبوة﴾؟","answer":"الكتاب هو الوحي المتلو والشريعة، والحكم فهمها والفصل بها، والنبوة منزلة الاصطفاء والتلقي عن الله؛ فاجتمعت أصول البلاغ والعلم والولاية النبوية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص322–332.","url":""}]},{"id":"s6-645","number":645,"surah":6,"verses":[89],"verseLabel":"الأنعام: 89","question":"ما سرّ تقديم ﴿الكتاب﴾ على ﴿الحكم والنبوة﴾؟","answer":"قُدم الكتاب لأن السياق مقبل على مناقشة منكري إنزال الوحي، ولأنه الأصل الظاهر الذي يتلقى منه الحكم وتظهر به حجة النبوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص322–332.","url":""}]},{"id":"s6-646","number":646,"surah":6,"verses":[89],"verseLabel":"الأنعام: 89","question":"لماذا أشار إلى كفار مكة بقوله: ﴿فإن يكفر بها هؤلاء﴾؟","answer":"اسم الإشارة ﴿هؤلاء﴾ يستحضر كفار مكة الحاضرين ويصغر شأن اعتراضهم أمام موكب الأنبياء، ويبين أن كفرهم لا يوقف أمر الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص322–332.","url":""}]},{"id":"s6-647","number":647,"surah":6,"verses":[89],"verseLabel":"الأنعام: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿فقد وكلنا بها قومًا﴾، فجعل الإيمان أمانة موكّلة؟","answer":"التوكيل هو إسناد الشيء إلى من يحفظه ويقوم به؛ فصور الإيمان بهذه الأصول أمانة قد أقام الله لها قومًا يحفظونها، فلا تضيع بكفر قوم آخرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص322–332.","url":""}]},{"id":"s6-648","number":648,"surah":6,"verses":[89],"verseLabel":"الأنعام: 89","question":"من هم ﴿قومًا ليسوا بها بكافرين﴾، ولماذا نُكّروا؟","answer":"يدخل في القوم الأنبياء المذكورون والمؤمنون الذين قاموا بالوحي، ومنهم المهاجرون والأنصار ومن تبعهم بإحسان. ونُكروا للتعظيم ولئلا يحصر حفظ الدين في جماعة نسبية واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص322–332.","url":""}]},{"id":"s6-649","number":649,"surah":6,"verses":[89],"verseLabel":"الأنعام: 89","question":"لماذا دخلت الباء على ﴿بكافرين﴾؟","answer":"الباء زائدة في خبر ﴿ليس﴾ لتوكيد النفي؛ أي ثبت أنهم منزّهون عن الكفر بها، متمسكون بالإيمان لا يتطرق إلى وصفهم شك.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص322–332.","url":""}]},{"id":"s6-650","number":650,"surah":6,"verses":[90],"verseLabel":"الأنعام: 90","question":"لماذا كرر الإشارة: ﴿أولئك الذين هدى الله﴾ بعد ﴿أولئك الذين آتيناهم﴾؟","answer":"الإشارة الأولى تجمع نعم الكتاب والحكم والنبوة، والثانية تستأنف الثناء بالهداية لتجعلها سبب الأمر بالاقتداء؛ فليست إعادة محضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص333–345.","url":""}]},{"id":"s6-651","number":651,"surah":6,"verses":[90],"verseLabel":"الأنعام: 90","question":"ما سرّ التعبير في قوله تعالى: ﴿فبهداهم اقتده﴾، دون أن يقال: فبهم اقتد؟","answer":"أُمر بالاقتداء بهداهم لا بأشخاصهم لأن الجامع المأمور باتباعه هو أصول توحيدهم وأخلاقهم وطرائق طاعتهم، لا الخصائص والشرائع التي قد تختلف بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص333–345.","url":""}]},{"id":"s6-652","number":652,"surah":6,"verses":[90],"verseLabel":"الأنعام: 90","question":"ما دلالة إضافة الهدى إلى ضمير الجمع في قوله تعالى: ﴿فبهداهم اقتده﴾ مع وحدة أصل الدين؟","answer":"لفظ ﴿هداهم﴾ ليس جمعًا لكلمة «هدى»، بل هو «هدى» مضاف إلى ضمير جماعة الأنبياء. والإضافة تجمع ما ظهر في كل واحد منهم من خصال الهدى، مع وحدة أصل الدين والتوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص333–345.","url":""}]},{"id":"s6-653","number":653,"surah":6,"verses":[90],"verseLabel":"الأنعام: 90","question":"لماذا جاءت هاء السكت في ﴿اقتده﴾؟","answer":"الهاء في ﴿اقتده﴾ هاء السكت، تثبت في الوقف، وقد ثبتت في رسم المصحف. وهي تهيئ وقفًا ظاهرًا على كلمة جامعة لمسيرة الأنبياء، فيزداد التنبيه إلى أهمية الاقتداء بهداهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص333–345.","url":""}]}]);
